window.RAFEQ_CORPUS=[{"id":"anatomy","year":1,"sem":1,"code":"BIOL 101aly","nAr":"التشريح ووظائف الأعضاء 1","nEn":"Human Anatomy & Physiology 1","bigAr":"ابدأ من البسيط إلى المعقد. المواد الكيميائية تكوّن الخلايا، والخلايا تكوّن الأنسجة، والأنسجة تبني الأعضاء، والأعضاء تعمل معًا في أجهزة مترابطة.","bigEn":"Anatomy explains body structure and location. Physiology explains how those structures work. Nursing becomes easier when students connect location, structure, function and what changes when function is disturbed.","chunksAr":[{"kind":"concept","title":"التشريح مقابل الفسيولوجيا","text":"التشريح يركز على بنية الجسم ومكان الأجزاء وعلاقاتها، أما الفسيولوجيا فتركز على كيفية عمل هذه الأجزاء والعمليات التي تؤدي وظائف الجسم."},{"kind":"content","title":"الصورة العامة للجسم","text":"ابدأ من البسيط إلى المعقد. المواد الكيميائية تكوّن الخلايا، والخلايا تكوّن الأنسجة، والأنسجة تبني الأعضاء، والأعضاء تعمل معًا في أجهزة مترابطة."},{"kind":"content","title":"Structure ↔ Function","text":"التركيب والوظيفة مرتبطان. شكل الخلية أو العضو وترتيبه غالبًا يساعده على أداء وظيفته."},{"kind":"content","title":"Homeostasis","text":"الجسم يحاول إبقاء الحرارة والسوائل والضغط والجلوكوز وغيرها ضمن حدود تسمح للخلايا بالعمل."},{"kind":"content","title":"Feedback","text":"التغذية الراجعة إحدى طرق التنظيم: تغير يحدث، الجسم يلاحظه، ثم يستجيب للمساعدة في الوصول إلى حالة مناسبة."},{"kind":"content","title":"Anatomical language","text":"مصطلحات الاتجاهات والمستويات والمناطق تمنع الغموض عندما نصف مكان عضو أو إصابة."},{"kind":"content","title":"Cells make tissues","text":"الخلايا المتخصصة تتجمع لتكوين أنسجة، والأنسجة المختلفة تتعاون داخل العضو الواحد."},{"kind":"content","title":"Systems interact","text":"أي جهاز يعتمد على أجهزة أخرى؛ لذلك لا تفكر في القلب أو الأعصاب أو الغدد كجزر منفصلة."},{"kind":"content","title":"لغة التشريح: أين يوجد الشيء؟","text":"الوضع التشريحي، الاتجاهات، مستويات القطع، مناطق الجسم والتجاويف هي اللغة التي تجعل وصف المكان دقيقًا ومفهومًا للجميع."},{"kind":"content","title":"الاتزان الداخلي","text":"الحياة تحتاج بيئة داخلية مستقرة نسبيًا. المستقبلات تلاحظ التغير، مركز التنظيم يقارن، ثم يحدث رد فعل يساعد على التصحيح."},{"kind":"content","title":"الكيمياء التي تسمح للحياة أن تحدث","text":"الماء، الأيونات، الأحماض والقواعد والجزيئات العضوية هي البيئة التي تجري فيها التفاعلات داخل الخلايا."},{"kind":"content","title":"الخلية: وحدة حية تعمل","text":"الغشاء ينظم ما يدخل ويخرج، النواة تحمل التعليمات الوراثية، والعضيات تؤدي وظائف متخصصة تحتاج إلى طاقة ومواد خام."},{"kind":"content","title":"النقل عبر الغشاء","text":"بعض المواد تتحرك حسب تدرج التركيز، وبعضها يحتاج بروتينات أو طاقة. حركة الماء مهمة لفهم السوائل والتورم والجفاف."},{"kind":"content","title":"الأنسجة: أربع عائلات أساسية","text":"الطلائي يغطي ويبطن، الضام يدعم ويربط، العضلي ينتج الحركة، والعصبي ينقل الإشارات. الأعضاء تجمع أكثر من نوع لتحقيق وظيفة واحدة."},{"kind":"content","title":"الالتهاب وإصلاح الأنسجة","text":"عندما يحدث ضرر تبدأ استجابة للحماية والتنظيف والإصلاح. الاحمرار والحرارة والتورم قد تكون أجزاء من هذه الاستجابة."},{"kind":"content","title":"الجهاز العصبي","text":"الخلايا العصبية تنقل المعلومات، والجهاز العصبي المركزي يعالجها، والأعصاب الطرفية تربط الجسم بالمراكز العصبية. توجد وظائف إرادية وأخرى ذاتية."},{"kind":"content","title":"القلب والأوعية","text":"القلب يولد قوة تدفع الدم، والأوعية توصل الدم إلى الأنسجة وتعيده. ضغط الدم وتدفقه يتأثران بقوة الضخ وحالة الأوعية والتنظيم العصبي."},{"kind":"content","title":"الدم","text":"البلازما تحمل المواد، كريات الدم الحمراء تنقل الغازات، الكريات البيضاء تشارك في الدفاع، والصفائح تسهم في الحد من فقدان الدم."},{"kind":"content","title":"الغدد الصماء","text":"الهرمونات رسائل كيميائية تنتقل في الدم وتؤثر في خلايا مستهدفة، فتشارك في تنظيم النمو والاستقلاب والجلوكوز وغيرها."},{"kind":"content","title":"الجهاز اللمفاوي","text":"يساعد على إعادة جزء من السائل بين الخلايا إلى الدورة الدموية، كما ترتبط مكوناته بالدفاع المناعي."},{"kind":"content","title":"🔬 عندما ترى نموذجًا أو شريحة أو صورة","text":"لا تسأل فقط «ما اسم هذا؟». اسأل ثلاث أسئلة تجعل الصورة تثبت في ذهنك:"},{"kind":"content","title":"دوار عند الوقوف","text":"تلاحظ تغيرًا في النبض أو الضغط بعد الانتقال من الاستلقاء إلى الوقوف."},{"kind":"content","title":"جرح حوله احمرار وتورم","text":"تربط العلامة باستجابة الأنسجة للضرر والالتهاب وبداية الإصلاح."},{"kind":"content","title":"ضعف حركة طرف","text":"تدرك أن الحركة والإحساس مرتبطان بمسارات عصبية وأن الملاحظة المنظمة مهمة."},{"kind":"content","title":"نتيجة تعداد دم","text":"عندما تعرف وظائف مكونات الدم تبدأ الأرقام في اكتساب معنى بدل أن تكون اختصارات فقط."},{"kind":"content","title":"تورم في الساق","text":"تعرف أن التورم يتعلق بحركة السوائل بين الأوعية والأنسجة، وأن الجهاز اللمفاوي جزء من الصورة."},{"kind":"content","title":"تعرق وتسارع نبض أثناء الخوف","text":"ترى كيف تظهر استجابة الجهاز العصبي الذاتي على أكثر من عضو في وقت واحد."}],"chunksEn":[{"kind":"concept","title":"Anatomy vs Physiology","text":"Anatomy focuses on body structures, locations and relationships; physiology focuses on how those structures work and the processes that produce body functions."},{"kind":"overview","title":"Human Anatomy & Physiology 1","text":"Anatomy explains body structure and location. Physiology explains how those structures work. Nursing becomes easier when students connect location, structure, function and what changes when function is disturbed."},{"kind":"content","title":"Structure ↔ Function","text":"Structure supports function."},{"kind":"content","title":"Homeostasis","text":"The body keeps internal conditions within workable ranges."},{"kind":"content","title":"Feedback","text":"Change is detected and regulatory responses follow."},{"kind":"content","title":"Anatomical language","text":"Directions, planes, regions and cavities make location precise."},{"kind":"content","title":"Cells & tissues","text":"Specialised cells form tissues that cooperate in organs."},{"kind":"content","title":"Systems interact","text":"No body system works in isolation."},{"kind":"content","title":"Anatomical language","text":"Anatomical position, directions, planes, regions and cavities."},{"kind":"content","title":"Homeostasis","text":"Receptors, control systems and responses help maintain suitable internal conditions."},{"kind":"content","title":"Chemistry of life","text":"Water, ions, acids, bases and organic molecules support cellular reactions."},{"kind":"content","title":"The cell","text":"Membranes regulate exchange; nuclei and organelles perform specialised roles."},{"kind":"content","title":"Membrane transport","text":"Gradients, carriers and energy-dependent transport help explain fluids and cellular balance."},{"kind":"content","title":"Tissue families","text":"Epithelial, connective, muscle and nervous tissues."},{"kind":"content","title":"Inflammation & repair","text":"Tissue damage triggers protective and repair responses."},{"kind":"content","title":"Nervous system","text":"Central and peripheral systems receive, process and coordinate responses."},{"kind":"content","title":"Heart & vessels","text":"Cardiac pumping and vascular function maintain circulation."},{"kind":"content","title":"Blood","text":"Plasma, red cells, white cells and platelets have distinct roles."},{"kind":"content","title":"Endocrine system","text":"Hormones regulate many body functions."},{"kind":"content","title":"Lymphatic system","text":"Fluid return and immune defence."},{"kind":"content","title":"Laboratory thinking","text":"When viewing a model, slide or image, ask: Where is it? How do I identify it? How does structure support function?"},{"kind":"content","title":"Dizziness on standing","text":"Connect circulation, blood pressure regulation and autonomic control."},{"kind":"content","title":"Redness and swelling near a wound","text":"Connect visible signs with tissue inflammation and repair."},{"kind":"content","title":"Weakness in one limb","text":"Think about nervous pathways and organised observation."},{"kind":"content","title":"Blood-count components","text":"Understand why red cells, white cells and platelets have different meanings."}],"sources":["openrn-skills","openstax-ap"]},{"id":"biochem","year":1,"sem":1,"code":"CHEM 101ly","nAr":"الكيمياء الحيوية","nEn":"Biochemistry","bigAr":"الماء وسط التفاعلات، والحموضة يجب أن تبقى ضمن نطاق مناسب لعمل البروتينات والخلايا.","bigEn":"Biochemistry explains body processes at the molecular level: water and pH, carbohydrates, lipids, proteins, enzymes, vitamins, minerals, nucleic acids and metabolism.","chunksAr":[{"kind":"content","title":"Water & pH","text":"الماء وسط التفاعلات، والحموضة يجب أن تبقى ضمن نطاق مناسب لعمل البروتينات والخلايا."},{"kind":"content","title":"Carbohydrates","text":"مصدر مهم للطاقة، والجلوكوز نقطة مركزية في الاستقلاب وتنظيم سكر الدم."},{"kind":"content","title":"Lipids","text":"تخزن الطاقة، تدخل في الأغشية والهرمونات، وتنقل في الدم ضمن جزيئات مثل LDL وHDL."},{"kind":"content","title":"Proteins","text":"تبني الأنسجة وتعمل كإنزيمات وناقلات ومستقبلات وأجسام مضادة وغيرها."},{"kind":"content","title":"Enzymes","text":"تسرّع التفاعلات الحيوية. تغير نشاطها أو مستويات بعضها قد يفيد في فهم أو متابعة حالات مرضية."},{"kind":"content","title":"DNA & RNA","text":"يحملان المعلومات الوراثية ويشاركان في توجيه تصنيع البروتينات."},{"kind":"content","title":"الماء والحموضة والـBuffers","text":"الجسم يحتاج المحافظة على pH مناسب. أنظمة التنظيم تساعد على مقاومة التغيرات الكبيرة في الحموضة والقلوية."},{"kind":"content","title":"الكربوهيدرات والطاقة","text":"الجلوكوز يدخل مسارات لإنتاج الطاقة، ويمكن تخزينه في صورة جليكوجين أو صنعه عند الحاجة في ظروف معينة."},{"kind":"content","title":"الدهون والليبوبروتينات","text":"الدهون لا تذوب بسهولة في الماء، لذلك تنقل في الدم ضمن جزيئات متخصصة. تختلف وظائف LDL وHDL وغيرها."},{"kind":"content","title":"البروتين والأحماض الأمينية","text":"البروتينات تعتمد في وظيفتها على بنيتها. تغير شكل البروتين قد يغير قدرته على العمل."},{"kind":"content","title":"الإنزيمات","text":"لها مواقع فعالة وتتأثر بالحرارة وpH والتركيز والمثبطات. كثير من العمليات الحيوية تعتمد عليها."},{"kind":"content","title":"الفيتامينات والمعادن","text":"بعضها يعمل كعامل مساعد في التفاعلات، والنقص أو الزيادة قد يؤثران في وظائف متعددة."},{"kind":"content","title":"الاستقلاب: بناء وهدم","text":"الجسم يهدم جزيئات للحصول على الطاقة ويبني جزيئات للنمو والإصلاح والتخزين. المساران يعملان باستمرار."},{"kind":"content","title":"تنظيم جلوكوز الدم والسكري","text":"توازن الجلوكوز يعتمد على الهرمونات والكبد والأنسجة ومسارات الاستقلاب. السكري مثال مهم لفهم أثر اضطراب هذا التنظيم."},{"kind":"content","title":"قراءة نتيجة Glucose","text":"الرقم وحده لا يكفي؛ فهم دور الجلوكوز والهرمونات والاستقلاب يعطيه معنى."},{"kind":"content","title":"مريض يعاني جفافًا","text":"فقد الماء لا يعني فقط العطش؛ يؤثر في حجم السوائل وتركيز المواد والتوازن داخل الجسم."},{"kind":"content","title":"نتيجة دهون الدم","text":"تظهر LDL وHDL وTriglycerides. فهم طريقة نقل الدهون يساعدك على عدم التعامل معها كأرقام منفصلة."},{"kind":"content","title":"تحليل يظهر ارتفاع إنزيم معين","text":"لا تشخّص من الرقم، لكن تفهم لماذا قد تُستخدم الإنزيمات كمؤشرات في المختبر."}],"chunksEn":[{"kind":"overview","title":"Biochemistry","text":"Biochemistry explains body processes at the molecular level: water and pH, carbohydrates, lipids, proteins, enzymes, vitamins, minerals, nucleic acids and metabolism."},{"kind":"content","title":"Water & pH","text":"Water supports reactions and pH affects protein and cell function."},{"kind":"content","title":"Carbohydrates","text":"Glucose is a central fuel molecule."},{"kind":"content","title":"Lipids","text":"Store energy, form membranes and travel through lipoproteins."},{"kind":"content","title":"Proteins","text":"Build tissues and serve as enzymes, carriers, receptors and antibodies."},{"kind":"content","title":"Enzymes","text":"Accelerate reactions and may serve as useful laboratory markers."},{"kind":"content","title":"DNA & RNA","text":"Carry and use genetic information."},{"kind":"content","title":"Buffers and pH","text":"Regulation resists harmful changes in acidity and alkalinity."},{"kind":"content","title":"Glucose metabolism","text":"Energy production, glycogen and blood glucose regulation."},{"kind":"content","title":"Lipoproteins","text":"LDL, HDL and related particles transport lipids."},{"kind":"content","title":"Vitamins & minerals","text":"Small quantities can have large physiological effects."},{"kind":"content","title":"A glucose result","text":"Understanding regulation gives the number meaning beyond memorising a reference range."},{"kind":"content","title":"Raised enzyme levels","text":"You do not diagnose from one result, but you understand why enzymes can be useful indicators."}],"sources":[]},{"id":"english","year":1,"sem":1,"code":"ENGL 101ly","nAr":"اللغة الإنجليزية 1","nEn":"English Language 1","bigAr":"الإنجليزية في التمريض ليست حفظ كلمات فقط. هي أداة لفهم المصطلح والتعليمات، طرح سؤال واضح، التأكد من أنك فهمت المريض أو الزميل بصورة صحيحة، ونقل معلومة دون لبس.","bigEn":"English in nursing is not only vocabulary. It supports accurate questions, clarification, understanding instructions, reading scientific terms and transferring information safely.","chunksAr":[{"kind":"content","title":"لماذا تهم طالب التمريض؟","text":"الإنجليزية في التمريض ليست حفظ كلمات فقط. هي أداة لفهم المصطلح والتعليمات، طرح سؤال واضح، التأكد من أنك فهمت المريض أو الزميل بصورة صحيحة، ونقل معلومة دون لبس."},{"kind":"scenario","title":"🩺 موقف قد تواجهه","text":"المريض يقول لك كلمة أو وصفًا لم تفهمه جيدًا. بدل التخمين، تحتاج إلى جملة بسيطة تطلب بها التوضيح ثم تعيد المعنى للتأكد من أنكما تقصدان الشيء نفسه."},{"kind":"content","title":"Nouns & Pronouns","text":"الأسماء والضمائر تحدد الأشخاص والأشياء: patient, nurse, medication, wound, he, she, it."},{"kind":"content","title":"Verbs","text":"الأفعال تصف ما يحدث أو ما يجب فعله: breathe, take, check, measure, turn, report, record."},{"kind":"content","title":"Adjectives","text":"الصفات تجعل الوصف أدق: severe, mild, swollen, clean, painful, warm."},{"kind":"content","title":"Questions","text":"تعلم بناء سؤال قصير وواضح للحصول على معلومة محددة بدل سؤال واسع أو غامض."},{"kind":"content","title":"Prepositions","text":"تفيد في وصف المكان والعلاقة: in, on, under, above, below, between."},{"kind":"content","title":"Numbers & time","text":"الأرقام والوقت مهمان في الحرارة والنبض والضغط والجرعات والمواعيد وتسجيل البيانات."},{"kind":"content","title":"مفردات تمريضية مبكرة","text":"هذه الكلمات تساعدك على التواصل، وسنضيف إليها تدريجيًا من مصطلحات التشريح والكيمياء الحيوية والمهارات التمريضية بدل دراسة اللغة بمعزل عن بقية مقرراتك."},{"kind":"content","title":"Clarification","text":"لا تخمن معنى كلمة أو تعليمات غير واضحة. اطلب توضيحًا."},{"kind":"content","title":"Checking understanding","text":"لا يكفي أن تقول المعلومة؛ تأكد من أن الشخص الآخر فهمها كما قصدت."},{"kind":"content","title":"Accurate handover","text":"المعلومة السريرية تحتاج كلمات محددة وأرقامًا واضحة، لا أوصافًا مبهمة."},{"kind":"content","title":"Patient-friendly language","text":"استخدم المصطلح المهني عندما تحتاجه، ثم اشرحه بلغة يستطيع المريض فهمها."}],"chunksEn":[{"kind":"overview","title":"English Language 1","text":"English in nursing is not only vocabulary. It supports accurate questions, clarification, understanding instructions, reading scientific terms and transferring information safely."},{"kind":"content","title":"Nouns & pronouns","text":"patient, nurse, medication, wound, he, she, it."},{"kind":"content","title":"Verbs","text":"breathe, take, check, measure, turn, report, record."},{"kind":"content","title":"Adjectives","text":"severe, mild, swollen, clean, painful, warm."},{"kind":"content","title":"Questions","text":"Build short, focused questions to obtain specific information."},{"kind":"content","title":"Position words","text":"in, on, under, above, below, between."},{"kind":"content","title":"Numbers & time","text":"Essential for vital signs, doses, measurements and documentation."},{"kind":"content","title":"An unclear patient description","text":"Rather than guessing, ask for clarification and repeat the meaning back to confirm it."}],"sources":[]},{"id":"arabic","year":1,"sem":1,"code":"LANG 100ly","nAr":"اللغة العربية","nEn":"Arabic Language","bigAr":"اللغة أداة للفهم والتواصل. يحتاج طالب التمريض إلى قراءة السؤال والتعليمات بدقة، ترتيب أفكاره، والتعبير عنها بصورة واضحة في الحديث والكتابة.","bigEn":"Language is a tool for understanding and communication. Nursing students need to read instructions accurately, organise ideas, and explain information clearly in speech and writing.","chunksAr":[{"kind":"content","title":"ما الذي يفيدك فيه هذا المقرر؟","text":"اللغة أداة للفهم والتواصل. يحتاج طالب التمريض إلى قراءة السؤال والتعليمات بدقة، ترتيب أفكاره، والتعبير عنها بصورة واضحة في الحديث والكتابة."},{"kind":"scenario","title":"🩺 موقف قد تواجهه","text":"عند سؤال مريض عن علاجه، قد يعطي السؤال العام إجابة عامة. صياغة سؤال محدد وواضح تساعدك على الحصول على معلومة أدق."},{"kind":"content","title":"بناء الجملة","text":"فهم الفعل والفاعل والصفة وبناء الجملة البسيطة يساعدك على القراءة والكتابة بوضوح."},{"kind":"content","title":"القراءة بفهم","text":"تعلم استخراج الفكرة الأساسية والتفاصيل، والتمييز بين ما هو رئيسي وما هو توضيح أو مثال."},{"kind":"content","title":"التعبير الشفهي","text":"رتب ما تريد قوله، واختر كلمات تناسب الشخص والموقف دون غموض أو تعقيد غير ضروري."},{"kind":"content","title":"الكتابة المنظمة","text":"ابدأ بفكرة واضحة ثم اشرحها بجمل مترابطة؛ هذه المهارة تفيد في الإجابات والتقارير والبحوث."},{"kind":"content","title":"الاستماع","text":"الاستماع الجيد لا يعني سماع الكلمات فقط، بل الانتباه للمعنى والسياق وما يحتاج إلى توضيح."},{"kind":"scenario","title":"اللغة حسب الموقف","text":"طريقة الحديث مع طفل أو مريض أو أستاذ أو زميل ليست واحدة؛ الوضوح والاحترام أهم من التعقيد."}],"chunksEn":[{"kind":"overview","title":"Arabic Language","text":"Language is a tool for understanding and communication. Nursing students need to read instructions accurately, organise ideas, and explain information clearly in speech and writing."},{"kind":"content","title":"Sentence structure","text":"Recognise how simple sentences are built and how words work together to create meaning."},{"kind":"content","title":"Reading for meaning","text":"Identify main ideas and important details instead of reading mechanically."},{"kind":"content","title":"Clear expression","text":"Organise ideas for answers, reports and patient education."}],"sources":[]},{"id":"islamic","year":1,"sem":1,"code":"LANG 102ly","nAr":"الدراسات الإسلامية","nEn":"Islamic Studies","bigAr":"مدخل إلى القرآن والسنة والسيرة، وأسس الفقه، والثقافة والحضارة الإسلامية، وعلاقة الإسلام بالحياة الاجتماعية والعلم وغيرها من القضايا العامة.","bigEn":"The course introduces core topics related to the Qur'an, Sunnah, Prophetic biography, Islamic law, culture, civilisation, science and social life.","chunksAr":[{"kind":"content","title":"ما الذي يتناوله المقرر؟","text":"مدخل إلى القرآن والسنة والسيرة، وأسس الفقه، والثقافة والحضارة الإسلامية، وعلاقة الإسلام بالحياة الاجتماعية والعلم وغيرها من القضايا العامة."},{"kind":"content","title":"🩺 صلة مفيدة بالممارسة","text":"العمل مع الناس يتطلب احترام معتقداتهم وقيمهم وخصوصيتهم. فهم الخلفية الدينية والثقافية يساعد على التواصل باحترام، مع الرجوع إلى المختصين عند وجود مسألة شرعية أو سريرية تحتاج حكمًا دقيقًا."},{"kind":"content","title":"القرآن","text":"مفاهيم أساسية، تاريخ القرآن، ومكانته في الحياة الإسلامية."},{"kind":"content","title":"السنة والسيرة","text":"مدخل إلى السنة ودراسة جوانب من سيرة النبي ﷺ."},{"kind":"content","title":"الفقه","text":"تعرف عام على مفهوم الشريعة والفقه ومجالاتهما."},{"kind":"content","title":"الثقافة والحضارة","text":"كيف تطورت الحضارة الإسلامية وإسهاماتها وتنوع مجتمعاتها."},{"kind":"content","title":"الإسلام والعلم","text":"التفكير في العلاقة بين طلب العلم والمسؤولية والمعرفة النافعة."},{"kind":"content","title":"النظام الاجتماعي","text":"قيم وعلاقات ومسؤوليات تنظم حياة الفرد داخل المجتمع."}],"chunksEn":[{"kind":"overview","title":"Islamic Studies","text":"The course introduces core topics related to the Qur'an, Sunnah, Prophetic biography, Islamic law, culture, civilisation, science and social life."},{"kind":"content","title":"Qur'an","text":"Basic concepts, history and role in Muslim life."},{"kind":"content","title":"Sunnah & Seerah","text":"An introduction to Sunnah and the Prophet's biography."},{"kind":"content","title":"Islamic jurisprudence","text":"A general introduction to Sharia and fiqh."},{"kind":"content","title":"Culture & civilisation","text":"Historical and cultural development of Muslim societies."},{"kind":"content","title":"Islam & science","text":"Knowledge, learning and beneficial scholarship."},{"kind":"content","title":"Social system","text":"Values, relationships and responsibilities within society."}],"sources":[]},{"id":"theory","year":1,"sem":1,"code":"NURS 101ly","nAr":"الأسس النظرية في التمريض","nEn":"Theoretical Foundations of Nursing","bigAr":"ليس «حالة مرضية» فقط؛ له احتياجات وقيم وعلاقات وقدرات ومخاوف وخلفية ثقافية.","bigEn":"Nursing is not a list of procedures. Theory helps students ask: Who is the person receiving care? What is health? How does environment matter? What is the nurse's role?","chunksAr":[{"kind":"content","title":"Person · الإنسان","text":"ليس «حالة مرضية» فقط؛ له احتياجات وقيم وعلاقات وقدرات ومخاوف وخلفية ثقافية."},{"kind":"content","title":"Health · الصحة","text":"ليست فقط غياب المرض؛ قد تشمل القدرة على التكيف والعمل والاستقلال وتحقيق أفضل حالة ممكنة."},{"kind":"content","title":"Environment · البيئة","text":"كل ما يحيط بالشخص وقد يؤثر في صحته: البيئة المادية والاجتماعية والثقافية."},{"kind":"content","title":"Nursing · التمريض","text":"ماذا يفعل الممرض ولماذا؟ مساعدة، حماية، تعليم، ملاحظة، دعم الاستقلال، بناء علاقة علاجية وتنسيق الرعاية."},{"kind":"lesson","title":"Concept","text":"فكرة أساسية تساعدنا على تسمية شيء وفهمه، مثل الصحة أو الاستقلال أو التكيف."},{"kind":"content","title":"Theory","text":"ترتيب منظم لأفكار وعلاقات يساعدنا على تفسير ظاهرة أو توجيه طريقة التفكير والممارسة."},{"kind":"content","title":"Principle","text":"قاعدة عامة توجه الفعل أو الحكم، مثل احترام الخصوصية أو المحافظة على السلامة."},{"kind":"content","title":"البيئة تؤثر في الشفاء","text":"النظافة والتهوية والضوء والهدوء والبيئة المناسبة ليست تفاصيل جانبية؛ قد تؤثر في راحة المريض وتعافيه."},{"kind":"content","title":"مساعدة الشخص على الاستقلال","text":"الممرض يساعد الشخص على أداء ما كان سيقوم به بنفسه لو كانت لديه القوة أو المعرفة أو القدرة."},{"kind":"content","title":"الرعاية الذاتية","text":"فكر في ما يستطيع المريض فعله بنفسه، وما لا يستطيع، وكيف تساعده على استعادة القدرة أو تعويضها."},{"kind":"content","title":"العلاقة العلاجية","text":"العلاقة بين الممرض والمريض نفسها أداة علاجية عندما تقوم على التواصل والثقة والأدوار الواضحة."},{"kind":"content","title":"التكيف","text":"انظر كيف يتكيف الشخص جسديًا ونفسيًا واجتماعيًا مع التغير أو المرض."},{"kind":"content","title":"الرعاية والثقافة","text":"الرعاية الجيدة تراعي قيم الشخص ومعتقداته وممارساته الثقافية ما دام ذلك ممكنًا وآمنًا."},{"kind":"content","title":"مريض يستطيع الأكل بنفسه لكنه بطيء","text":"القيام بكل شيء عنه قد يكون أسرع، لكن تشجيعه على الاستقلال قد يكون جزءًا من الرعاية."},{"kind":"content","title":"مريض قلق ولا يتعاون","text":"قد لا تكون المشكلة «رفضًا» فقط؛ العلاقة، الخوف وطريقة التواصل قد تغير الموقف."},{"kind":"content","title":"ممارسة ثقافية مهمة للمريض","text":"بدل تجاهلها، تسأل كيف يمكن احترامها دون تعريض سلامة المريض للخطر."},{"kind":"content","title":"غرفة مزعجة ومزدحمة","text":"قد تكون البيئة جزءًا من المشكلة: النوم والراحة والخصوصية والسلامة كلها تتأثر."}],"chunksEn":[{"kind":"overview","title":"Theoretical Foundations of Nursing","text":"Nursing is not a list of procedures. Theory helps students ask: Who is the person receiving care? What is health? How does environment matter? What is the nurse's role?"},{"kind":"content","title":"Person","text":"A whole person with needs, values, relationships and culture."},{"kind":"content","title":"Health","text":"More than absence of disease; includes function, adaptation and independence."},{"kind":"content","title":"Environment","text":"Physical, social and cultural surroundings that influence health."},{"kind":"content","title":"Nursing","text":"Observation, assistance, education, protection, relationship-building and coordination."},{"kind":"content","title":"Environment matters","text":"Cleanliness, ventilation, light, quiet and surroundings can influence recovery."},{"kind":"content","title":"Support independence","text":"Assist with what the person would do independently if able."},{"kind":"content","title":"Self-care","text":"Assess what the person can do and where nursing support is needed."},{"kind":"content","title":"Therapeutic relationship","text":"Communication and trust are part of professional nursing care."},{"kind":"content","title":"Adaptation","text":"Consider physical, psychological and social adaptation."},{"kind":"content","title":"Culture and care","text":"Respect meaningful cultural beliefs and practices whenever safe and possible."}],"sources":[]},{"id":"rle1","year":1,"sem":1,"code":"NURS 102ly","nAr":"الخبرة التعليمية المرتبطة 1","nEn":"Related Learning Experience 1","bigAr":"افترض أن التعرض للدم أو سوائل الجسم قد يحمل خطرًا، واتبع الاحتياطات المناسبة بدل الاعتماد على معرفة تشخيص المريض.","bigEn":"This is where knowledge begins to become performance. The goal is not only to copy steps, but to understand why each step is done and how it protects the patient and nurse.","chunksAr":[{"kind":"content","title":"Universal precautions","text":"افترض أن التعرض للدم أو سوائل الجسم قد يحمل خطرًا، واتبع الاحتياطات المناسبة بدل الاعتماد على معرفة تشخيص المريض."},{"kind":"content","title":"Hand hygiene","text":"غسل اليدين ليس إجراءً شكليًا؛ هو كسر لسلسلة انتقال الميكروبات في اللحظة المناسبة وبالطريقة المناسبة."},{"kind":"content","title":"PPE & gloves","text":"اختيار معدات الوقاية وترتيب لبسها وخلعها يرتبط بنوع التعرض المتوقع ومنع تلويث النفس أو البيئة."},{"kind":"content","title":"Documentation","text":"ما لم يُوثق بدقة قد يصبح غير واضح للفريق التالي. التسجيل جزء من استمرارية الرعاية."},{"kind":"content","title":"Body mechanics & positioning","text":"الوضعية قد تحقق الراحة، تسهل إجراءً، تحمي الجلد أو التنفس، كما تحمي الممرض من إصابة الظهر."},{"kind":"content","title":"Vital signs","text":"الحرارة والنبض والتنفس والضغط ليست أرقامًا تحفظ؛ هي إشارات عن عمل أجهزة الجسم يجب قياسها بصورة صحيحة ومقارنتها بالسياق."},{"kind":"content","title":"غسل اليدين","text":"متى تغسل؟ كيف تمنع إعادة تلوث اليدين؟ ولماذا تحتاج تغطية كل الأسطح بدل الاكتفاء ببلل اليدين؟"},{"kind":"content","title":"القفازات والـPPE","text":"التمييز بين القفاز النظيف والمعقم، وكيفية ارتداء معدات الوقاية وخلعها دون نقل التلوث."},{"kind":"content","title":"الوضعيات","text":"Supine, prone, lateral, Fowler’s وغيرها؛ كل وضعية لها هدف واحتياطات."},{"kind":"content","title":"Range of Motion","text":"حركة المفاصل ضمن المدى المناسب للمساعدة على المحافظة على الحركة والمرونة حسب حالة المريض."},{"kind":"content","title":"النظافة والراحة","text":"تغيير الرداء أو الحفاض أو العناية بالنظافة يجب أن يحافظ على الكرامة والخصوصية والجلد وسلامة الحركة."},{"kind":"content","title":"ترتيب السرير","text":"السرير المفتوح والمغلق والمشغول ليست أشكالًا؛ الهدف هو راحة المريض وسلامته وكفاءة الرعاية."},{"kind":"content","title":"درجة الحرارة والنبض والتنفس","text":"تعلم القياس، العوامل التي تغير القراءة، ومتى تبدو النتيجة مختلفة عما تتوقع."},{"kind":"content","title":"ضغط الدم","text":"اختيار الكفة المناسبة، وضع الذراع، التقنية الصحيحة، وفهم أن القياس الخاطئ قد يعطي رقمًا مضللًا."},{"kind":"content","title":"أنت على وشك لمس المريض بعد لمس سطح قريب","text":"تتذكر أن اليد قد تنقل الميكروبات حتى لو لم تبدُ متسخة."},{"kind":"content","title":"مريض ضعيف يحتاج تغيير الوضعية","text":"التحريك غير المنظم قد يؤذي المريض أو ظهرك."},{"kind":"content","title":"ضغط الدم أعلى بكثير من المتوقع","text":"قبل أن تقلق من الرقم، تتأكد من الكفة والوضعية والراحة والتقنية ثم تعيد القياس أو تبلغ حسب الإجراء."},{"kind":"content","title":"إبرة مستعملة بعد الإجراء","text":"لحظة التخلص منها قد تكون أخطر من الإجراء نفسه إذا لم تتبع احتياطات الأدوات الحادة."}],"chunksEn":[{"kind":"overview","title":"Related Learning Experience 1","text":"This is where knowledge begins to become performance. The goal is not only to copy steps, but to understand why each step is done and how it protects the patient and nurse."},{"kind":"content","title":"Universal precautions","text":"Use protection for possible exposure."},{"kind":"content","title":"Hand hygiene","text":"Break the chain of microorganism transmission."},{"kind":"content","title":"PPE & gloves","text":"Select, don and remove protective equipment safely."},{"kind":"content","title":"Documentation","text":"Accurate records support continuity of care."},{"kind":"content","title":"Positioning & body mechanics","text":"Protect patient comfort and staff safety."},{"kind":"content","title":"Vital signs","text":"Measurements reflect body function and must be obtained accurately."},{"kind":"content","title":"Handwashing","text":"When, how and why all hand surfaces are cleaned."},{"kind":"content","title":"Gloves & PPE","text":"Clean vs sterile gloves; safe donning and doffing."},{"kind":"content","title":"Patient positioning","text":"Supine, prone, lateral, Fowler's and other positions."},{"kind":"content","title":"Range of motion","text":"Joint movement according to patient condition."},{"kind":"content","title":"Hygiene & comfort","text":"Dignity, privacy, skin care and safe movement."},{"kind":"content","title":"Bed making","text":"Open, closed and occupied beds."},{"kind":"content","title":"Temperature, pulse, respiration","text":"Technique and factors that affect results."},{"kind":"content","title":"Blood pressure","text":"Cuff size, arm position and technique."},{"kind":"content","title":"A surprisingly high blood pressure reading","text":"Check cuff size, position, rest and technique before interpreting the number."},{"kind":"content","title":"Used sharps after a procedure","text":"Safety continues after the procedure; disposal is part of preventing injury and exposure."}],"sources":["openrn-fund","openrn-skills","who-safety"]},{"id":"sociology","year":1,"sem":1,"code":"SOCSCI 100ly","nAr":"علم الاجتماع الطبي","nEn":"Medical Sociology","bigAr":"نفس المرض قد تكون له تجربة مختلفة عند شخصين لأن ظروفهما الاجتماعية مختلفة.","bigEn":"Health and illness are influenced by social conditions as well as biological factors. Family, education, income, work, housing, culture and access to care can shape health behaviour and outcomes.","chunksAr":[{"kind":"content","title":"Health is social too","text":"نفس المرض قد تكون له تجربة مختلفة عند شخصين لأن ظروفهما الاجتماعية مختلفة."},{"kind":"content","title":"Patterns of disease","text":"بعض الأمراض أو المخاطر لا تتوزع بالتساوي بين الناس، وقد ترتبط بظروف المجتمع والبيئة ونمط الحياة."},{"kind":"content","title":"Social inequalities","text":"القدرة على الوصول للفحص أو الدواء أو الغذاء أو النقل قد تغير النتائج الصحية حتى عند وجود الخدمة نفسها."},{"kind":"content","title":"Illness experience","text":"ما يشعر به الإنسان وما يعنيه المرض له قد يختلف عن التعريف الطبي للمرض."},{"kind":"content","title":"Sick role","text":"المجتمع لديه توقعات عن المريض: متى يطلب مساعدة، وما الذي يُعفى منه، وما الذي يتوقع منه فعله للتعافي."},{"kind":"content","title":"Health system","text":"المهن الصحية والتنظيم والتأمين وطريقة تقديم الخدمات كلها تؤثر في رحلة المريض."},{"kind":"content","title":"المحددات الاجتماعية للصحة","text":"اسأل: أين يعيش المريض؟ ماذا يستطيع أن يشتري؟ هل لديه نقل؟ هل يستطيع قراءة التعليمات؟ هل لديه دعم أسري؟"},{"kind":"content","title":"الثقافة والمعتقدات","text":"الثقافة قد تؤثر في تفسير المرض، طلب المساعدة، الطعام، الخصوصية، قبول بعض الإجراءات وطريقة التواصل."},{"kind":"content","title":"Medicalization","text":"بعض جوانب الحياة قد تُعامل مع الوقت على أنها قضايا طبية؛ فهم هذا المفهوم يساعدك على التفكير النقدي في حدود الطب والرعاية."},{"kind":"content","title":"العلاقة مع النظام الصحي","text":"تجربة المريض لا تعتمد على الطبيب أو الممرض وحده؛ التنظيم والمواعيد والتكلفة والمعلومات كلها أجزاء من الرعاية."},{"kind":"content","title":"مريض لا يعود للمتابعة","text":"قد يبدو لأول وهلة «غير ملتزم»، لكن السبب قد يكون بعد المسافة أو المواصلات أو تكلفة الدواء أو عدم فهم التعليمات."},{"kind":"content","title":"أسرة تفسر المرض بطريقة مختلفة","text":"قد تكون لديهم معتقدات حول السبب أو العلاج. فهم الخلفية لا يعني الموافقة على كل شيء، لكنه يساعدك على التواصل باحترام وبناء الثقة."},{"kind":"content","title":"تعليمات ممتازة لكنها غير قابلة للتطبيق","text":"تنصح المريض بنظام غذائي أو متابعة لا يستطيع تنفيذها بسبب ظروفه."},{"kind":"content","title":"مريضان بنفس التشخيص","text":"أحدهما لديه أسرة داعمة وموارد جيدة، والآخر يعيش وحده وموارده محدودة."}],"chunksEn":[{"kind":"overview","title":"Medical Sociology","text":"Health and illness are influenced by social conditions as well as biological factors. Family, education, income, work, housing, culture and access to care can shape health behaviour and outcomes."},{"kind":"content","title":"Patterns of disease","text":"Health risks are not distributed equally."},{"kind":"content","title":"Social inequalities","text":"Resources and access can change outcomes."},{"kind":"content","title":"Illness experience","text":"The patient's experience may differ from the biomedical label."},{"kind":"content","title":"Culture","text":"Beliefs can influence communication, food, privacy and help-seeking."},{"kind":"content","title":"Sick role","text":"Societies have expectations around illness and recovery."},{"kind":"content","title":"Health systems","text":"Organisation and service design shape the patient journey."},{"kind":"content","title":"A patient misses follow-up","text":"Consider transport, cost, understanding, family support or work before labelling the patient “non-compliant.”"},{"kind":"content","title":"Advice that cannot be followed","text":"A technically correct plan may fail if it ignores the patient's real circumstances."}],"sources":[]},{"id":"comm1","year":1,"sem":2,"code":"LANG 102ly","nAr":"مهارات التواصل 1","nEn":"Communication Skills 1","typeAr":"عام","typeEn":"General","bigAr":"مهارات التواصل 1 تبني أساس الاستماع والوضوح والسؤال المناسب واللغة غير اللفظية والتحقق من الفهم؛ وهي أساس مهم قبل التواصل العلاجي والسريري الأكثر تقدمًا.","bigEn":"Communication Skills 1 develops listening, clarity, effective questioning, nonverbal communication and checking understanding as foundations for therapeutic communication.","chunksAr":[{"kind":"concept","title":"الاستماع الفعال","text":"ركز في كلام المتحدث، لا تقاطعه بلا حاجة، لاحظ المعنى والانفعال، ثم لخص أو أعد الصياغة للتأكد أنك فهمت."},{"kind":"concept","title":"الأسئلة المفتوحة والمغلقة","text":"السؤال المفتوح يساعد على السرد والفهم، والمغلق يفيد في معلومة محددة؛ الاستخدام الجيد يجمع بينهما."},{"kind":"concept","title":"التواصل غير اللفظي","text":"نبرة الصوت وتعبير الوجه والمسافة ووضع الجسم قد تدعم الرسالة أو تناقضها."},{"kind":"concept","title":"التحقق من الفهم","text":"لا تسأل فقط «فهمت؟». اطلب من الشخص أن يشرح بطريقته ما فهمه عندما تكون المعلومة مهمة."},{"kind":"concept","title":"الوضوح والاختصار","text":"استخدم كلمات تناسب الشخص، فكرة واحدة في كل مرة، وتجنب المصطلحات المعقدة دون شرح."},{"kind":"scenario","title":"مريض يقول نعم لكنه يبدو مترددًا","text":"لا تفترض الفهم؛ استخدم سؤالًا مفتوحًا أو إعادة صياغة، وانتبه للإشارات غير اللفظية."}],"chunksEn":[{"kind":"concept","title":"Active listening","text":"Attend to the speaker, avoid unnecessary interruption, notice meaning and emotion, then summarise or paraphrase to confirm understanding."},{"kind":"concept","title":"Open and closed questions","text":"Open questions invite explanation; closed questions obtain specific facts. Effective interviewing uses both."},{"kind":"concept","title":"Nonverbal communication","text":"Tone, facial expression, distance and posture can support or contradict spoken words."},{"kind":"concept","title":"Check understanding","text":"Do not rely only on 'Do you understand?'; for important information, ask the person to explain it back in their own words."},{"kind":"concept","title":"Clarity","text":"Use language appropriate to the person, one idea at a time, and explain technical terms."},{"kind":"scenario","title":"Patient says yes but looks unsure","text":"Do not assume understanding; use an open question or paraphrase and attend to nonverbal cues."}],"sources":["who-safety"]},{"id":"anatomy2","year":1,"sem":2,"code":"MED 103ly","nAr":"التشريح ووظائف الأعضاء 2","nEn":"Human Anatomy & Physiology 2","typeAr":"طبي مساند","typeEn":"Supporting medical","bigAr":"يكمل المقرر فهم أجهزة الجسم بوصفها أنظمة مترابطة. المهم أن تربط البنية بالوظيفة، ثم تسأل كيف يغيّر خلل عضو واحد السوائل والطاقة والهرمونات والتنفس والإطراح والتكاثر.","bigEn":"Anatomy & Physiology 2 continues a systems approach, connecting structure with function across respiration, digestion, urinary function, endocrine regulation and reproduction.","chunksAr":[{"kind":"concept","title":"الجهاز التنفسي","text":"التهوية تحرك الهواء، وتبادل الغازات ينقل الأكسجين وثاني أكسيد الكربون عبر الحويصلات، بينما ينظم الجسم التنفس حسب الحاجة."},{"kind":"concept","title":"الجهاز الهضمي والاستقلاب","text":"الهضم يحول الطعام إلى مواد قابلة للامتصاص، والكبد والبنكرياس والأمعاء تسهم في الاستقلاب وتنظيم المغذيات."},{"kind":"concept","title":"الجهاز البولي","text":"الكلى ترشح الدم وتضبط الماء والشوارد والحمض والقاعدة وتشارك في تنظيم الضغط وتكوين بعض الهرمونات."},{"kind":"concept","title":"الغدد الصماء","text":"الهرمونات رسائل كيميائية تنظم النمو والاستقلاب والسكر والتوازن المائي والتكاثر، ويعتمد أثرها على المستقبلات وآليات التغذية الراجعة."},{"kind":"concept","title":"التكاثر","text":"الأعضاء التناسلية والهرمونات والدورة التناسلية مترابطة، ويجب فهمها كأساس للحمل والصحة الإنجابية."},{"kind":"lesson","title":"السوائل والشوارد","text":"توازن الماء والصوديوم والبوتاسيوم مهم لوظيفة الأعصاب والعضلات والدورة والخلايا."},{"kind":"lesson","title":"اربط الأجهزة","text":"عند تغير التنفس أو البول أو الضغط، فكّر في التفاعل بين الرئتين والكلى والقلب والهرمونات بدل دراسة كل جهاز منفردًا."}],"chunksEn":[{"kind":"concept","title":"Respiratory system","text":"Ventilation moves air; gas exchange transfers oxygen and carbon dioxide across alveoli; control systems adjust breathing to need."},{"kind":"concept","title":"Digestive system & metabolism","text":"Digestion makes nutrients absorbable while the liver, pancreas and intestine support metabolism and nutrient regulation."},{"kind":"concept","title":"Urinary system","text":"Kidneys filter blood and regulate water, electrolytes, acid-base balance, blood pressure and selected hormones."},{"kind":"concept","title":"Endocrine system","text":"Hormones are chemical messengers controlling growth, metabolism, glucose, water balance and reproduction through receptors and feedback."},{"kind":"concept","title":"Reproduction","text":"Reproductive organs, hormones and cycles form the physiological basis for reproductive health and pregnancy."},{"kind":"lesson","title":"Fluids & electrolytes","text":"Water, sodium and potassium balance are essential to nerves, muscles, circulation and cells."},{"kind":"lesson","title":"Integrate systems","text":"When breathing, urine output or blood pressure changes, think across lungs, kidneys, heart and hormones rather than one organ alone."}],"sources":["openrn-skills","openstax-ap"]},{"id":"micro","year":1,"sem":2,"code":"MED 104ly","nAr":"الأحياء الدقيقة للتمريض","nEn":"Microbiology for Nursing","typeAr":"طبي مساند","typeEn":"Supporting medical","bigAr":"الأحياء الدقيقة للتمريض تشرح من هم الميكروبات، كيف تنتقل وتسبب المرض، كيف يدافع الجسم، وكيف تقلل الممارسة السليمة العدوى ومقاومة المضادات.","bigEn":"Microbiology for Nursing explains microorganisms, transmission, host defence, infection prevention and antimicrobial resistance with clinical relevance.","chunksAr":[{"kind":"concept","title":"البكتيريا والفيروسات والفطريات","text":"تختلف المجموعات في البنية وطريقة التكاثر والاستجابة للعلاج؛ لذلك لا يُفترض أن دواءً واحدًا يعمل ضد جميع مسببات العدوى."},{"kind":"concept","title":"سلسلة العدوى","text":"العامل الممرض والمستودع وبوابة الخروج وطريقة الانتقال وبوابة الدخول والمضيف القابل للإصابة حلقات يمكن كسرها بإجراءات الوقاية."},{"kind":"concept","title":"Gram stain","text":"صبغة غرام تقسّم كثيرًا من البكتيريا إلى موجبة وسالبة غرام حسب خصائص جدار الخلية، وهي معلومة تساعد في التعرف الأولي وليست تشخيصًا نهائيًا وحدها."},{"kind":"concept","title":"التعقيم والتطهير","text":"التنظيف يزيل الأوساخ ويخفض الحمل الميكروبي؛ التطهير يقتل كثيرًا من الكائنات على الأسطح؛ التعقيم يهدف إلى إزالة جميع أشكال الحياة الميكروبية بما فيها الأبواغ."},{"kind":"concept","title":"مقاومة المضادات","text":"الاستخدام غير الضروري أو غير الصحيح للمضادات يزيد الضغط الانتقائي الذي يسمح للسلالات المقاومة بالبقاء والانتشار."},{"kind":"lesson","title":"جمع العينات","text":"العينة الجيدة تُجمع من الموقع الصحيح وفي الوقت الصحيح وبأداة مناسبة وتصل للمختبر دون تلوث أو تأخير غير مبرر."},{"kind":"scenario","title":"مريض بعلامات عدوى","text":"فكر في المصدر المحتمل، طريقة الانتقال، العينة المناسبة، احتياطات العدوى، والعلاج الموصوف دون افتراض أن كل حمى تحتاج مضادًا حيويًا."}],"chunksEn":[{"kind":"concept","title":"Bacteria, viruses and fungi","text":"These groups differ in structure, replication and treatment response; one antimicrobial does not work against every infectious cause."},{"kind":"concept","title":"Chain of infection","text":"Agent, reservoir, portal of exit, mode of transmission, portal of entry and susceptible host are links that prevention can interrupt."},{"kind":"concept","title":"Gram stain","text":"Gram staining classifies many bacteria as Gram-positive or Gram-negative based on cell-wall properties; it supports early identification but is not a final diagnosis by itself."},{"kind":"concept","title":"Sterilisation and disinfection","text":"Cleaning removes soil and lowers microbial burden; disinfection kills many organisms on surfaces; sterilisation aims to eliminate all microbial life including spores."},{"kind":"concept","title":"Antimicrobial resistance","text":"Unnecessary or incorrect antimicrobial use creates selection pressure that allows resistant organisms to survive and spread."},{"kind":"lesson","title":"Specimen collection","text":"Collect the right specimen from the right site at the right time with appropriate technique and transport it without avoidable contamination or delay."},{"kind":"scenario","title":"Patient with infection signs","text":"Think about source, transmission, specimen needs, precautions and prescribed treatment rather than assuming every fever requires an antibiotic."}],"sources":["openstax-micro"]},{"id":"healthassessment","year":1,"sem":2,"code":"NURS 103LY","nAr":"التقييم الصحي","nEn":"Health Assessment","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"التقييم الصحي هو جمع منظم للمعلومات من التاريخ الصحي والفحص البدني والعلامات الحيوية، ثم تمييز المتوقع من غير المتوقع وتوثيق ما وُجد بدقة. الهدف ليس جمع أكبر عدد من البيانات، بل اكتشاف ما يهم المريض الآن وما يحتاج متابعة.","bigEn":"Health assessment combines history, physical examination and vital signs to identify what is expected or unexpected and to document findings accurately.","chunksAr":[{"kind":"concept","title":"التاريخ الصحي","text":"ابدأ بسبب طلب الرعاية، الأعراض الحالية، التاريخ السابق، الأدوية والحساسيات والعادات والوظيفة اليومية، مع أسئلة مفتوحة ثم أسئلة أكثر تحديدًا."},{"kind":"concept","title":"الفحص البدني","text":"التقنيات الأساسية هي المعاينة والجس والقرع والتسمع، ويختلف ترتيبها حسب الجهاز؛ في البطن يُفضّل التسمع قبل الجس والقرع حتى لا تغير الأصوات المعوية."},{"kind":"concept","title":"العلامات الحيوية","text":"الحرارة والنبض والتنفس والضغط والأكسجة مؤشرات يجب تفسيرها مع حالة المريض والعمر والسياق، لا كأرقام منفصلة."},{"kind":"concept","title":"الألم","text":"قيّم الموقع والبداية والصفة والشدة وما يزيده أو يخففه والأعراض المصاحبة وتأثيره في الوظيفة، ثم أعد التقييم بعد التدخل."},{"kind":"lesson","title":"التقييم من الرأس إلى القدمين","text":"استخدم تسلسلًا ثابتًا لتقليل النسيان، لكن انتقل فورًا إلى تقييم مركز إذا ظهرت مشكلة عاجلة."},{"kind":"lesson","title":"التوثيق","text":"اكتب ما رأيته وسمعته وقسته بلغة واضحة وموضوعية، وميّز بين كلام المريض والملاحظة السريرية."},{"kind":"scenario","title":"دوخة عند الوقوف","text":"اربط الشكوى بالضغط والنبض والسوائل والأدوية والسقوط، ولا تعتمد على قراءة واحدة دون سياق."},{"kind":"scenario","title":"ضيق تنفس جديد","text":"ابدأ بمظهر المريض ومعدل التنفس والأكسجة والقدرة على الكلام وأصوات التنفس، ثم صعّد حسب الخطورة."}],"chunksEn":[{"kind":"concept","title":"Health history","text":"Start with the reason for care, current symptoms, past history, medicines, allergies, habits and daily function; move from open to focused questions."},{"kind":"concept","title":"Physical examination","text":"Core techniques are inspection, palpation, percussion and auscultation; abdominal assessment commonly uses auscultation before palpation and percussion."},{"kind":"concept","title":"Vital signs","text":"Temperature, pulse, respirations, blood pressure and oxygenation must be interpreted in context rather than as isolated numbers."},{"kind":"concept","title":"Pain assessment","text":"Assess location, onset, character, severity, aggravating/relieving factors, associated symptoms and functional impact, then reassess after intervention."},{"kind":"lesson","title":"Head-to-toe assessment","text":"Use a consistent sequence to reduce omissions, but switch to a focused urgent assessment when a serious problem appears."},{"kind":"lesson","title":"Documentation","text":"Record observed, heard and measured findings clearly and objectively; distinguish the patient's words from clinical observations."},{"kind":"scenario","title":"Dizziness on standing","text":"Connect the symptom with blood pressure, pulse, hydration, medicines and fall risk instead of relying on a single number."},{"kind":"scenario","title":"New shortness of breath","text":"Assess appearance, respiratory rate, oxygenation, ability to speak and breath sounds, then escalate according to severity."}],"sources":["openrn-skills","openstax-ap","openrn-fund"]},{"id":"fundamentals","year":1,"sem":2,"code":"NURS 104ly","nAr":"أساسيات التمريض","nEn":"Fundamentals of Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"أساسيات التمريض تبني طريقة التفكير قبل المهارة: سلامة المريض، عملية التمريض، التواصل، النظافة والراحة، الحركة، الأكسجة، التغذية، الإطراح، الوقاية من العدوى والتوثيق.","bigEn":"Fundamentals of Nursing builds the thinking behind safe care: nursing process, communication, infection prevention, comfort, mobility, oxygenation, nutrition, elimination and documentation.","chunksAr":[{"kind":"concept","title":"عملية التمريض","text":"التقييم يجمع البيانات، ثم تُحدد المشكلات أو التشخيصات التمريضية، وتوضع أهداف وخطة، وتنفذ التدخلات، ثم تقاس النتيجة ويعاد التقييم."},{"kind":"concept","title":"سلامة المريض","text":"تحقق الهوية، بيئة آمنة، الوقاية من السقوط، التواصل الواضح، ومراجعة المخاطر قبل الإجراء تقلل الضرر."},{"kind":"concept","title":"الوقاية من العدوى","text":"نظافة اليدين، التقنية المناسبة، معدات الحماية، والتعامل الصحيح مع الأدوات والإفرازات تكسر سلسلة انتقال العدوى."},{"kind":"concept","title":"الحركة والراحة","text":"الوضعية والحركة الآمنة والعناية بالجلد والنوم والسيطرة على الألم تساعد على منع مضاعفات قلة الحركة وتحافظ على الاستقلال."},{"kind":"concept","title":"التغذية والإطراح","text":"الوارد الغذائي والسوائل والبول والبراز تعطي معلومات عن الوظيفة والحالة العامة وتحتاج متابعة واحترام الخصوصية."},{"kind":"lesson","title":"التواصل العلاجي","text":"استمع، استخدم أسئلة مفتوحة، تحقق من الفهم، تجنب الأحكام والوعود غير الواقعية، ووثّق المعلومات المهمة."},{"kind":"scenario","title":"مريض معرض للسقوط","text":"لا يكفي وضع لافتة؛ قيّم السبب والدواء والحركة والبيئة، قرّب جرس النداء وشارك خطة السلامة مع الفريق."}],"chunksEn":[{"kind":"concept","title":"Nursing process","text":"Assess, identify nursing problems, set goals and a plan, implement interventions, evaluate outcomes, and reassess."},{"kind":"concept","title":"Patient safety","text":"Identity checks, a safe environment, fall prevention, clear communication and risk review reduce preventable harm."},{"kind":"concept","title":"Infection prevention","text":"Hand hygiene, appropriate technique, PPE and correct handling of equipment and body fluids interrupt transmission."},{"kind":"concept","title":"Mobility & comfort","text":"Safe positioning, mobility, skin care, sleep and pain management help prevent complications and preserve independence."},{"kind":"concept","title":"Nutrition & elimination","text":"Food, fluid intake, urine and stool provide useful information about health and require monitoring with dignity and privacy."},{"kind":"lesson","title":"Therapeutic communication","text":"Listen, use open questions, check understanding, avoid judgement and unrealistic promises, and document important information."},{"kind":"scenario","title":"Patient at risk of falling","text":"Do more than place a sign: assess causes, medicines, mobility and environment, position the call bell, and share the safety plan."}],"sources":["openrn-mental","openrn-fund","openrn-skills"]},{"id":"rle2","year":1,"sem":2,"code":"NURS 105ly","nAr":"الخبرة التعليمية المرتبطة 2","nEn":"Related Learning Experience 2","typeAr":"تمريضي عملي","typeEn":"Practical nursing","bigAr":"هذا المقرر هو مساحة التطبيق العملي لما تتعلمه في أساسيات التمريض والتقييم الصحي. النجاح فيه يعتمد على السلامة والترتيب وفهم سبب كل خطوة، لا على تقليد الحركة فقط.","bigEn":"Related Learning Experience 2 applies fundamentals and health assessment in practical skills; safe sequencing and understanding rationales matter more than copying movements.","chunksAr":[{"kind":"concept","title":"قبل الإجراء","text":"تحقق من هوية المريض، اشرح ما ستفعله، راجع الحساسية والمخاطر، جهّز الأدوات وحافظ على الخصوصية ونظافة اليدين."},{"kind":"concept","title":"التقنية النظيفة والمعقمة","text":"اختر مستوى التقنية المناسب للمهمة، واعرف متى يُعد السطح أو الأداة ملوثة وما الذي يجب تغييره فورًا."},{"kind":"concept","title":"القياس والملاحظة","text":"العلامات الحيوية والتقييم السريري مهارات قياس وتفسير معًا؛ أي قيمة غير متوقعة تحتاج إعادة تحقق وربط بالسياق."},{"kind":"concept","title":"الأدوية والعينات","text":"التزم بحقوق إعطاء الدواء وسياسة الكلية/الموقع، وعرّف العينة جيدًا وتجنب التلوث وسجل الوقت والمصدر حسب الإجراء."},{"kind":"lesson","title":"التغذية الراجعة","text":"بعد كل تدريب اسأل: ما الخطوة التي نجحت؟ أين كسرْت التسلسل أو السلامة؟ وما المبرر الذي لم أفهمه؟"},{"kind":"scenario","title":"تلوث أثناء مهارة","text":"إذا شككت أن قفازًا أو أداة أو حقلًا أصبح ملوثًا، توقف وصحح قبل الاستمرار بدل إخفاء الخطأ لإكمال التسلسل."}],"chunksEn":[{"kind":"concept","title":"Before a procedure","text":"Confirm identity, explain the procedure, review allergies and risks, prepare equipment, protect privacy and perform hand hygiene."},{"kind":"concept","title":"Clean and sterile technique","text":"Choose the correct level of asepsis and recognise when a glove, field or instrument has become contaminated."},{"kind":"concept","title":"Measurement & observation","text":"Vital signs and assessment require both measurement and interpretation; unexpected values should be rechecked and placed in context."},{"kind":"concept","title":"Medicines & specimens","text":"Follow medication rights and local policy; identify specimens correctly and minimise contamination and unnecessary delay."},{"kind":"lesson","title":"Use feedback","text":"After practice ask what went well, where sequence or safety broke down, and which rationale you still do not understand."},{"kind":"scenario","title":"Contamination during a skill","text":"Stop and correct the contamination rather than hiding the error just to complete the sequence."}],"sources":["openrn-fund","openrn-skills","who-safety"]},{"id":"psych","year":1,"sem":2,"code":"PSYCH 100ly","nAr":"علم النفس العام","nEn":"General Psychology","typeAr":"عام","typeEn":"General","bigAr":"علم النفس يساعد طالب التمريض على فهم السلوك والتعلم والذاكرة والدافعية والانفعال والضغط والتكيف والاختلافات الفردية، وهي أمور تظهر في كل تواصل مع المريض.","bigEn":"General Psychology helps nursing students understand behaviour, learning, memory, motivation, emotion, stress, coping and individual differences relevant to patient care.","chunksAr":[{"kind":"concept","title":"التعلم والذاكرة","text":"التعلم يغير السلوك أو المعرفة عبر الخبرة، والذاكرة تحتاج ترميزًا وتخزينًا واسترجاعًا؛ الانتباه والمعنى والتكرار المنظم يساعدان التذكر."},{"kind":"concept","title":"الدافعية والانفعال","text":"الحاجات والأهداف والتوقعات تؤثر في السلوك، والانفعال يغير الانتباه والتواصل والقرارات."},{"kind":"concept","title":"الضغط والتكيف","text":"الضغط ليس مجرد حدث؛ يتأثر بتقييم الشخص للحدث وموارده ودعمه واستراتيجيات المواجهة."},{"kind":"concept","title":"الإدراك","text":"الإحساس يستقبل المثيرات، أما الإدراك فينظمها ويعطيها معنى؛ لذلك قد يختلف تفسير الموقف بين الأشخاص."},{"kind":"concept","title":"الشخصية والاختلاف الفردي","text":"لا تختزل المريض في صفة واحدة؛ السلوك ينتج من تفاعل الخبرة والسمات والبيئة والحالة الحالية."},{"kind":"lesson","title":"تطبيق تمريضي","text":"استخدم فهمك للانتباه والقلق والدافعية عند تثقيف المريض؛ المعلومات الكثيرة لا تفيد إذا كان الألم أو الخوف يمنع التركيز."}],"chunksEn":[{"kind":"concept","title":"Learning and memory","text":"Learning changes knowledge or behaviour through experience; memory involves encoding, storage and retrieval, helped by attention, meaning and spaced practice."},{"kind":"concept","title":"Motivation and emotion","text":"Needs, goals and expectations influence behaviour, while emotions change attention, communication and decision-making."},{"kind":"concept","title":"Stress and coping","text":"Stress depends not only on the event but also on appraisal, resources, support and coping strategies."},{"kind":"concept","title":"Perception","text":"Sensation receives stimuli; perception organises and interprets them, so people may experience the same situation differently."},{"kind":"concept","title":"Personality and individuality","text":"Avoid reducing a person to one trait; behaviour reflects traits, experience, environment and the current situation."},{"kind":"lesson","title":"Nursing application","text":"Use psychology when teaching: pain, fear or overload may prevent attention even when the information itself is correct."}],"sources":["openstax-psych"]},{"id":"english2","year":2,"sem":1,"code":"LANG 201ly","nAr":"اللغة الإنجليزية 2","nEn":"English Language 2","typeAr":"عام","typeEn":"General","bigAr":"في السنة الثانية تُستخدم اللغة داخل مواقف تمريضية حقيقية المعنى: وصف الأعراض، إعطاء التعليمات، طلب التوضيح، التأكد من الفهم، التواصل مع الفريق، قراءة النماذج والتقارير، ومصطلحات العينات والقسطرة والكلى وغيرها. تُدمج قواعد ومفردات دليل الوزارة داخل هذا السياق بدل دراستها منفصلة.","bigEn":"In Year 2, English is used inside nursing situations: describing symptoms, giving instructions, asking for clarification, checking understanding, contacting colleagues, reading forms/reports, and using vocabulary around specimens, catheters, renal care and other course topics. Ministry grammar and vocabulary are integrated into these clinical contexts.","chunksAr":[{"kind":"overview","title":"اللغة الإنجليزية 2","text":"في السنة الثانية تُستخدم اللغة داخل مواقف تمريضية حقيقية المعنى: وصف الأعراض، إعطاء التعليمات، طلب التوضيح، التأكد من الفهم، التواصل مع الفريق، قراءة النماذج والتقارير، ومصطلحات العينات والقسطرة والكلى وغيرها. تُدمج قواعد ومفردات دليل الوزارة داخل هذا السياق بدل دراستها منفصلة."},{"kind":"concept","title":"Adjectives","text":"تصف الاسم: severe pain, swollen ankle, clear fluid."},{"kind":"concept","title":"Adverbs","text":"تصف الفعل أو الطريقة: breathing rapidly, walking slowly."},{"kind":"concept","title":"Comparatives","text":"تساعد في وصف التغير: better, worse, higher, lower."},{"kind":"concept","title":"Prepositions","text":"تحدد المكان والاتجاه والعلاقة: below, above, between, through."},{"kind":"concept","title":"Clarification","text":"عندما لا تفهم، اسأل ولا تخمن."},{"kind":"concept","title":"Checking understanding","text":"بعد التعليمات، تأكد أن المريض فهم ما تقصده."},{"kind":"lesson","title":"وصف الألم والتغير","text":"sharp, dull, severe, mild, constant, intermittent؛ ثم قارن: better, worse, higher, lower."},{"kind":"lesson","title":"طلب التوضيح","text":"استخدم إعادة الصياغة والسؤال عند عدم وضوح التعليمات أو وصف المريض، ولا تعتمد على التخمين."},{"kind":"lesson","title":"التأكد من الفهم","text":"بعد شرح إجراء أو عينة، اطلب من المريض إعادة الخطوات أو إظهار ما فهمه."},{"kind":"lesson","title":"التواصل الهاتفي مع الفريق","text":"عرّف بنفسك، حدد المريض وسبب الاتصال، انقل المعلومة المهمة بدقة، وأعد الأرقام أو التعليمات المهمة."},{"kind":"lesson","title":"لغة العينات والتقارير","text":"تعلم مفردات specimen, urine, blood, contamination, pathology report, catheter, renal وغيرها داخل سياق سريري."},{"kind":"lesson","title":"مصطلحات من مقرراتك","text":"ادمج مفردات Pharmacology وMaternity وNutrition وRLE مع اللغة المهنية بدل حفظ الإنجليزية بمعزل عن التمريض."},{"kind":"scenario","title":"وصف غير واضح للألم","text":"تستخدم أسئلة مثل Where exactly? How severe? When did it start? للحصول على وصف أدق."},{"kind":"scenario","title":"تعليمات جمع عينة","text":"تشرح الخطوات بلغة قصيرة ثم تطلب من المريض أن يعيدها للتأكد من الفهم وتقليل التلوث."},{"kind":"scenario","title":"مكالمة بخصوص نتيجة أو عينة","text":"تنقل اسم المريض والسبب والنتيجة أو الإجراء المطلوب بوضوح وتطلب التوضيح إذا كانت المعلومة غير مكتملة."}],"chunksEn":[{"kind":"overview","title":"English Language 2","text":"In Year 2, English is used inside nursing situations: describing symptoms, giving instructions, asking for clarification, checking understanding, contacting colleagues, reading forms/reports, and using vocabulary around specimens, catheters, renal care and other course topics. Ministry grammar and vocabulary are integrated into these clinical contexts."},{"kind":"concept","title":"Adjectives","text":"severe pain, swollen ankle, clear fluid."},{"kind":"concept","title":"Adverbs","text":"breathing rapidly, walking slowly."},{"kind":"concept","title":"Comparatives","text":"better, worse, higher, lower."},{"kind":"concept","title":"Prepositions","text":"below, above, between, through."},{"kind":"concept","title":"Clarification","text":"Ask when meaning is unclear; do not guess."},{"kind":"concept","title":"Checking understanding","text":"After instructions, confirm that the patient understood."},{"kind":"lesson","title":"Describe pain and change","text":"Use precise descriptors and comparisons such as sharp, dull, severe, better, worse, higher and lower."},{"kind":"lesson","title":"Ask for clarification","text":"Paraphrase or ask for explanation when instructions or symptoms are unclear."},{"kind":"lesson","title":"Check understanding","text":"After explaining a procedure or specimen collection, ask the patient to repeat or demonstrate the key steps."},{"kind":"lesson","title":"Telephone communication","text":"Identify yourself, the patient and reason for calling; communicate relevant facts and confirm important instructions."},{"kind":"lesson","title":"Specimens and reports","text":"Use clinical vocabulary such as specimen, urine, contamination, pathology report, catheter and renal in context."},{"kind":"lesson","title":"Vocabulary from other courses","text":"Bring Pharmacology, Maternity, Nutrition and RLE terminology into nursing-English practice."},{"kind":"scenario","title":"An unclear pain description","text":"Use focused questions to clarify location, severity and timing."},{"kind":"scenario","title":"Explaining specimen collection","text":"Give short step-by-step instructions and use teach-back to reduce misunderstanding and contamination."},{"kind":"scenario","title":"Calling about a result or specimen","text":"State the patient, reason, relevant finding and requested action clearly, then confirm the response."}],"sources":[]},{"id":"patho","year":2,"sem":1,"code":"MED 201ly","nAr":"فسيولوجيا الأمراض","nEn":"Pathophysiology","typeAr":"طبي مساند","typeEn":"Supporting medical","bigAr":"هذا المقرر يربط «كيف يعمل الجسم طبيعيًا» بـ«ماذا يحدث عندما تختل الوظيفة». بدل حفظ قائمة أعراض، تتعلم سلسلة: سبب أو خلل → آلية مرضية → تغير في الوظيفة → علامات وأعراض → فحوص → آثار تمريضية.","bigEn":"Pathophysiology links normal function with what changes when function is disturbed. Instead of memorising symptoms, follow a chain: cause or disturbance → disease mechanism → altered function → signs/symptoms → tests → nursing implications.","chunksAr":[{"kind":"overview","title":"فسيولوجيا الأمراض","text":"هذا المقرر يربط «كيف يعمل الجسم طبيعيًا» بـ«ماذا يحدث عندما تختل الوظيفة». بدل حفظ قائمة أعراض، تتعلم سلسلة: سبب أو خلل → آلية مرضية → تغير في الوظيفة → علامات وأعراض → فحوص → آثار تمريضية."},{"kind":"concept","title":"الإجهاد والتكيف","text":"الخلايا والأجهزة تحاول التكيف مع الضغط، لكن الاستجابة قد تصبح غير كافية أو ضارة."},{"kind":"concept","title":"إصابة الخلية","text":"المرض قد يبدأ من تغير في وظيفة الخلية قبل أن يظهر كخلل واضح في العضو."},{"kind":"concept","title":"السوائل والأملاح","text":"الصوديوم والبوتاسيوم والماء والحمض/القاعدة تؤثر في الأعصاب والعضلات والدورة ووظائف الخلايا."},{"kind":"concept","title":"الالتهاب والمناعة","text":"استجابة الحماية قد تكون ضرورية، لكنها قد تسهم أيضًا في الضرر إذا زادت أو استمرت."},{"kind":"concept","title":"التروية والأكسجة","text":"كثير من الأعراض تُفهم عندما تسأل: هل يصل الدم والأكسجين بصورة كافية؟"},{"kind":"concept","title":"التعويض","text":"الجسم قد يعوض الخلل لفترة؛ لذلك قد تتغير العلامات قبل ظهور تدهور واضح."},{"kind":"lesson","title":"ابدأ بالطبيعي","text":"اكتب الوظيفة الطبيعية للعضو قبل دراسة المرض."},{"kind":"lesson","title":"حدد الخلل","text":"ما الجزء أو العملية التي تغيرت؟"},{"kind":"lesson","title":"تتبع النتيجة","text":"كيف ينتج عن الخلل أعراض أو علامات أو تغيرات مخبرية؟"},{"kind":"lesson","title":"قارن الأجهزة","text":"القلب والكلى والرئتان والسوائل تعمل معًا؛ لا تدرس كل جهاز وحده."},{"kind":"lesson","title":"اربط الفحص بالآلية","text":"لماذا طلب هذا الفحص؟ وما الوظيفة التي يحاول تقييمها؟"},{"kind":"lesson","title":"اسأل عن الآثار التمريضية","text":"ما الذي يحتاج الممرض إلى ملاحظته أو متابعته بسبب هذه الآلية؟"},{"kind":"scenario","title":"ضيق تنفس مع تورم","text":"بدل حفظ عرضين منفصلين، تفكر في السوائل والدورة والتروية وكيف قد يؤثر خلل جهاز في آخر."},{"kind":"scenario","title":"تغير مفاجئ في مستوى الوعي","text":"تتذكر أن الدماغ حساس للأكسجين والجلوكوز والشوارد والتروية، وأن الملاحظة السريعة مهمة."},{"kind":"scenario","title":"قيء وإسهال مستمران","text":"تبدأ في التفكير في فقد الماء والشوارد والحمض/القاعدة، لا في الجهاز الهضمي وحده."},{"kind":"scenario","title":"ارتفاع جلوكوز الدم","text":"تربط الهرمونات والاستقلاب والسوائل بالتغيرات التي قد تظهر على المريض."}],"chunksEn":[{"kind":"overview","title":"Pathophysiology","text":"Pathophysiology links normal function with what changes when function is disturbed. Instead of memorising symptoms, follow a chain: cause or disturbance → disease mechanism → altered function → signs/symptoms → tests → nursing implications."},{"kind":"concept","title":"Stress & adaptation","text":"Cells and systems attempt to adapt to stress, but adaptation can fail or become harmful."},{"kind":"concept","title":"Cell injury","text":"Disease may begin with altered cellular function before obvious organ failure."},{"kind":"concept","title":"Fluids & electrolytes","text":"Water, sodium, potassium and acid-base balance affect nerves, muscles, circulation and cells."},{"kind":"concept","title":"Inflammation & defence","text":"Protective responses can also contribute to damage when excessive or prolonged."},{"kind":"concept","title":"Perfusion & oxygenation","text":"Many findings become clearer when you ask whether blood and oxygen are reaching tissues."},{"kind":"concept","title":"Compensation","text":"The body may compensate for dysfunction, changing observations before obvious deterioration."},{"kind":"lesson","title":"Start with normal","text":"Write down the normal function before studying the disorder."},{"kind":"lesson","title":"Identify the disturbance","text":"Which structure or process has changed?"},{"kind":"lesson","title":"Trace the consequence","text":"How does the disturbance produce manifestations or lab changes?"},{"kind":"lesson","title":"Connect systems","text":"Heart, lungs, kidneys and fluids interact."},{"kind":"lesson","title":"Link tests to mechanism","text":"What body function is the test trying to assess?"},{"kind":"lesson","title":"Ask the nursing implication","text":"What does the nurse need to observe because of this mechanism?"},{"kind":"scenario","title":"Shortness of breath with swelling","text":"Think about circulation, fluid movement and interaction between systems."},{"kind":"scenario","title":"Sudden change in consciousness","text":"Remember brain dependence on oxygen, glucose, electrolytes and perfusion."},{"kind":"scenario","title":"Ongoing vomiting and diarrhoea","text":"Think beyond the gut to water, electrolytes and acid-base balance."},{"kind":"scenario","title":"High blood glucose","text":"Connect hormones, metabolism and fluid changes."}],"sources":[]},{"id":"pharm","year":2,"sem":1,"code":"MED 202ly","nAr":"علم الأدوية","nEn":"Pharmacology","typeAr":"طبي مساند","typeEn":"Supporting medical","bigAr":"علم الأدوية ليس حفظ أسماء أدوية. الفكرة الأساسية هي: ماذا يفعل الدواء بالجسم؟ ماذا يفعل الجسم بالدواء؟ ما التأثير المتوقع؟ ما الخطر المحتمل؟ وما مسؤولية الممرض قبل الإعطاء وأثناءه وبعده؟","bigEn":"Pharmacology is not simply memorising drug names. Ask: What does the drug do to the body? What does the body do to the drug? What effect is expected? What can go wrong? What must the nurse assess before, during and after administration?","chunksAr":[{"kind":"overview","title":"علم الأدوية","text":"علم الأدوية ليس حفظ أسماء أدوية. الفكرة الأساسية هي: ماذا يفعل الدواء بالجسم؟ ماذا يفعل الجسم بالدواء؟ ما التأثير المتوقع؟ ما الخطر المحتمل؟ وما مسؤولية الممرض قبل الإعطاء وأثناءه وبعده؟"},{"kind":"concept","title":"Pharmacodynamics","text":"كيف يؤثر الدواء في الجسم: المستقبلات، التأثير، الجرعة والاستجابة."},{"kind":"concept","title":"Pharmacokinetics","text":"كيف يتعامل الجسم مع الدواء: امتصاص، توزيع، استقلاب وإطراح."},{"kind":"concept","title":"Therapeutic effect","text":"التأثير المطلوب الذي أعطي الدواء من أجله."},{"kind":"concept","title":"Adverse effects","text":"تأثيرات غير مرغوبة تحتاج معرفة ومراقبة وتمييزًا عن التأثير المتوقع."},{"kind":"concept","title":"Medication rights","text":"سلامة الدواء تعتمد على التحقق المنظم من المريض والدواء والجرعة والطريق والوقت وغيرها."},{"kind":"concept","title":"Calculations","text":"الحساب ليس رياضيات منفصلة؛ الخطأ العددي قد يتحول إلى خطأ دوائي."},{"kind":"lesson","title":"الأوامر الدوائية","text":"تعلم قراءة اسم الدواء والجرعة والطريق والتكرار والتوقيت."},{"kind":"lesson","title":"Routes","text":"الفموي، الموضعي، الاستنشاقي والحقني تختلف في الاستخدام وسرعة التأثير والمخاطر."},{"kind":"lesson","title":"التصنيفات","text":"ادرس كل مجموعة عبر: آلية عامة → استخدامات → آثار جانبية → احتياطات → ملاحظات تمريضية."},{"kind":"lesson","title":"Antimicrobials","text":"افهم الهدف من المضادات ومشكلة الاستخدام غير الرشيد والمقاومة."},{"kind":"lesson","title":"Cardiovascular drugs","text":"اربط الدواء بالضغط والنبض والسوائل ووظيفة القلب."},{"kind":"lesson","title":"Analgesics & others","text":"اربط التأثير المطلوب بالمراقبة والآثار الجانبية، لا بالاسم فقط."},{"kind":"scenario","title":"دواء قد يخفض الضغط","text":"قبل الإعطاء لا يكفي قراءة الاسم؛ تحتاج فهم التأثير المتوقع وما يجب ملاحظته ومتى تراجع التعليمات."},{"kind":"scenario","title":"مريض يقول إن دواءه «أتعبه»","text":"تحتاج سؤالًا منظمًا عن العرض والتوقيت والجرعة بدل تجاهل الشكوى أو إيقاف الدواء من نفسك."},{"kind":"scenario","title":"حساب جرعة","text":"تراجع الوحدة والجرعة المطلوبة والمتاحة قبل الحساب، لأن الخطأ في mg وmL قد يكون مهمًا."},{"kind":"scenario","title":"مضاد حيوي","text":"تعرف أن الالتزام بالوصفة والتوقيت والتقييم جزء من الاستخدام الآمن، وأن المضاد لا يعالج كل عدوى."}],"chunksEn":[{"kind":"overview","title":"Pharmacology","text":"Pharmacology is not simply memorising drug names. Ask: What does the drug do to the body? What does the body do to the drug? What effect is expected? What can go wrong? What must the nurse assess before, during and after administration?"},{"kind":"concept","title":"Pharmacodynamics","text":"How a drug affects the body."},{"kind":"concept","title":"Pharmacokinetics","text":"Absorption, distribution, metabolism and excretion."},{"kind":"concept","title":"Therapeutic effect","text":"The intended beneficial effect."},{"kind":"concept","title":"Adverse effects","text":"Unwanted effects requiring recognition and monitoring."},{"kind":"concept","title":"Medication rights","text":"Repeated safety checks reduce medication error risk."},{"kind":"concept","title":"Calculations","text":"A numerical error can become a medication error."},{"kind":"lesson","title":"Medication orders","text":"Read drug, dose, route, frequency and timing."},{"kind":"lesson","title":"Routes","text":"Oral, topical, inhaled and parenteral routes differ in use and risk."},{"kind":"lesson","title":"Drug classes","text":"Study each class through action, use, adverse effects, cautions and nursing observations."},{"kind":"lesson","title":"Antimicrobials","text":"Understand purpose, safe use and antimicrobial resistance."},{"kind":"lesson","title":"Cardiovascular drugs","text":"Connect medicines with blood pressure, pulse, fluids and cardiac function."},{"kind":"lesson","title":"Analgesics and others","text":"Connect intended effects with monitoring and unwanted effects."},{"kind":"scenario","title":"A medicine may lower blood pressure","text":"Anticipate the expected effect and relevant observations before and after administration."},{"kind":"scenario","title":"A patient says a medicine made them feel unwell","text":"Clarify the symptom, timing and dose rather than dismissing it or stopping medicine independently."},{"kind":"scenario","title":"Dose calculation","text":"Check units, required dose and available strength before calculating."},{"kind":"scenario","title":"Antibiotic use","text":"Understand timing, prescribed use and why antibiotics do not treat every infection."}],"sources":["openrn-pharm"]},{"id":"nutrition","year":2,"sem":1,"code":"MED 203ly","nAr":"التغذية","nEn":"Nutrition","typeAr":"طبي مساند","typeEn":"Supporting medical","bigAr":"التغذية تشرح كيف يستخدم الجسم الطعام للنمو والطاقة والإصلاح والحفاظ على الوظائف. المطلوب ليس حفظ قائمة أطعمة، بل فهم الاحتياج، التوازن، العمر، الحالة الصحية والسياق.","bigEn":"Nutrition explains how food supports energy, growth, repair and body function. The goal is not to memorise food lists, but to understand needs, balance, age, health status and real-life context.","chunksAr":[{"kind":"overview","title":"التغذية","text":"التغذية تشرح كيف يستخدم الجسم الطعام للنمو والطاقة والإصلاح والحفاظ على الوظائف. المطلوب ليس حفظ قائمة أطعمة، بل فهم الاحتياج، التوازن، العمر، الحالة الصحية والسياق."},{"kind":"concept","title":"Macronutrients","text":"الكربوهيدرات والبروتين والدهون لها أدوار مختلفة في الطاقة والبناء والوظائف."},{"kind":"concept","title":"Micronutrients","text":"الفيتامينات والمعادن بكميات صغيرة قد تكون ضرورية لعمليات كبيرة."},{"kind":"concept","title":"Energy needs","text":"الاحتياج يتغير مع العمر والنشاط والحمل والمرض وغيرها."},{"kind":"concept","title":"Water","text":"الماء عنصر غذائي أساسي يرتبط بالدورة والحرارة والإطراح والخلايا."},{"kind":"concept","title":"Lifespan nutrition","text":"احتياجات الرضيع والمراهق والحامل وكبير السن ليست متطابقة."},{"kind":"concept","title":"Malnutrition","text":"قد يعني نقص الطاقة أو البروتين أو المغذيات، وليس فقط انخفاض الوزن."},{"kind":"lesson","title":"اقرأ الوجبة كمغذيات","text":"اسأل ماذا تقدم الوجبة من طاقة وبروتين ودهون وألياف وفيتامينات."},{"kind":"lesson","title":"لا يوجد طعام واحد كامل","text":"التنوع والتوازن أهم من البحث عن «طعام سحري»."},{"kind":"lesson","title":"العمر يغير الحاجة","text":"النمو والحمل والرضاعة والشيخوخة تغير الأولويات."},{"kind":"lesson","title":"المرض يغير الحاجة","text":"السكري وأمراض القلب وغيرها قد تتطلب تعديلًا غذائيًا مدروسًا."},{"kind":"lesson","title":"المعرفة لا تكفي","text":"الثقافة والدخل والتوافر والقدرة على المضغ أو البلع قد تغير الخطة."},{"kind":"lesson","title":"التثقيف الغذائي","text":"حوّل النصيحة إلى خطوات واقعية يمكن للشخص تنفيذها."},{"kind":"scenario","title":"مريضة حامل تسأل ماذا تأكل","text":"لا تعطي قائمة عشوائية؛ تفكر في الاحتياج المتغير والتوازن والغذاء الآمن والتوجيه المعتمد."},{"kind":"scenario","title":"كبير سن يأكل قليلًا","text":"تفكر في الشهية والأسنان والبلع والموارد والمرض والأدوية، لا في السعرات فقط."},{"kind":"scenario","title":"شخص مصاب بالسكري","text":"تفهم أن توزيع الكربوهيدرات ونمط الطعام جزء من الصورة، وليس منع «السكر» فقط."},{"kind":"scenario","title":"طفل ينمو ببطء","text":"تعرف أن التغذية أحد عوامل النمو، لكن التقييم يحتاج سياقًا أوسع."}],"chunksEn":[{"kind":"overview","title":"Nutrition","text":"Nutrition explains how food supports energy, growth, repair and body function. The goal is not to memorise food lists, but to understand needs, balance, age, health status and real-life context."},{"kind":"concept","title":"Macronutrients","text":"Carbohydrates, proteins and fats have different roles."},{"kind":"concept","title":"Micronutrients","text":"Vitamins and minerals are needed in small amounts but can have major effects."},{"kind":"concept","title":"Energy needs","text":"Needs vary with age, activity, pregnancy and illness."},{"kind":"concept","title":"Water","text":"Essential for circulation, temperature, elimination and cells."},{"kind":"concept","title":"Lifespan nutrition","text":"Infants, adolescents, pregnant women and older adults have different needs."},{"kind":"concept","title":"Malnutrition","text":"Can involve energy, protein or micronutrient deficiency—not only low body weight."},{"kind":"lesson","title":"Read a meal as nutrients","text":"Ask what energy, protein, fat, fibre and micronutrients it provides."},{"kind":"lesson","title":"No single perfect food","text":"Balance and variety matter."},{"kind":"lesson","title":"Age changes needs","text":"Growth, pregnancy, lactation and ageing change priorities."},{"kind":"lesson","title":"Disease changes needs","text":"Diabetes and cardiovascular disease may require structured dietary modification."},{"kind":"lesson","title":"Context matters","text":"Culture, income, availability, chewing and swallowing influence diet."},{"kind":"lesson","title":"Teach realistically","text":"Turn advice into practical actions the person can follow."},{"kind":"scenario","title":"A pregnant woman asks what to eat","text":"Think about changing requirements, balance and approved guidance rather than random food lists."},{"kind":"scenario","title":"An older adult eats very little","text":"Consider appetite, teeth, swallowing, resources, illness and medicines."},{"kind":"scenario","title":"A person with diabetes","text":"Think about carbohydrate patterns and overall diet, not simply banning 'sugar'."},{"kind":"scenario","title":"A child is growing slowly","text":"Nutrition is one factor in growth, but assessment needs a broader context."}],"sources":["openrn-healthpromo"]},{"id":"maternity","year":2,"sem":1,"code":"NURS 201ly","nAr":"تمريض الأمومة","nEn":"Maternity Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"تمريض الأمومة يتابع رحلة المرأة والأسرة من الصحة الإنجابية والحمل إلى المخاض والولادة والنفاس والرضاعة، مع التمييز بين التغير الطبيعي وعلامات الخطر التي تحتاج انتباهًا سريعًا.","bigEn":"Maternity Nursing follows women and families from reproductive health and pregnancy through labour, birth, postpartum care and breastfeeding, while distinguishing normal change from danger signs that require prompt attention.","chunksAr":[{"kind":"overview","title":"تمريض الأمومة","text":"تمريض الأمومة يتابع رحلة المرأة والأسرة من الصحة الإنجابية والحمل إلى المخاض والولادة والنفاس والرضاعة، مع التمييز بين التغير الطبيعي وعلامات الخطر التي تحتاج انتباهًا سريعًا."},{"kind":"concept","title":"الدورة والتبويض","text":"فهم الدورة يساعدك على فهم الإخصاب وبداية الحمل."},{"kind":"concept","title":"الحمل الطبيعي","text":"يتغير جسم المرأة نفسيًا وجسديًا عبر الثلث الأول والثاني والثالث."},{"kind":"concept","title":"Antepartum care","text":"المتابعة قبل الولادة تهدف إلى تعزيز الصحة واكتشاف المخاطر مبكرًا."},{"kind":"concept","title":"Fetal wellbeing","text":"نمو الجنين وحركته والدوران الجنيني والتقييمات تساعد على متابعة سلامته."},{"kind":"concept","title":"Labor","text":"المخاض عملية متدرجة لها مراحل وحركات جنينية وتغيرات في الأم."},{"kind":"concept","title":"Postpartum","text":"بعد الولادة تستمر المراقبة: النزف، الرحم، lochia، الرضاعة والتكيف."},{"kind":"lesson","title":"علامات الحمل","text":"فرّق بين presumptive وprobable وpositive signs."},{"kind":"lesson","title":"حساب عمر الحمل والموعد","text":"افهم LMP وEDC ومبادئ التاريخ الولادي بدل حفظ اختصارات بلا معنى."},{"kind":"lesson","title":"Leopold's maneuver","text":"طريقة منظمة للتعرف إلى وضع الجنين خارجيًا ضمن التدريب والإشراف."},{"kind":"lesson","title":"علامات الخطر","text":"النزف، الصداع الشديد، زغللة الرؤية، نقص حركة الجنين أو خروج سائل مفاجئ أمثلة تحتاج انتباهًا وتقييمًا."},{"kind":"lesson","title":"المخاض الحقيقي والكاذب","text":"تعرف الفروق العامة وتغيرات عنق الرحم وتقدم المخاض."},{"kind":"lesson","title":"الوليد والرضاعة","text":"الرعاية الأساسية والحرارة والرضاعة والارتباط جزء من استمرارية رعاية الأم والطفل."},{"kind":"scenario","title":"حامل تقول إن حركة الجنين أقل من المعتاد","text":"تدرك أن هذه ليست شكوى عابرة وتحتاج إبلاغًا وتقييمًا وفق الإجراء."},{"kind":"scenario","title":"صداع شديد مع زغللة وتورم","text":"تربط الأعراض بعلامات خطر في الحمل وتتعامل معها بجدية بدل وصفها كإزعاج عادي."},{"kind":"scenario","title":"نزف بعد الولادة","text":"تعرف أن كمية النزف وحالة الرحم والعلامات الحيوية ملاحظات مهمة ويجب التصعيد وفق البروتوكول."},{"kind":"scenario","title":"أم تواجه صعوبة في الرضاعة","text":"تحتاج ملاحظة الوضعية والالتقام والراحة والتثقيف بدل افتراض أنها «لا تعرف»."}],"chunksEn":[{"kind":"overview","title":"Maternity Nursing","text":"Maternity Nursing follows women and families from reproductive health and pregnancy through labour, birth, postpartum care and breastfeeding, while distinguishing normal change from danger signs that require prompt attention."},{"kind":"concept","title":"Cycle & ovulation","text":"Understanding the reproductive cycle supports understanding conception and pregnancy."},{"kind":"concept","title":"Normal pregnancy","text":"Physical and psychological changes evolve across trimesters."},{"kind":"concept","title":"Antepartum care","text":"Promotes health and identifies risk early."},{"kind":"concept","title":"Fetal wellbeing","text":"Growth, movement and fetal circulation support assessment."},{"kind":"concept","title":"Labour","text":"A staged process with maternal and fetal changes."},{"kind":"concept","title":"Postpartum","text":"Observation continues after birth: bleeding, uterus, lochia, breastfeeding and adaptation."},{"kind":"lesson","title":"Pregnancy signs","text":"Differentiate presumptive, probable and positive signs."},{"kind":"lesson","title":"Gestational dating","text":"Understand LMP, EDC and obstetric history concepts."},{"kind":"lesson","title":"Leopold's manoeuvres","text":"An organised approach to external fetal assessment under supervision."},{"kind":"lesson","title":"Danger signs","text":"Bleeding, severe headache, blurred vision, decreased fetal movement or sudden fluid loss require attention."},{"kind":"lesson","title":"True vs false labour","text":"Understand general differences and labour progression."},{"kind":"lesson","title":"Newborn & breastfeeding","text":"Basic newborn care, temperature and feeding are part of maternal-child continuity."},{"kind":"scenario","title":"Reduced fetal movement","text":"Recognise it as a finding that requires reporting and assessment."},{"kind":"scenario","title":"Severe headache with blurred vision","text":"Recognise danger signs rather than treating them as ordinary discomfort."},{"kind":"scenario","title":"Postpartum bleeding","text":"Bleeding amount, uterine findings and vital signs matter."},{"kind":"scenario","title":"Breastfeeding difficulty","text":"Assess position, attachment, comfort and teaching rather than assuming lack of knowledge."}],"sources":["openrn-fund","openrn-skills","openrn-healthpromo"]},{"id":"rle3","year":2,"sem":1,"code":"NURS 202ly","nAr":"الخبرة التعليمية المرتبطة 3","nEn":"Related Learning Experience 3","typeAr":"عملي تمريضي","typeEn":"Practical nursing","bigAr":"هذا المقرر يحول مفاهيم الأمومة والطفولة والعناية الأساسية إلى مهارات: تقييم الحمل، رعاية الوليد، جمع العينات، القسطرة، العناية بالجلد والجرح، ودعم الاحتياجات النفسية والروحية.","bigEn":"RLE 3 turns maternal-child and basic care concepts into skills: pregnancy assessment, newborn care, specimen collection, catheter-related skills, wound/skin care, asepsis and emotional/spiritual support.","chunksAr":[{"kind":"overview","title":"الخبرة التعليمية المرتبطة 3","text":"هذا المقرر يحول مفاهيم الأمومة والطفولة والعناية الأساسية إلى مهارات: تقييم الحمل، رعاية الوليد، جمع العينات، القسطرة، العناية بالجلد والجرح، ودعم الاحتياجات النفسية والروحية."},{"kind":"concept","title":"Assessment before action","text":"أي مهارة تبدأ بتقييم الحاجة والمخاطر والخصوصية."},{"kind":"concept","title":"Aseptic technique","text":"الحفاظ على النظافة ومنع التلوث مهم في العينات والقسطرة والعناية."},{"kind":"concept","title":"Maternal assessment","text":"Leopold وfundal height مهارات لها هدف سريري وليست حركات للحفظ."},{"kind":"concept","title":"Infant care","text":"الحرارة والقياسات والرضاعة والعناية بالحبل ترتبط بسلامة الوليد."},{"kind":"concept","title":"Specimens","text":"جودة العينة تؤثر في جودة نتيجة المختبر."},{"kind":"concept","title":"Dignity at end of life","text":"رعاية المحتضر وما بعد الوفاة تحتاج احترامًا وهدوءًا وحساسية للأسرة والثقافة."},{"kind":"lesson","title":"Leopold & fundal height","text":"تعرف الهدف قبل التدريب على الحركة."},{"kind":"lesson","title":"Breastfeeding & infant bath","text":"السلامة والحرارة والخصوصية والتثقيف جزء من المهارة."},{"kind":"lesson","title":"Anthropometric measures","text":"الطول والوزن وغيرها لها معنى عند متابعتها في سياق العمر والنمو."},{"kind":"lesson","title":"Urine/stool specimens","text":"الطريقة المناسبة تقلل التلوث وتحسن موثوقية النتيجة."},{"kind":"lesson","title":"Urinary catheterization","text":"مهارة معقمة تحتاج تحقق الهوية والخصوصية والتقنية والتوثيق."},{"kind":"lesson","title":"End-of-life care","text":"لا تنس الاحتياجات النفسية والروحية للأسرة والمريض."},{"kind":"scenario","title":"عينة بول ملوثة","text":"تفهم أن المشكلة قد تكون في طريقة الجمع لا في المختبر، لذلك التعليم والتحقق مهمان."},{"kind":"scenario","title":"قسطرة لا يتدفق منها البول كما المتوقع","text":"لا تتعامل معها بالقوة؛ راجع الوضع والتقنية واطلب الإشراف حسب البروتوكول."},{"kind":"scenario","title":"وليد يفقد الحرارة بسرعة","text":"تعرف أن الرضع أكثر حساسية لفقد الحرارة وأن الحفاظ على الدفء جزء من الرعاية."},{"kind":"scenario","title":"أسرة بجانب مريض يحتضر","text":"المهارة هنا ليست جهازًا أو قياسًا فقط؛ التواصل والخصوصية والاحترام جزء من الرعاية."}],"chunksEn":[{"kind":"overview","title":"Related Learning Experience 3","text":"RLE 3 turns maternal-child and basic care concepts into skills: pregnancy assessment, newborn care, specimen collection, catheter-related skills, wound/skin care, asepsis and emotional/spiritual support."},{"kind":"concept","title":"Assessment before action","text":"Every skill starts with need, risk and privacy assessment."},{"kind":"concept","title":"Aseptic technique","text":"Prevent contamination during specimens, catheter care and procedures."},{"kind":"concept","title":"Maternal assessment","text":"Leopold's manoeuvres and fundal height have clinical purposes."},{"kind":"concept","title":"Infant care","text":"Temperature, measurements, breastfeeding and cord care support newborn safety."},{"kind":"concept","title":"Specimens","text":"Collection quality affects laboratory reliability."},{"kind":"concept","title":"End-of-life dignity","text":"Care of dying patients requires respect, privacy and sensitivity."},{"kind":"lesson","title":"Leopold & fundal height","text":"Know the purpose before practising the movement."},{"kind":"lesson","title":"Breastfeeding & infant bath","text":"Safety, warmth, privacy and education matter."},{"kind":"lesson","title":"Anthropometric measures","text":"Interpret measurements within age and growth context."},{"kind":"lesson","title":"Urine/stool specimens","text":"Correct collection reduces contamination."},{"kind":"lesson","title":"Urinary catheterisation","text":"Requires identity checks, privacy, asepsis and documentation."},{"kind":"lesson","title":"End-of-life care","text":"Psychological and spiritual needs are part of nursing care."},{"kind":"scenario","title":"A contaminated urine specimen","text":"Collection technique may be the problem, so education and checking matter."},{"kind":"scenario","title":"A catheter is not draining as expected","text":"Do not force it; review position/technique and seek supervision according to policy."},{"kind":"scenario","title":"A newborn loses heat quickly","text":"Recognise newborn sensitivity to heat loss."},{"kind":"scenario","title":"Family beside a dying patient","text":"Communication, privacy and respect are clinical care too."}],"sources":["openrn-fund","openrn-skills","who-safety"]},{"id":"healthedu","year":2,"sem":2,"code":"EDUC 201ly","nAr":"استراتيجيات التثقيف الصحي","nEn":"Strategies in Health Education","typeAr":"عام وفق المادة 6","typeEn":"General (Article 6)","bigAr":"الممرض يعلّم طوال الوقت: يشرح دواءً، جرحًا، غذاءً، تمرينًا، وقاية أو مهارة. التثقيف الصحي ليس إلقاء معلومات؛ هو تحديد ما يحتاج الشخص تعلمه، اختيار الطريقة، التأكد من الفهم، ثم تقييم النتيجة.","bigEn":"Nurses teach constantly: medicines, wounds, diet, exercise, prevention and skills. Health education is not information dumping—it means identifying learning needs, choosing a method, checking understanding and evaluating the result.","chunksAr":[{"kind":"overview","title":"استراتيجيات التثقيف الصحي","text":"الممرض يعلّم طوال الوقت: يشرح دواءً، جرحًا، غذاءً، تمرينًا، وقاية أو مهارة. التثقيف الصحي ليس إلقاء معلومات؛ هو تحديد ما يحتاج الشخص تعلمه، اختيار الطريقة، التأكد من الفهم، ثم تقييم النتيجة."},{"kind":"concept","title":"Readiness to learn","text":"هل الشخص مستعد الآن؟ الألم والخوف والإرهاق قد يمنع التعلم."},{"kind":"concept","title":"Learning needs","text":"ما الذي يحتاجه فعلًا ليحافظ على صحته أو يتصرف بأمان؟"},{"kind":"concept","title":"Objectives","text":"اجعل الهدف قابلًا للملاحظة: ماذا سيعرف أو يفعل بعد التعليم؟"},{"kind":"concept","title":"Teaching methods","text":"اختر شرحًا أو صورة أو مناقشة أو عرض مهارة حسب الهدف."},{"kind":"concept","title":"Culture & literacy","text":"المحتوى يجب أن يناسب اللغة والثقافة والقدرة على القراءة."},{"kind":"concept","title":"Evaluation","text":"لا تفترض أن التعليم نجح؛ اختبر الفهم أو الأداء."},{"kind":"lesson","title":"Plan","text":"حدد المتعلم والحاجة والهدف والوقت والمكان."},{"kind":"lesson","title":"Teach","text":"استخدم أسلوبًا يناسب الهدف والشخص."},{"kind":"lesson","title":"Demonstrate","text":"في المهارات الحركية، اعرض بوضوح ثم اسمح بالتدريب."},{"kind":"lesson","title":"Question","text":"الأسئلة تكشف الفهم وتشجع التفكير."},{"kind":"lesson","title":"Use visuals wisely","text":"الصورة أو الفيديو أداة، وليست هدفًا بحد ذاته."},{"kind":"lesson","title":"Evaluate","text":"استخدم teach-back أو إعادة الأداء أو سؤالًا تطبيقيًا."},{"kind":"scenario","title":"مريض خرج بدواء جديد","text":"بدل قراءة ورقة طويلة، ركز على ما يجب أن يعرفه واطلب منه أن يشرح لك كيف سيستخدم الدواء."},{"kind":"scenario","title":"تثقيف أم عن رعاية طفل","text":"اختر كلمات وأمثلة تناسب خلفيتها واطلب منها تطبيق أو إعادة الفكرة."},{"kind":"scenario","title":"تعليم مهارة عملية","text":"المحاضرة وحدها لا تكفي؛ يحتاج المتعلم مشاهدة وتدريبًا وتغذية راجعة."}],"chunksEn":[{"kind":"overview","title":"Strategies in Health Education","text":"Nurses teach constantly: medicines, wounds, diet, exercise, prevention and skills. Health education is not information dumping—it means identifying learning needs, choosing a method, checking understanding and evaluating the result."},{"kind":"concept","title":"Readiness to learn","text":"Pain, fear or fatigue may reduce learning readiness."},{"kind":"concept","title":"Learning needs","text":"What does this person actually need to know or do safely?"},{"kind":"concept","title":"Objectives","text":"Make outcomes observable and practical."},{"kind":"concept","title":"Teaching methods","text":"Choose explanation, images, discussion or demonstration to fit the goal."},{"kind":"concept","title":"Culture & literacy","text":"Teaching should fit language, culture and reading ability."},{"kind":"concept","title":"Evaluation","text":"Do not assume teaching worked; check understanding or performance."},{"kind":"lesson","title":"Plan","text":"Define learner, need, objective, time and setting."},{"kind":"lesson","title":"Teach","text":"Select a method appropriate to the person and goal."},{"kind":"lesson","title":"Demonstrate","text":"Psychomotor skills need visible demonstration and practice."},{"kind":"lesson","title":"Question","text":"Questions reveal understanding and support thinking."},{"kind":"lesson","title":"Use visuals wisely","text":"Media support teaching; they do not replace a teaching plan."},{"kind":"lesson","title":"Evaluate","text":"Use teach-back, return demonstration or application questions."},{"kind":"scenario","title":"A patient leaves with a new medicine","text":"Focus on key safe-use points and ask the patient to explain how they will use it."},{"kind":"scenario","title":"Teaching a parent about child care","text":"Use language and examples that fit the learner."},{"kind":"scenario","title":"Teaching a practical skill","text":"A lecture alone is not enough; observation, practice and feedback are needed."}],"sources":["openrn-healthpromo"]},{"id":"comm2","year":2,"sem":2,"code":"LANG 202ly","nAr":"مهارات التواصل 2","nEn":"Communication Skills 2","typeAr":"عام","typeEn":"General","bigAr":"التواصل في هذه المرحلة يصبح تواصلًا تمريضيًا وظيفيًا: قراءة نص صحي، كتابة معلومات واضحة، تعبئة نماذج المريض، طلب التوضيح، التأكد من الفهم، شرح إجراء بسيط، إجراء مكالمة مهنية، وفهم مفردات سريرية من مواقف التمريض.","bigEn":"Communication becomes functional nursing communication: reading health information, writing clearly, completing patient forms, asking for clarification, checking understanding, explaining simple procedures, making professional telephone calls and using clinical vocabulary accurately.","chunksAr":[{"kind":"overview","title":"مهارات التواصل 2","text":"التواصل في هذه المرحلة يصبح تواصلًا تمريضيًا وظيفيًا: قراءة نص صحي، كتابة معلومات واضحة، تعبئة نماذج المريض، طلب التوضيح، التأكد من الفهم، شرح إجراء بسيط، إجراء مكالمة مهنية، وفهم مفردات سريرية من مواقف التمريض."},{"kind":"concept","title":"Active listening","text":"استمع للمعنى والمشاعر وما يحتاج توضيحًا."},{"kind":"concept","title":"Clarification","text":"اطلب إعادة أو تفسير المعلومة بدل التخمين."},{"kind":"concept","title":"Technical writing","text":"اكتب حقيقة محددة ومفهومة بدل وصف مبهم."},{"kind":"concept","title":"Forms","text":"افهم الحقول والمصطلحات قبل تعبئة بيانات المريض."},{"kind":"concept","title":"Pronunciation","text":"النطق الواضح مهم خصوصًا للأرقام والأدوية والأسماء."},{"kind":"concept","title":"Professional tone","text":"اللغة المحترمة والمباشرة تختلف عن المحادثة العادية."},{"kind":"lesson","title":"Read for purpose","text":"ابحث عن المطلوب في التقرير أو النموذج: عرض، عينة، نتيجة، وقت، رقم أو إجراء."},{"kind":"lesson","title":"Ask for clarification","text":"أعد صياغة ما سمعته أو اطلب شرحًا إضافيًا عندما تكون التعليمات أو الأعراض غير واضحة."},{"kind":"lesson","title":"Check understanding","text":"اطلب من المريض إعادة الخطوات أو شرح ما فهمه بعد التعليمات."},{"kind":"lesson","title":"Telephone skills","text":"ابدأ بهويتك، حدد المريض والسبب، أعط المعلومات ذات الصلة، ثم أكد ما تم الاتفاق عليه."},{"kind":"lesson","title":"Explain clinical ideas simply","text":"اشرح مفاهيم مثل urine specimen أو catheter أو renal function بلغة يفهمها المريض."},{"kind":"lesson","title":"Read clinical forms","text":"تدرب على pathology reports والنماذج الأساسية واستخراج المعلومات المهمة منها."},{"kind":"scenario","title":"مكالمة للطبيب أو عضو الفريق","text":"معلومة ناقصة أو رقم غير واضح قد يغير القرار؛ استخدم ترتيبًا واضحًا وتحقق من المعلومة."},{"kind":"scenario","title":"جمع عينة بول","text":"تشرح للمريض الخطوات، تتأكد أنه فهمها، وتستخدم كلمات واضحة تقلل الخطأ والتلوث."},{"kind":"scenario","title":"تعبئة نموذج أو قراءة تقرير","text":"لا تكتفِ برؤية الأرقام؛ حدد اسم الفحص والعينة والنتيجة وما يحتاج نقله للفريق."}],"chunksEn":[{"kind":"overview","title":"Communication Skills 2","text":"Communication becomes functional nursing communication: reading health information, writing clearly, completing patient forms, asking for clarification, checking understanding, explaining simple procedures, making professional telephone calls and using clinical vocabulary accurately."},{"kind":"concept","title":"Active listening","text":"Listen for meaning, emotion and what needs clarification."},{"kind":"concept","title":"Clarification","text":"Ask for repetition or explanation rather than guessing."},{"kind":"concept","title":"Technical writing","text":"Use specific facts rather than vague judgement."},{"kind":"concept","title":"Forms","text":"Understand fields and terminology before entering data."},{"kind":"concept","title":"Pronunciation","text":"Clear pronunciation matters especially for numbers, medicines and names."},{"kind":"concept","title":"Professional tone","text":"Respectful, direct professional language differs from casual speech."},{"kind":"lesson","title":"Read for purpose","text":"Identify the symptom, specimen, result, time, number or instruction you need."},{"kind":"lesson","title":"Ask for clarification","text":"Use repetition and paraphrasing instead of guessing."},{"kind":"lesson","title":"Check understanding","text":"Ask the patient to repeat key instructions or show what they understood."},{"kind":"lesson","title":"Telephone skills","text":"Identify yourself, patient and reason for calling; present relevant information and confirm next steps."},{"kind":"lesson","title":"Explain clinical ideas simply","text":"Explain terms such as specimen, catheter or renal function in patient-friendly language."},{"kind":"lesson","title":"Read clinical forms","text":"Practise extracting important information from pathology reports and common patient forms."},{"kind":"scenario","title":"Calling another team member","text":"Incomplete information or an unclear number can matter; organise and verify."},{"kind":"scenario","title":"Collecting a urine specimen","text":"Explain the steps clearly, check understanding and reduce contamination risk."},{"kind":"scenario","title":"Reading a clinical report","text":"Identify the specimen, test, result and what needs to be communicated rather than seeing only numbers."}],"sources":["who-safety"]},{"id":"therdiet","year":2,"sem":2,"code":"MED 204ly","nAr":"التغذية العلاجية","nEn":"Therapeutic Dietetics","typeAr":"طبي مساند","typeEn":"Supporting medical","bigAr":"التغذية العلاجية تبدأ من سؤال: كيف نعدّل الغذاء أو طريقة تقديمه ليتناسب مع حالة المريض؟ قد يكون التعديل في القوام أو المكونات أو طريق التغذية، مع مراعاة الثقافة والقدرة على الأكل والمرض.","bigEn":"Therapeutic Dietetics asks how food or the route of nutrition should be modified to fit a patient's condition. Modification may involve texture, nutrient composition or route, while respecting culture and the ability to eat safely.","chunksAr":[{"kind":"overview","title":"التغذية العلاجية","text":"التغذية العلاجية تبدأ من سؤال: كيف نعدّل الغذاء أو طريقة تقديمه ليتناسب مع حالة المريض؟ قد يكون التعديل في القوام أو المكونات أو طريق التغذية، مع مراعاة الثقافة والقدرة على الأكل والمرض."},{"kind":"concept","title":"Consistency","text":"قد يحتاج المريض clear liquid أو full liquid أو soft أو pureed حسب قدرته وحالته."},{"kind":"concept","title":"Composition","text":"قد تُعدل الدهون أو الكربوهيدرات أو الألياف أو الصوديوم وغيرها حسب الهدف العلاجي."},{"kind":"concept","title":"Enteral feeding","text":"إذا كان الجهاز الهضمي يعمل لكن الأكل بالفم غير كافٍ، قد تستخدم تغذية عبر الأنبوب حسب الخطة."},{"kind":"concept","title":"Parenteral nutrition","text":"تغذية وريدية في حالات محددة تحتاج مراقبة دقيقة للمضاعفات."},{"kind":"concept","title":"Culture & religion","text":"الخطة التي تتجاهل معتقدات المريض وعاداته قد لا تكون قابلة للتطبيق."},{"kind":"concept","title":"Health teaching","text":"الممرض يساعد المريض على فهم «لماذا» وكيف يطبق الخطة في المنزل."},{"kind":"lesson","title":"عدل القوام لا القيمة فقط","text":"المريض المصاب بصعوبة بلع قد يحتاج غذاءً أكثر أمانًا في القوام."},{"kind":"lesson","title":"اربط الحمية بالهدف","text":"DASH أو diabetic diet ليست أسماء؛ لكل نمط هدف ومبدأ."},{"kind":"lesson","title":"Enteral vs parenteral","text":"اعرف الفرق العام ومتى يكون الجهاز الهضمي جزءًا من الخطة."},{"kind":"lesson","title":"راقب المضاعفات","text":"تحمل التغذية، العدوى، الاختلالات الاستقلابية والسوائل أمور مهمة حسب الطريق."},{"kind":"lesson","title":"لا تنس المريض","text":"الذوق والثقافة والقدرة المالية تؤثر في الالتزام."},{"kind":"lesson","title":"التعليم الواقعي","text":"استبدل «لا تأكل كذا» بخيارات وبدائل وكمية وتوقيت يمكن تطبيقها."},{"kind":"scenario","title":"مريض لديه صعوبة بلع","text":"تفهم أن اختيار القوام قد يكون مسألة سلامة وليس مجرد تفضيل."},{"kind":"scenario","title":"تغذية عبر أنبوب","text":"تدرك أن الطريق مختلف لكن هدف التغذية والمتابعة ومنع المضاعفات مستمر."},{"kind":"scenario","title":"مريض يقول إن الحمية لا تناسب طعام أسرته","text":"تحاول فهم العادات وإيجاد بدائل مناسبة بدل إعطائه قائمة منفصلة عن حياته."}],"chunksEn":[{"kind":"overview","title":"Therapeutic Dietetics","text":"Therapeutic Dietetics asks how food or the route of nutrition should be modified to fit a patient's condition. Modification may involve texture, nutrient composition or route, while respecting culture and the ability to eat safely."},{"kind":"concept","title":"Consistency","text":"Clear liquid, full liquid, soft and pureed diets differ in texture and purpose."},{"kind":"concept","title":"Composition","text":"Fat, carbohydrate, fibre, sodium and other components may be modified."},{"kind":"concept","title":"Enteral feeding","text":"Uses the gastrointestinal tract when oral intake is inadequate but the gut can be used."},{"kind":"concept","title":"Parenteral nutrition","text":"Intravenous nutrition for selected situations with close monitoring."},{"kind":"concept","title":"Culture & religion","text":"Diet plans must consider meaningful dietary practices."},{"kind":"concept","title":"Health teaching","text":"Help the patient understand why and how to follow the plan at home."},{"kind":"lesson","title":"Texture is a safety issue","text":"Dysphagia may require safer food consistency."},{"kind":"lesson","title":"Link a diet to its goal","text":"A named diet has a purpose, not just a list of allowed foods."},{"kind":"lesson","title":"Enteral vs parenteral","text":"Know the broad distinction and why one route may be chosen."},{"kind":"lesson","title":"Monitor complications","text":"Tolerance, infection, metabolism and fluid status can matter."},{"kind":"lesson","title":"Respect the patient","text":"Preferences, culture and affordability influence adherence."},{"kind":"lesson","title":"Teach realistically","text":"Offer workable options, not only prohibitions."},{"kind":"scenario","title":"A patient has difficulty swallowing","text":"Food consistency can be a safety issue, not merely preference."},{"kind":"scenario","title":"Tube feeding","text":"The route changes, but nutrition goals and monitoring continue."},{"kind":"scenario","title":"A diet does not fit family foods","text":"Explore culturally appropriate alternatives instead of giving an unrealistic list."}],"sources":[]},{"id":"growth","year":2,"sem":2,"code":"NURS 203ly","nAr":"النمو والتطور","nEn":"Growth and Development","typeAr":"تخصصي","typeEn":"Specialty","bigAr":"النمو يعني التغير الكمي في الجسم، والتطور يعني اكتساب قدرات ووظائف ومهارات عبر العمر. لا تقارن الطفل أو البالغ بمرحلة أخرى؛ اسأل دائمًا: ما المتوقع في هذه المرحلة؟ وما مدى الاختلاف الطبيعي؟","bigEn":"Growth refers to quantitative body change; development refers to acquisition of abilities and functions across life. Always ask what is expected at this stage and how broad normal variation can be.","chunksAr":[{"kind":"overview","title":"النمو والتطور","text":"النمو يعني التغير الكمي في الجسم، والتطور يعني اكتساب قدرات ووظائف ومهارات عبر العمر. لا تقارن الطفل أو البالغ بمرحلة أخرى؛ اسأل دائمًا: ما المتوقع في هذه المرحلة؟ وما مدى الاختلاف الطبيعي؟"},{"kind":"concept","title":"Growth vs development","text":"الطول والوزن أمثلة على النمو، بينما اللغة والحركة والتفكير والعلاقات أمثلة على التطور."},{"kind":"concept","title":"Milestones","text":"علامات تقريبية لما يكتسبه الطفل في مراحل معينة، وليست ساعة تعمل بنفس اليوم لكل طفل."},{"kind":"concept","title":"Domains","text":"النمو الجسدي والحركي واللغوي والمعرفي والاجتماعي مترابط."},{"kind":"concept","title":"Factors","text":"الجينات والتغذية والمرض والأسرة والثقافة والبيئة تؤثر في المسار."},{"kind":"concept","title":"Screening","text":"أداة الفحص تساعد على اكتشاف من يحتاج تقييمًا أعمق؛ لا تعطي تشخيصًا وحدها."},{"kind":"concept","title":"Lifespan","text":"التطور لا ينتهي في الطفولة؛ البلوغ والشيخوخة أيضًا مراحل لها تغيراتها."},{"kind":"lesson","title":"Infancy","text":"نمو سريع، ارتباط، حركة أولية، حس وإدراك وتواصل مبكر."},{"kind":"lesson","title":"Toddler","text":"استقلال متزايد، حركة ولغة واستكشاف وحدود."},{"kind":"lesson","title":"Preschool","text":"تطور اللغة واللعب والخيال والمهارات الحركية."},{"kind":"lesson","title":"School age","text":"التعلم والمهارات الاجتماعية والاستقلال والكفاءة."},{"kind":"lesson","title":"Adolescence","text":"تغير جسدي وهوية وعلاقات وتفكير أكثر تعقيدًا."},{"kind":"lesson","title":"Adulthood & aging","text":"أدوار وعلاقات وصحة وتكيف وتغيرات فسيولوجية ونفسية عبر العمر."},{"kind":"scenario","title":"والدة تقارن طفلها بطفل آخر","text":"تشرح أن المراحل لها نطاقات وأن المهم هو النمط العام، مع الإحالة للتقييم عند وجود قلق."},{"kind":"scenario","title":"طفل لا يتعاون في الفحص","text":"طريقة التواصل يجب أن تناسب عمره وقدرته على الفهم."},{"kind":"scenario","title":"كبير سن أبطأ في الحركة","text":"تفرق بين تغيرات العمر المتوقعة وبين تغير مفاجئ أو غير معتاد يحتاج تقييمًا."}],"chunksEn":[{"kind":"overview","title":"Growth and Development","text":"Growth refers to quantitative body change; development refers to acquisition of abilities and functions across life. Always ask what is expected at this stage and how broad normal variation can be."},{"kind":"concept","title":"Growth vs development","text":"Height/weight differ from language, movement, cognition and social development."},{"kind":"concept","title":"Milestones","text":"Approximate markers, not identical deadlines for every child."},{"kind":"concept","title":"Domains","text":"Physical, motor, language, cognitive and social domains interact."},{"kind":"concept","title":"Factors","text":"Genes, nutrition, illness, family, culture and environment matter."},{"kind":"concept","title":"Screening","text":"Screening identifies who may need deeper assessment; it does not diagnose by itself."},{"kind":"concept","title":"Lifespan","text":"Development continues through adulthood and ageing."},{"kind":"lesson","title":"Infancy","text":"Rapid growth, attachment, early movement and communication."},{"kind":"lesson","title":"Toddler","text":"Increasing autonomy, movement, language and exploration."},{"kind":"lesson","title":"Preschool","text":"Language, play, imagination and motor development."},{"kind":"lesson","title":"School age","text":"Learning, social skills and competence."},{"kind":"lesson","title":"Adolescence","text":"Physical change, identity and more complex thinking."},{"kind":"lesson","title":"Adulthood & ageing","text":"Roles, health, adaptation and physiological/psychological change."},{"kind":"scenario","title":"A parent compares two children","text":"Explain that milestones occur in ranges and patterns matter."},{"kind":"scenario","title":"A child resists examination","text":"Communication should fit developmental level."},{"kind":"scenario","title":"An older adult moves more slowly","text":"Distinguish expected age-related change from sudden or unusual change."}],"sources":["openrn-healthpromo"]},{"id":"rle4","year":2,"sem":2,"code":"NURS 204ly","nAr":"الخبرة التعليمية المرتبطة 4","nEn":"Related Learning Experience 4","typeAr":"عملي تمريضي","typeEn":"Practical nursing","bigAr":"هذا المقرر يجعل سلامة إعطاء الدواء مهارة عملية: التحقق، الحساب، الطريق، المريض، التوثيق، التقييم قبل وبعد الإعطاء، ومراقبة الاستجابة.","bigEn":"RLE 4 makes medication safety practical: verification, calculation, route, patient identification, documentation, pre/post assessment and monitoring for response.","chunksAr":[{"kind":"overview","title":"الخبرة التعليمية المرتبطة 4","text":"هذا المقرر يجعل سلامة إعطاء الدواء مهارة عملية: التحقق، الحساب، الطريق، المريض، التوثيق، التقييم قبل وبعد الإعطاء، ومراقبة الاستجابة."},{"kind":"concept","title":"Medication rights","text":"حقوق إعطاء الدواء ليست قائمة للحفظ؛ هي حواجز أمان متكررة قبل الخطأ."},{"kind":"concept","title":"Medication card","text":"تلخيص الاسم والجرعة والطريق والتأثير والاحتياطات يساعد على الاستعداد المنظم."},{"kind":"concept","title":"Routes","text":"الفموي والعيني والأذني والأنفي والاستنشاقي والحقني لكل منها تقنية واعتبارات مختلفة."},{"kind":"concept","title":"Calculations","text":"الجرعة الصحيحة تحتاج وحدات صحيحة وحسابًا ومراجعة."},{"kind":"concept","title":"Pediatric assessment","text":"الطفل ليس بالغًا صغيرًا؛ القياسات والاستجابة والتواصل تتغير مع العمر."},{"kind":"concept","title":"Observe after administration","text":"انتهاء إعطاء الدواء لا يعني انتهاء المهمة؛ تابع التأثير والاستجابة والآثار غير المتوقعة."},{"kind":"lesson","title":"Oral medications","text":"الأقراص والسوائل والمعلق وتحت اللسان والشدق."},{"kind":"lesson","title":"Eye/Ear/Nasal","text":"الطريق الموضعي يحتاج تحديد العضو والدواء وتقنية تمنع التلوث."},{"kind":"lesson","title":"Nebulizer & inhalants","text":"فهم التنفس والجهاز والدواء والتعاون مع المريض."},{"kind":"lesson","title":"ID/SC/IM","text":"الحقن تختلف في الطبقة والموقع والحجم والأدوات حسب الدواء والمريض."},{"kind":"lesson","title":"IV & bolus","text":"طريق سريع التأثير يحتاج تحققًا ومراقبة وسياسات واضحة."},{"kind":"lesson","title":"Suppositories","text":"يحافظ الممرض على الخصوصية والوضعية الصحيحة والتقنية."},{"kind":"scenario","title":"جرعة محسوبة تبدو كبيرة","text":"لا تتجاوز الشك؛ أعد الحساب والوحدات واطلب التحقق حسب السياسة."},{"kind":"scenario","title":"اسم المريض مشابه لمريض آخر","text":"تستخدم معرفات المريض ولا تعتمد على الغرفة أو الذاكرة."},{"kind":"scenario","title":"المريض يقول إنه حساس لدواء","text":"تتوقف عن الافتراض وتتحقق من السجل وتبلغ قبل الإعطاء."},{"kind":"scenario","title":"بعد دواء جديد ظهر عرض غير متوقع","text":"تربط التوقيت بالدواء وتقيّم وتبلغ حسب البروتوكول."}],"chunksEn":[{"kind":"overview","title":"Related Learning Experience 4","text":"RLE 4 makes medication safety practical: verification, calculation, route, patient identification, documentation, pre/post assessment and monitoring for response."},{"kind":"concept","title":"Medication rights","text":"Safety checks are barriers against error."},{"kind":"concept","title":"Medication card","text":"Organises drug, dose, route, purpose, cautions and observations."},{"kind":"concept","title":"Routes","text":"Oral, eye, ear, nasal, inhaled and parenteral routes differ."},{"kind":"concept","title":"Calculations","text":"Correct dose requires correct units and checking."},{"kind":"concept","title":"Pediatric assessment","text":"Children require age-appropriate measurement and communication."},{"kind":"concept","title":"Observe after administration","text":"The nursing task continues after the medicine is given."},{"kind":"lesson","title":"Oral medicines","text":"Tablets, liquids, suspensions, sublingual and buccal routes."},{"kind":"lesson","title":"Eye/Ear/Nasal","text":"Local routes require correct site and contamination prevention."},{"kind":"lesson","title":"Nebuliser & inhalants","text":"Connect respiratory assessment, device technique and medicine."},{"kind":"lesson","title":"ID/SC/IM","text":"Injection routes differ by tissue layer and clinical purpose."},{"kind":"lesson","title":"IV & bolus","text":"Rapid-effect routes require precise verification and monitoring."},{"kind":"lesson","title":"Suppositories","text":"Privacy, positioning and safe technique matter."},{"kind":"scenario","title":"A calculated dose looks unusually large","text":"Recheck units and calculation and seek independent verification according to policy."},{"kind":"scenario","title":"Two patients have similar names","text":"Use approved patient identifiers rather than room or memory."},{"kind":"scenario","title":"A patient reports a drug allergy","text":"Verify and report before administration."},{"kind":"scenario","title":"A new symptom appears after a medicine","text":"Assess timing and findings and report according to policy."}],"sources":["openrn-fund","openrn-skills","who-safety"]},{"id":"community","year":2,"sem":2,"code":"NURS 205ly","nAr":"تمريض صحة المجتمع","nEn":"Community Health Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"في المستشفى يكون المريض أمامك فردًا؛ في صحة المجتمع قد يكون «المريض» فردًا أو أسرة أو مدرسة أو حيًا أو فئة معرضة للخطر. الهدف ينتقل من علاج المشكلة فقط إلى الوقاية وتعزيز الصحة وتحسين الظروف التي تصنع المرض.","bigEn":"In community nursing, the client may be an individual, family, school, neighbourhood or at-risk group. The focus expands from treating illness to prevention, health promotion and changing conditions that shape health.","chunksAr":[{"kind":"overview","title":"تمريض صحة المجتمع","text":"في المستشفى يكون المريض أمامك فردًا؛ في صحة المجتمع قد يكون «المريض» فردًا أو أسرة أو مدرسة أو حيًا أو فئة معرضة للخطر. الهدف ينتقل من علاج المشكلة فقط إلى الوقاية وتعزيز الصحة وتحسين الظروف التي تصنع المرض."},{"kind":"concept","title":"Population focus","text":"انظر إلى النمط في مجموعة، لا حالة واحدة فقط."},{"kind":"concept","title":"Primary Health Care","text":"قرب الخدمة، الوقاية، المشاركة والعدالة مبادئ مهمة في الرعاية الأولية."},{"kind":"concept","title":"Needs assessment","text":"قبل تصميم نشاط، اعرف ما المشكلة ومن يتأثر وما الموارد وما الأولوية."},{"kind":"concept","title":"Levels of prevention","text":"أولي قبل المرض، ثانوي للكشف المبكر، وثالثي لتقليل المضاعفات."},{"kind":"concept","title":"Communicable disease","text":"العدوى تحتاج فهم الانتقال والوقاية والمتابعة المجتمعية."},{"kind":"concept","title":"Non-communicable disease","text":"السكري والضغط والسرطان وCOPD تتطلب وقاية وسلوكًا ومتابعة طويلة."},{"kind":"lesson","title":"الفرد والأسرة والمجتمع","text":"كل مستوى له بيانات واحتياجات وتدخلات مختلفة."},{"kind":"lesson","title":"Community assessment","text":"اجمع معلومات سكانية وبيئية وصحية وخدمية قبل اتخاذ القرار."},{"kind":"lesson","title":"Health promotion","text":"لا تكتفِ بالمحاضرة؛ فكر في السلوك والبيئة والدعم والمتابعة."},{"kind":"lesson","title":"Vulnerable groups","text":"بعض الفئات تواجه مخاطر أو حواجز أكبر وتحتاج تدخلًا مناسبًا."},{"kind":"lesson","title":"Disease prevention","text":"اربط العدوى وغير المعدية بعوامل الخطر والوقاية والكشف المبكر."},{"kind":"lesson","title":"Documentation","text":"التسجيل المجتمعي يساعد على اكتشاف الأنماط ومتابعة أثر البرامج."},{"kind":"scenario","title":"زيارة مدرسة","text":"قبل إعطاء محاضرة، اسأل ما المشكلة الصحية الفعلية وما عمر الطلاب وما الذي يمكن قياس أثره."},{"kind":"scenario","title":"حي ترتفع فيه حالات الضغط","text":"لا تفكر فقط في علاج فرد؛ فكر في الكشف والتوعية والنمط الغذائي والوصول للخدمة."},{"kind":"scenario","title":"أسرة لديها طفل مريض متكررًا","text":"قد تحتاج النظر إلى السكن والازدحام والتطعيم والتغذية والوصول للرعاية."},{"kind":"scenario","title":"حملة توعية لم تغير السلوك","text":"تتعلم أن المعرفة وحدها لا تضمن التغيير؛ يجب فهم الحواجز والدوافع والمتابعة."}],"chunksEn":[{"kind":"overview","title":"Community Health Nursing","text":"In community nursing, the client may be an individual, family, school, neighbourhood or at-risk group. The focus expands from treating illness to prevention, health promotion and changing conditions that shape health."},{"kind":"concept","title":"Population focus","text":"Look for patterns across groups, not only one case."},{"kind":"concept","title":"Primary Health Care","text":"Accessibility, prevention, participation and equity matter."},{"kind":"concept","title":"Needs assessment","text":"Identify the real problem, affected groups and resources before designing an activity."},{"kind":"concept","title":"Levels of prevention","text":"Primary, secondary and tertiary prevention have different goals."},{"kind":"concept","title":"Communicable disease","text":"Understand transmission, prevention and community follow-up."},{"kind":"concept","title":"Non-communicable disease","text":"Long-term risks and behaviours require prevention and continuity."},{"kind":"lesson","title":"Individual-family-community","text":"Each level needs different data and interventions."},{"kind":"lesson","title":"Community assessment","text":"Collect demographic, environmental, health and service information."},{"kind":"lesson","title":"Health promotion","text":"Information alone may not change behaviour."},{"kind":"lesson","title":"Vulnerable groups","text":"Some groups face greater risks or barriers."},{"kind":"lesson","title":"Disease prevention","text":"Connect risk factors with prevention and early detection."},{"kind":"lesson","title":"Documentation","text":"Community records help identify patterns and evaluate programmes."},{"kind":"scenario","title":"A school health visit","text":"Assess the actual need and age group before giving a generic lecture."},{"kind":"scenario","title":"High blood pressure is common in an area","text":"Think about screening, diet, behaviour and access to care at population level."},{"kind":"scenario","title":"A child is repeatedly ill","text":"Consider housing, crowding, immunisation, nutrition and access to care."},{"kind":"scenario","title":"Awareness improved but behaviour did not","text":"Explore barriers, motivation and follow-up rather than assuming education failed."}],"sources":["openrn-mental","who-safety"]},{"id":"ethics","year":2,"sem":2,"code":"NURS 206ly","nAr":"أخلاقيات وتشريعات التمريض","nEn":"Nursing Ethics and Jurisprudence","typeAr":"تخصصي","typeEn":"Specialty","bigAr":"هذا المقرر يساعدك على اتخاذ قرار مهني عندما لا تكون المسألة «تقنية» فقط. الرعاية الآمنة تحتاج احترام الشخص وحقوقه، موازنة الفائدة والضرر، العدالة، الصدق، السرية والمسؤولية القانونية.","bigEn":"This course supports professional decisions when a situation is not only technical. Safe care requires respect for the person and rights, balancing benefit and harm, justice, truthfulness, confidentiality and legal responsibility.","chunksAr":[{"kind":"overview","title":"أخلاقيات وتشريعات التمريض","text":"هذا المقرر يساعدك على اتخاذ قرار مهني عندما لا تكون المسألة «تقنية» فقط. الرعاية الآمنة تحتاج احترام الشخص وحقوقه، موازنة الفائدة والضرر، العدالة، الصدق، السرية والمسؤولية القانونية."},{"kind":"concept","title":"Autonomy","text":"للمريض حق المشاركة في القرارات المتعلقة بجسده ورعايته ضمن الأطر المعمول بها."},{"kind":"concept","title":"Beneficence","text":"اعمل لما يحقق مصلحة المريض."},{"kind":"concept","title":"Non-maleficence","text":"تجنب الضرر الذي يمكن منعه."},{"kind":"concept","title":"Justice","text":"عامل الناس بعدل ووزع الموارد والفرص بصورة منصفة."},{"kind":"concept","title":"Fidelity & veracity","text":"الوفاء بالمسؤولية والصدق يبنيان الثقة المهنية."},{"kind":"concept","title":"Informed consent","text":"الموافقة ليست توقيعًا فقط؛ ترتبط بالمعلومة والقدرة والاختيار."},{"kind":"lesson","title":"حقوق المريض","text":"الخصوصية والاحترام والمعلومة والمشاركة أسس مهمة."},{"kind":"lesson","title":"القيم المهنية","text":"النزاهة والرحمة والاحترام والشجاعة المهنية تظهر في السلوك اليومي."},{"kind":"lesson","title":"Ethical dilemma","text":"قد تتعارض قيم أو مصالح؛ استخدم تفكيرًا منظمًا بدل رد فعل شخصي."},{"kind":"lesson","title":"Legal responsibility","text":"اعرف حدود دورك، وثق بدقة، واتبع السياسات ولا تعمل خارج صلاحياتك."},{"kind":"lesson","title":"Negligence & malpractice","text":"الإهمال المهني قد يسبب ضررًا وله تبعات؛ الوقاية تبدأ بالممارسة الآمنة."},{"kind":"lesson","title":"Consent & capacity","text":"عند الشك في القدرة أو الموافقة، لا تفترض؛ ارجع للإجراء والجهة المختصة."},{"kind":"scenario","title":"مريض يرفض إجراءً","text":"لا تحول الرفض إلى صراع؛ تأكد من الفهم، أبلغ، واحترم الإجراء النظامي."},{"kind":"scenario","title":"أحد الأقارب يطلب معلومات خاصة","text":"كونه قريبًا لا يعني تلقائيًا حقه في كل المعلومات؛ الخصوصية مهمة."},{"kind":"scenario","title":"خطأ دوائي كاد يحدث","text":"الإخفاء يزيد الخطر؛ السلامة تتطلب الإبلاغ وفق النظام والتعلم من السبب."},{"kind":"scenario","title":"طلب منك تنفيذ شيء خارج تدريبك","text":"المهنية تشمل معرفة حدودك وطلب الإشراف بدل المجازفة."}],"chunksEn":[{"kind":"overview","title":"Nursing Ethics and Jurisprudence","text":"This course supports professional decisions when a situation is not only technical. Safe care requires respect for the person and rights, balancing benefit and harm, justice, truthfulness, confidentiality and legal responsibility."},{"kind":"concept","title":"Autonomy","text":"Patients participate in decisions about their bodies and care within applicable frameworks."},{"kind":"concept","title":"Beneficence","text":"Act to support the patient's good."},{"kind":"concept","title":"Non-maleficence","text":"Avoid preventable harm."},{"kind":"concept","title":"Justice","text":"Treat people fairly."},{"kind":"concept","title":"Fidelity & veracity","text":"Keeping professional commitments and telling the truth support trust."},{"kind":"concept","title":"Informed consent","text":"Consent is more than a signature; information, capacity and choice matter."},{"kind":"lesson","title":"Patient rights","text":"Privacy, respect, information and participation matter."},{"kind":"lesson","title":"Professional virtues","text":"Integrity, compassion, honesty and courage appear in daily practice."},{"kind":"lesson","title":"Ethical dilemmas","text":"Competing values require structured reasoning."},{"kind":"lesson","title":"Legal responsibility","text":"Know your role, document accurately and follow policy."},{"kind":"lesson","title":"Negligence & malpractice","text":"Unsafe omission/action can cause harm and legal consequences."},{"kind":"lesson","title":"Consent & capacity","text":"Do not assume; use the appropriate process when capacity or consent is unclear."},{"kind":"scenario","title":"A patient refuses a procedure","text":"Check understanding, report appropriately and respect the formal process."},{"kind":"scenario","title":"A relative asks for private information","text":"Being family does not automatically mean unrestricted access to patient information."},{"kind":"scenario","title":"A near medication error occurs","text":"Safety requires appropriate reporting and learning from the cause."},{"kind":"scenario","title":"You are asked to do something beyond your training","text":"Professionalism includes recognising limits and seeking supervision."}],"sources":["openrn-management","who-safety"]},{"id":"medterm1","year":3,"sem":1,"code":"LANG 301ly","nAr":"المصطلحات الطبية 1","nEn":"Medical Terminology 1","typeAr":"عام","typeEn":"General","bigAr":"المصطلح الطبي ليس كلمة غريبة يجب حفظها كاملة؛ غالبًا يمكن تفكيكه إلى جذر وprefix وsuffix. عندما تفهم الأجزاء تبدأ في تفسير كلمات لم ترها من قبل بدل حفظ آلاف الكلمات منفصلة.","bigEn":"Medical terms become easier when broken into roots, prefixes and suffixes. Understanding word structure lets you interpret unfamiliar terms instead of memorising thousands of isolated words.","chunksAr":[{"kind":"overview","title":"المصطلحات الطبية 1","text":"المصطلح الطبي ليس كلمة غريبة يجب حفظها كاملة؛ غالبًا يمكن تفكيكه إلى جذر وprefix وsuffix. عندما تفهم الأجزاء تبدأ في تفسير كلمات لم ترها من قبل بدل حفظ آلاف الكلمات منفصلة."},{"kind":"concept","title":"Root","text":"يحمل الفكرة الأساسية مثل cardi- للقلب أو neur- للعصب."},{"kind":"concept","title":"Prefix","text":"يأتي قبل الجذر ويعدل المعنى مثل hypo- أو hyper-."},{"kind":"concept","title":"Suffix","text":"يأتي في النهاية وقد يشير لالتهاب أو فحص أو إجراء."},{"kind":"concept","title":"Combining form","text":"يساعد على وصل أجزاء المصطلح."},{"kind":"concept","title":"Abbreviations","text":"الاختصارات شائعة لكن يجب استخدامها بحذر لأنها قد تُفهم بطرق مختلفة."},{"kind":"concept","title":"Body-system vocabulary","text":"المفردات تصبح أسهل عندما تُنظم حسب أجهزة الجسم."},{"kind":"lesson","title":"ابنِ الكلمة","text":"حلل المصطلح ثم أعد تركيبه."},{"kind":"lesson","title":"لا تخمن من التشابه","text":"بعض الكلمات متشابهة لكنها مختلفة المعنى؛ ارجع إلى مصدر موثوق."},{"kind":"lesson","title":"قل المصطلح بصوت","text":"النطق جزء من التواصل السريري."},{"kind":"lesson","title":"اربطه بالتشريح","text":"مصطلح بلا صورة للجسم يصعب تثبيته."},{"kind":"lesson","title":"تعلم التشخيص والإجراء","text":"ميز بين كلمة تصف مرضًا وكلمة تصف فحصًا أو عملية."},{"kind":"lesson","title":"استخدمه في جملة","text":"لا تحفظ cardiomegaly وحدها؛ استخدمها في سياق تقرير أو شرح."},{"kind":"scenario","title":"رأيت كلمة لأول مرة في تقرير","text":"تفككها إلى أجزاء قبل فتح القاموس، ثم تتحقق من المعنى."},{"kind":"scenario","title":"اختصار غير واضح في ورقة","text":"لا تفترض؛ اسأل أو ارجع للمرجع المعتمد لأن الخطأ في الاختصار قد يغير المعنى."}],"chunksEn":[{"kind":"overview","title":"Medical Terminology 1","text":"Medical terms become easier when broken into roots, prefixes and suffixes. Understanding word structure lets you interpret unfamiliar terms instead of memorising thousands of isolated words."},{"kind":"concept","title":"Root","text":"Carries the central meaning, e.g. cardi- or neur-."},{"kind":"concept","title":"Prefix","text":"Modifies meaning at the beginning, e.g. hypo-, hyper-."},{"kind":"concept","title":"Suffix","text":"Often identifies a condition, procedure or process."},{"kind":"concept","title":"Combining form","text":"Connects word elements."},{"kind":"concept","title":"Abbreviations","text":"Common but potentially ambiguous; use carefully."},{"kind":"concept","title":"Body-system vocabulary","text":"Organising terms by body system supports memory."},{"kind":"lesson","title":"Build the word","text":"Break down a term and reconstruct it."},{"kind":"lesson","title":"Do not guess","text":"Similar-looking terms can mean different things."},{"kind":"lesson","title":"Say it aloud","text":"Pronunciation supports safe communication."},{"kind":"lesson","title":"Link to anatomy","text":"A term is easier when you know the structure it refers to."},{"kind":"lesson","title":"Condition vs procedure","text":"Distinguish disease terms from test/procedure terms."},{"kind":"lesson","title":"Use it in context","text":"Place terms in a report or clinical sentence."},{"kind":"scenario","title":"An unfamiliar term appears in a report","text":"Break it into elements, then verify the full meaning."},{"kind":"scenario","title":"An abbreviation is unclear","text":"Do not assume—clarify or use an approved reference."}],"sources":["openrn-medterm"]},{"id":"adult1","year":3,"sem":1,"code":"NURS 301ly","nAr":"تمريض البالغين 1","nEn":"Adult Nursing 1","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"هنا تبدأ بجمع أجزاء كثيرة سبق أن درستها: التشريح، الفسيولوجيا المرضية، التقييم، الأدوية والسوائل. التركيز على أمراض القلب والرئتين والكلى واختلال السوائل والشوارد، باستخدام عملية التمريض من التقييم حتى تقييم النتائج.","bigEn":"Adult Nursing 1 integrates anatomy, pathophysiology, assessment, medicines and fluids in care of cardiovascular, pulmonary and renal problems and fluid/electrolyte imbalance.","chunksAr":[{"kind":"overview","title":"تمريض البالغين 1","text":"هنا تبدأ بجمع أجزاء كثيرة سبق أن درستها: التشريح، الفسيولوجيا المرضية، التقييم، الأدوية والسوائل. التركيز على أمراض القلب والرئتين والكلى واختلال السوائل والشوارد، باستخدام عملية التمريض من التقييم حتى تقييم النتائج."},{"kind":"concept","title":"Oxygenation","text":"القلب والرئتان والدورة تعمل معًا لإيصال الأكسجين للأنسجة."},{"kind":"concept","title":"Perfusion","text":"الضغط والنبض والقوة القلبية وحالة الأوعية تؤثر في وصول الدم للأعضاء."},{"kind":"concept","title":"Fluid balance","text":"الوارد والمفقود ووظيفة الكلى والهرمونات تؤثر في حجم السوائل وتركيزها."},{"kind":"concept","title":"Acid-base","text":"الرئة والكلى والـbuffers تتعاون للمحافظة على pH."},{"kind":"concept","title":"Clinical assessment","text":"الأعراض والعلامات والفحص والنتائج المخبرية تُجمع لتكوين صورة واحدة."},{"kind":"concept","title":"Nursing process","text":"التقييم والتشخيص التمريضي والتخطيط والتنفيذ والتقييم هي طريقة تنظيم الرعاية."},{"kind":"lesson","title":"القلب","text":"Atherosclerosis، angina، myocardial infarction وheart failure تُفهم عبر التروية والطلب على الأكسجين وقدرة القلب على الضخ."},{"kind":"lesson","title":"الرئتان","text":"COPD والعدوى ومشكلات التنفس تربط بين مجرى الهواء والتهوية وتبادل الغازات."},{"kind":"lesson","title":"الكلى","text":"UTI، glomerulonephritis، nephrotic syndrome، renal failure والحصوات تؤثر في الإطراح والسوائل والشوارد."},{"kind":"lesson","title":"Dialysis","text":"فهم الهدف من hemodialysis وperitoneal dialysis أهم من حفظ الإجراءات وحدها."},{"kind":"lesson","title":"ABG","text":"الغازات الشريانية تربط التنفس بالأكسجة والحموضة والتهوية."},{"kind":"lesson","title":"التثقيف","text":"الغذاء، السوائل، الأدوية، النشاط ومتى يطلب المريض المساعدة جزء من الرعاية."},{"kind":"scenario","title":"مريض بضيق نفس وتورم كاحلين","text":"تجمع النبض والضغط والتنفس والأكسجة والسوائل بدل النظر لكل علامة منفصلة."},{"kind":"scenario","title":"ألم صدري جديد","text":"تتعامل معه كعرض يحتاج تقييمًا سريعًا ولا تفترض أنه مجرد عسر هضم."},{"kind":"scenario","title":"انخفاض البول","text":"تفكر في التروية والسوائل ووظيفة الكلى والأدوية وتبلغ حسب الحالة."},{"kind":"scenario","title":"بوتاسيوم غير طبيعي","text":"تعرف أن تغير الشوارد قد يؤثر في العضلات والقلب ويحتاج متابعة دقيقة."}],"chunksEn":[{"kind":"overview","title":"Adult Nursing 1","text":"Adult Nursing 1 integrates anatomy, pathophysiology, assessment, medicines and fluids in care of cardiovascular, pulmonary and renal problems and fluid/electrolyte imbalance."},{"kind":"concept","title":"Oxygenation","text":"Heart, lungs and circulation work together to deliver oxygen."},{"kind":"concept","title":"Perfusion","text":"Blood pressure, cardiac output and vascular tone affect tissue blood flow."},{"kind":"concept","title":"Fluid balance","text":"Intake, output, kidney function and hormones affect volume and concentration."},{"kind":"concept","title":"Acid-base","text":"Lungs, kidneys and buffers help maintain pH."},{"kind":"concept","title":"Clinical assessment","text":"Symptoms, examination and tests form one clinical picture."},{"kind":"concept","title":"Nursing process","text":"Assessment, diagnosis, planning, implementation and evaluation organise care."},{"kind":"lesson","title":"Cardiovascular care","text":"Understand atherosclerosis, angina, myocardial infarction and heart failure through perfusion and oxygen demand."},{"kind":"lesson","title":"Pulmonary care","text":"Connect COPD and respiratory infection with ventilation and gas exchange."},{"kind":"lesson","title":"Renal care","text":"Link UTI, glomerular disease and renal failure with elimination, fluids and electrolytes."},{"kind":"lesson","title":"Dialysis","text":"Understand the purpose and broad differences between hemodialysis and peritoneal dialysis."},{"kind":"lesson","title":"ABG","text":"Connect arterial gases with oxygenation, ventilation and acid-base balance."},{"kind":"lesson","title":"Teaching","text":"Diet, fluids, medicines, activity and warning signs are part of care."},{"kind":"scenario","title":"Breathlessness with ankle swelling","text":"Assess oxygenation, circulation and fluid status together."},{"kind":"scenario","title":"New chest pain","text":"Treat it as an important symptom requiring prompt assessment rather than assuming indigestion."},{"kind":"scenario","title":"Reduced urine output","text":"Consider perfusion, fluid status, renal function and medicines."},{"kind":"scenario","title":"Abnormal potassium","text":"Recognise that electrolyte disturbance may affect muscle and cardiac function."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"peds","year":3,"sem":1,"code":"NURS 302ly","nAr":"تمريض الأطفال","nEn":"Pediatric Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"الطفل ليس بالغًا صغيرًا. العمر والنمو والوزن والقدرة على التواصل واحتياطي الجسم كلها تغير التقييم والرعاية والجرعات والمخاطر. هذا المقرر يطبق التمريض على أمراض الأطفال عبر أجهزة الجسم المختلفة.","bigEn":"A child is not simply a small adult. Age, development, weight, communication ability and physiological reserve change assessment, care, medication dosing and risk.","chunksAr":[{"kind":"overview","title":"تمريض الأطفال","text":"الطفل ليس بالغًا صغيرًا. العمر والنمو والوزن والقدرة على التواصل واحتياطي الجسم كلها تغير التقييم والرعاية والجرعات والمخاطر. هذا المقرر يطبق التمريض على أمراض الأطفال عبر أجهزة الجسم المختلفة."},{"kind":"concept","title":"Age-specific assessment","text":"المعدل الطبيعي للنبض والتنفس والسلوك يختلف حسب العمر."},{"kind":"concept","title":"Family-centred care","text":"الأسرة جزء من الرعاية والمعلومة والدعم، مع احترام الطفل وخصوصيته."},{"kind":"concept","title":"Growth context","text":"أي عرض يجب أن يُفسر في سياق مرحلة النمو والتطور."},{"kind":"concept","title":"Fluid vulnerability","text":"الأطفال قد يتأثرون بفقد السوائل بسرعة أكبر."},{"kind":"concept","title":"Congenital vs acquired","text":"بعض المشكلات موجودة منذ الولادة وأخرى تحدث لاحقًا."},{"kind":"concept","title":"Weight-based care","text":"الوزن يدخل في الحسابات الدوائية والسوائل والتغذية."},{"kind":"lesson","title":"الجلد","text":"Impetigo، candidiasis، dermatitis، tinea، scabies وغيرها تحتاج تمييز النمط ومنع الانتقال والعناية بالجلد."},{"kind":"lesson","title":"التنفس","text":"URTI، bronchiolitis، asthma وpneumonia تظهر بصورة قد تختلف حسب العمر."},{"kind":"lesson","title":"القلب الخلقي","text":"PDA، ASD، VSD، Tetralogy of Fallot وغيرها تُفهم عبر اتجاه تدفق الدم والأكسجة."},{"kind":"lesson","title":"الجهاز الهضمي","text":"الإسهال، pyloric stenosis، intussusception وHirschsprung ترتبط بالتغذية والسوائل والنمو."},{"kind":"lesson","title":"الكلى والمسالك","text":"UTI، glomerulonephritis وnephrotic syndrome تحتاج متابعة البول والوذمة والضغط وغيرها."},{"kind":"lesson","title":"العصبي","text":"seizures، meningitis، hydrocephalus وغيرها تحتاج ملاحظة واعية للتغير العصبي."},{"kind":"scenario","title":"طفل يتنفس بسرعة ولا يستطيع الرضاعة جيدًا","text":"تعرف أن صعوبة الرضاعة قد تكون علامة مهمة على عبء التنفس عند الرضع."},{"kind":"scenario","title":"طفل بإسهال متكرر","text":"تراقب السوائل والبول والوزن والنشاط لأن الجفاف قد يتطور بسرعة."},{"kind":"scenario","title":"طفل مزرق أثناء البكاء","text":"تتعامل مع تغير اللون والأكسجة كعلامة مهمة ضمن التقييم القلبي التنفسي."},{"kind":"scenario","title":"جرعة دواء لطفل","text":"لا تنقل جرعة بالغ؛ تتحقق من الوزن والتركيز والوحدة وسياسة الدواء."}],"chunksEn":[{"kind":"overview","title":"Pediatric Nursing","text":"A child is not simply a small adult. Age, development, weight, communication ability and physiological reserve change assessment, care, medication dosing and risk."},{"kind":"concept","title":"Age-specific assessment","text":"Normal pulse, respiration and behaviour vary with age."},{"kind":"concept","title":"Family-centred care","text":"Family involvement supports information, comfort and continuity."},{"kind":"concept","title":"Growth context","text":"Interpret findings within developmental stage."},{"kind":"concept","title":"Fluid vulnerability","text":"Children can be affected quickly by fluid loss."},{"kind":"concept","title":"Congenital vs acquired","text":"Some disorders are present from birth; others develop later."},{"kind":"concept","title":"Weight-based care","text":"Weight influences medicine, fluid and nutrition calculations."},{"kind":"lesson","title":"Skin disorders","text":"Recognise common pediatric skin conditions and infection-control implications."},{"kind":"lesson","title":"Respiratory disorders","text":"Understand upper/lower respiratory problems, bronchiolitis, asthma and pneumonia."},{"kind":"lesson","title":"Congenital heart disease","text":"Use blood-flow and oxygenation concepts to understand defects."},{"kind":"lesson","title":"GI problems","text":"Connect vomiting/diarrhoea and congenital GI problems with hydration and growth."},{"kind":"lesson","title":"GU problems","text":"Monitor urine, edema and blood pressure in renal/urinary disorders."},{"kind":"lesson","title":"Neurologic problems","text":"Observe neurological change carefully in seizures, meningitis and other conditions."},{"kind":"scenario","title":"Fast breathing and poor feeding in an infant","text":"Poor feeding can be an important sign of respiratory workload."},{"kind":"scenario","title":"Repeated diarrhoea","text":"Monitor hydration, urine output, weight and activity."},{"kind":"scenario","title":"Cyanosis with crying","text":"Recognise colour/oxygenation change as an important assessment finding."},{"kind":"scenario","title":"Pediatric medication dose","text":"Verify weight, concentration and units rather than scaling an adult dose."}],"sources":["openrn-fund","openrn-skills","openrn-healthpromo"]},{"id":"informatics","year":3,"sem":1,"code":"NURS 303ly","nAr":"مقدمة الحاسوب ومعلوماتية التمريض","nEn":"Introduction to Computer with Nursing Informatics","typeAr":"عام","typeEn":"General","bigAr":"المعلوماتية التمريضية هي استخدام البيانات والمعلومات والتقنية لخدمة الرعاية والقرار والتوثيق والتعليم والبحث. الهدف ليس معرفة الحاسوب فقط، بل معرفة كيف تستخدمه بأمان ووعي داخل بيئة صحية.","bigEn":"Nursing informatics uses data, information and technology to support care, decisions, documentation, education and research. The goal is not just computer literacy, but safe and meaningful use of information.","chunksAr":[{"kind":"overview","title":"مقدمة الحاسوب ومعلوماتية التمريض","text":"المعلوماتية التمريضية هي استخدام البيانات والمعلومات والتقنية لخدمة الرعاية والقرار والتوثيق والتعليم والبحث. الهدف ليس معرفة الحاسوب فقط، بل معرفة كيف تستخدمه بأمان ووعي داخل بيئة صحية."},{"kind":"concept","title":"Data → information","text":"الرقم أو الملاحظة تصبح معلومة عندما تُنظم وتُفسر في سياق."},{"kind":"concept","title":"EHR","text":"السجل الصحي الإلكتروني يجمع معلومات يجب أن تكون دقيقة ومحدّثة وقابلة للتتبع."},{"kind":"concept","title":"Confidentiality","text":"سهولة الوصول الرقمي لا تعني أن كل شخص يحق له رؤية بيانات المريض."},{"kind":"concept","title":"Information literacy","text":"ليست كل نتيجة من الإنترنت مصدرًا موثوقًا."},{"kind":"concept","title":"Decision support","text":"التقنية يمكن أن تساعد القرار لكنها لا تلغي التفكير السريري."},{"kind":"concept","title":"Telehealth","text":"الرعاية عن بعد توسع الوصول لكنها تحتاج خصوصية وتحققًا وتواصلًا مناسبًا."},{"kind":"lesson","title":"أساسيات الحاسوب","text":"hardware، software، files، folders وword processing أدوات عمل أساسية."},{"kind":"lesson","title":"إدارة المعلومات","text":"تعلم الفرق بين البيانات والمعلومة والمعرفة."},{"kind":"lesson","title":"البحث الموثوق","text":"تحقق من الجهة والمؤلف والتاريخ والدليل قبل استخدام محتوى صحي."},{"kind":"lesson","title":"السجل الإلكتروني","text":"التوثيق يجب أن يكون موضوعيًا ودقيقًا وفي وقته."},{"kind":"lesson","title":"الأمان","text":"كلمة المرور والشاشة المفتوحة ونسخ البيانات أمور تمس خصوصية المريض."},{"kind":"lesson","title":"استخدامات المعلوماتية","text":"التعليم والبحث والإدارة وtelehealth والمعلومات السريرية."},{"kind":"scenario","title":"تركت شاشة ملف المريض مفتوحة","text":"تفهم أن الخصوصية الرقمية جزء من أخلاقيات الرعاية."},{"kind":"scenario","title":"وجدت معلومة طبية على موقع مجهول","text":"لا تستخدمها مباشرة؛ تفحص المصدر والدليل والتاريخ."},{"kind":"scenario","title":"نسخت ملاحظة قديمة في ملف المريض","text":"تدرك خطر نقل معلومة لم تعد صحيحة دون التحقق."}],"chunksEn":[{"kind":"overview","title":"Introduction to Computer with Nursing Informatics","text":"Nursing informatics uses data, information and technology to support care, decisions, documentation, education and research. The goal is not just computer literacy, but safe and meaningful use of information."},{"kind":"concept","title":"Data → information","text":"Raw observations become useful information when organised and interpreted."},{"kind":"concept","title":"EHR","text":"Electronic records must be accurate, timely and traceable."},{"kind":"concept","title":"Confidentiality","text":"Digital access does not mean unrestricted access."},{"kind":"concept","title":"Information literacy","text":"Not every online health source is reliable."},{"kind":"concept","title":"Decision support","text":"Technology can support—but not replace—clinical judgement."},{"kind":"concept","title":"Telehealth","text":"Remote care expands access but requires privacy and good communication."},{"kind":"lesson","title":"Computer basics","text":"Hardware, software, files, folders and word processing."},{"kind":"lesson","title":"Information management","text":"Understand data, information and knowledge."},{"kind":"lesson","title":"Source appraisal","text":"Check authority, date and evidence before using online health information."},{"kind":"lesson","title":"Electronic documentation","text":"Record objectively, accurately and promptly."},{"kind":"lesson","title":"Security","text":"Passwords, unattended screens and copied data can create privacy risks."},{"kind":"lesson","title":"Applications","text":"Education, research, management, telehealth and clinical information systems."},{"kind":"scenario","title":"A patient record is left open on screen","text":"Digital privacy is part of professional ethics."},{"kind":"scenario","title":"A medical claim appears on an unknown website","text":"Evaluate the source before using it."},{"kind":"scenario","title":"Copying an old note into today's record","text":"Verify that copied information is still correct."}],"sources":[]},{"id":"prac1","year":3,"sem":1,"code":"NURS 304ly","nAr":"التدريب التمريضي المكثف 1","nEn":"Intensive Nursing Practicum 1","typeAr":"سريري تمريضي","typeEn":"Clinical nursing","bigAr":"هذا هو المكان الذي يجب أن تبدأ فيه المعرفة بالعمل كمنظومة واحدة. لا تؤدي مهارة بمعزل عن المريض: قيّم، حدد الأولوية، نفذ بأمان، راقب الاستجابة، وثق وبلّغ.","bigEn":"Practicum 1 integrates knowledge at the bedside: assess, prioritise, perform safely, observe response, document and communicate.","chunksAr":[{"kind":"overview","title":"التدريب التمريضي المكثف 1","text":"هذا هو المكان الذي يجب أن تبدأ فيه المعرفة بالعمل كمنظومة واحدة. لا تؤدي مهارة بمعزل عن المريض: قيّم، حدد الأولوية، نفذ بأمان، راقب الاستجابة، وثق وبلّغ."},{"kind":"concept","title":"Clinical priorities","text":"ما الذي يهدد الحياة أو الوظيفة أولًا؟"},{"kind":"concept","title":"Oxygenation","text":"الأكسجين والنبض والأكسجة والشفط والـnebulization أدوات مرتبطة بتقييم التنفس."},{"kind":"concept","title":"IV therapy","text":"السوائل الوريدية تحتاج اختيارًا ومراقبة للمعدل والموقع والاستجابة."},{"kind":"concept","title":"ECG","text":"المراقبة الكهربائية للقلب تحتاج تقنية صحيحة وسياقًا سريريًا."},{"kind":"concept","title":"Blood transfusion","text":"التحقق قبل وأثناء وبعد النقل جزء أساسي من السلامة."},{"kind":"concept","title":"Dialysis & urinary care","text":"الكلى والإطراح والسوائل تظهر بوضوح في الممارسة."},{"kind":"lesson","title":"الأكسجين","text":"nasal cannula، face mask، pulse oximetry، suctioning وnebulization."},{"kind":"lesson","title":"السوائل الوريدية","text":"بدء ومتابعة السوائل ومراقبة الموقع والمعدل والمريض."},{"kind":"lesson","title":"Pediatric assessment","text":"علامات حيوية وتقييم يناسب الطفل وعمره."},{"kind":"lesson","title":"ECG","text":"وضع الأقطاب وجودة الإشارة والتعرف على أن المراقبة لا تساوي التشخيص وحده."},{"kind":"lesson","title":"Blood transfusion","text":"هوية المريض والدم والمراقبة والاستجابة لأي أعراض غير متوقعة."},{"kind":"lesson","title":"Dialysis","text":"فهم الوصول الوعائي/البريتوني والسوائل والمراقبة في سياق الرعاية."},{"kind":"scenario","title":"انخفض SpO₂ عند مريض","text":"لا تنظر للرقم فقط؛ قيّم المريض ووضع الحساس والتنفس ثم اتبع الإجراء."},{"kind":"scenario","title":"ظهر ألم أو تورم في موقع IV","text":"توقف عن تجاهل الموقع وقيّم احتمال مشكلة في القنية أو التسريب."},{"kind":"scenario","title":"بدأت أعراض أثناء نقل الدم","text":"تعرف أنها تستدعي استجابة سريعة وفق بروتوكول نقل الدم."},{"kind":"scenario","title":"ECG مليء بالتشويش","text":"تفحص الأقطاب والحركة والاتصال قبل افتراض أن الإشارة اضطراب قلبي."}],"chunksEn":[{"kind":"overview","title":"Intensive Nursing Practicum 1","text":"Practicum 1 integrates knowledge at the bedside: assess, prioritise, perform safely, observe response, document and communicate."},{"kind":"concept","title":"Clinical priorities","text":"Identify threats to life or function first."},{"kind":"concept","title":"Oxygenation","text":"Oxygen devices, pulse oximetry, suctioning and nebulisation depend on respiratory assessment."},{"kind":"concept","title":"IV therapy","text":"Fluids require correct setup, rate and site/patient monitoring."},{"kind":"concept","title":"ECG","text":"Accurate electrode placement and signal quality matter."},{"kind":"concept","title":"Blood transfusion","text":"Identity verification and observation are central to safety."},{"kind":"concept","title":"Dialysis & urinary care","text":"Renal function, fluids and elimination become practical nursing concerns."},{"kind":"lesson","title":"Oxygen therapy","text":"Nasal cannula, face mask, pulse oximetry, suctioning and nebulisation."},{"kind":"lesson","title":"IV fluids","text":"Initiate/maintain fluids and monitor site, rate and response."},{"kind":"lesson","title":"Pediatric assessment","text":"Use age-appropriate vital signs and assessment."},{"kind":"lesson","title":"ECG monitoring","text":"Place electrodes correctly and distinguish artifact from useful signal."},{"kind":"lesson","title":"Blood transfusion","text":"Verify patient/product and monitor for reaction."},{"kind":"lesson","title":"Dialysis","text":"Understand fluid removal, access and monitoring in context."},{"kind":"scenario","title":"SpO2 falls","text":"Assess the patient and sensor, not just the number."},{"kind":"scenario","title":"Pain/swelling at an IV site","text":"Assess for infiltration/phlebitis rather than ignoring the site."},{"kind":"scenario","title":"Symptoms begin during transfusion","text":"Recognise the need for prompt action according to protocol."},{"kind":"scenario","title":"ECG looks noisy","text":"Check movement and electrode contact before assuming arrhythmia."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"comm3","year":3,"sem":2,"code":"LANG 302ly","nAr":"مهارات التواصل 3","nEn":"Communication Skills 3","typeAr":"عام","typeEn":"General","bigAr":"في Communication Skills 3 ينتقل التركيز إلى الكلام أمام الآخرين والعرض المنظم: كيف تنقل فكرة صحية أو أكاديمية شفهيًا، بصوت مفهوم، وتسلسل واضح، ووسائل بصرية تساعد الفكرة بدل أن تشتت عنها.","bigEn":"Communication Skills 3 moves toward public speaking and structured presentation: explaining a health or academic idea clearly, using voice and visual aids effectively.","chunksAr":[{"kind":"overview","title":"مهارات التواصل 3","text":"في Communication Skills 3 ينتقل التركيز إلى الكلام أمام الآخرين والعرض المنظم: كيف تنقل فكرة صحية أو أكاديمية شفهيًا، بصوت مفهوم، وتسلسل واضح، ووسائل بصرية تساعد الفكرة بدل أن تشتت عنها."},{"kind":"concept","title":"Audience","text":"ابدأ بمن سيستمع: طالب، مريض، أسرة أو زملاء."},{"kind":"concept","title":"Purpose","text":"هل تريد أن تشرح، تقنع، تعلم، تلخص أو تعرض نتيجة؟"},{"kind":"concept","title":"Structure","text":"مقدمة واضحة، نقاط مرتبة، وخاتمة تعيد الرسالة الأساسية."},{"kind":"concept","title":"Voice","text":"النطق والسرعة والوقفات والنبرة تؤثر في الفهم."},{"kind":"concept","title":"Visual aids","text":"الشريحة تدعم المتحدث ولا تكون نصًا يقرأه."},{"kind":"concept","title":"Interaction","text":"التواصل الجيد يتضمن الاستماع للأسئلة والرد المباشر."},{"kind":"lesson","title":"خطط رسالتك","text":"اكتب جملة واحدة تلخص ما تريد أن يتذكره الحضور."},{"kind":"lesson","title":"قلل الشريحة","text":"كلمات أساسية وصورة أو مخطط أفضل من فقرة كاملة."},{"kind":"lesson","title":"انطق المصطلح","text":"تدرب على الأسماء الطبية والأرقام قبل العرض."},{"kind":"lesson","title":"تواصل بالعين","text":"لا تقرأ الشاشة طوال الوقت."},{"kind":"lesson","title":"تعامل مع السؤال","text":"استمع حتى النهاية وأعد السؤال إن احتجت ثم أجب بما تعرفه."},{"kind":"lesson","title":"اعترف بالحدود","text":"إذا لم تعرف، قل إنك ستتحقق بدل اختراع إجابة."},{"kind":"scenario","title":"عرض تثقيف صحي أمام مجموعة","text":"تختار ثلاث رسائل أساسية بدل حشر عشرين معلومة."},{"kind":"scenario","title":"سؤال مفاجئ بعد العرض","text":"لا تتسرع؛ تأكد أنك فهمت السؤال ثم أجب أو صرّح بالحاجة للتحقق."}],"chunksEn":[{"kind":"overview","title":"Communication Skills 3","text":"Communication Skills 3 moves toward public speaking and structured presentation: explaining a health or academic idea clearly, using voice and visual aids effectively."},{"kind":"concept","title":"Audience","text":"Adapt to patients, families, students or professionals."},{"kind":"concept","title":"Purpose","text":"Are you explaining, teaching, persuading or reporting?"},{"kind":"concept","title":"Structure","text":"Use a clear beginning, organised points and conclusion."},{"kind":"concept","title":"Voice","text":"Pronunciation, pace, pauses and tone affect understanding."},{"kind":"concept","title":"Visual aids","text":"Slides should support the message rather than become a script."},{"kind":"concept","title":"Interaction","text":"Listen to questions and respond to what was actually asked."},{"kind":"lesson","title":"Plan one key message","text":"Decide what the audience should remember."},{"kind":"lesson","title":"Reduce slide text","text":"Use key words, diagrams or images rather than paragraphs."},{"kind":"lesson","title":"Practise terminology","text":"Rehearse difficult medical terms and numbers."},{"kind":"lesson","title":"Maintain contact","text":"Avoid reading the screen throughout."},{"kind":"lesson","title":"Handle questions","text":"Listen fully, clarify if needed, then answer."},{"kind":"lesson","title":"Acknowledge limits","text":"If you do not know, say you will verify rather than inventing an answer."},{"kind":"scenario","title":"Giving a health-education talk","text":"Choose a few key messages rather than overwhelming the audience."},{"kind":"scenario","title":"An unexpected question","text":"Clarify the question and answer only what you know accurately."}],"sources":["who-safety"]},{"id":"biostat","year":3,"sem":2,"code":"MATH 301ly","nAr":"الإحصاء الحيوي","nEn":"Biostatistics","typeAr":"عام","typeEn":"General","bigAr":"الإحصاء الحيوي يحول البيانات إلى معلومات يمكن فهمها. لا يبدأ من المعادلة بل من السؤال: ما نوع البيانات؟ كيف وُصفت؟ وما الذي يمكن أن نستنتجه منها دون أن نقول أكثر مما تسمح به؟","bigEn":"Biostatistics turns health data into interpretable information. Start with the question and data type before choosing a calculation.","chunksAr":[{"kind":"overview","title":"الإحصاء الحيوي","text":"الإحصاء الحيوي يحول البيانات إلى معلومات يمكن فهمها. لا يبدأ من المعادلة بل من السؤال: ما نوع البيانات؟ كيف وُصفت؟ وما الذي يمكن أن نستنتجه منها دون أن نقول أكثر مما تسمح به؟"},{"kind":"concept","title":"Variable","text":"كل صفة أو قياس يمكن أن يأخذ قيمًا مختلفة."},{"kind":"concept","title":"Frequency","text":"كم مرة ظهرت قيمة أو فئة؟"},{"kind":"concept","title":"Mean/Median/Mode","text":"طرق مختلفة لوصف المركز، ولكل واحدة موقف يناسبها."},{"kind":"concept","title":"Variability","text":"المتوسط وحده لا يخبرك مدى تشتت القيم."},{"kind":"concept","title":"Percentage & rates","text":"تساعد على المقارنة عندما تختلف أحجام المجموعات."},{"kind":"concept","title":"Hypothesis testing","text":"طريقة منظمة لتقييم ما إذا كان الفرق المرصود قد يكون متوافقًا مع الصدفة ضمن افتراضات محددة."},{"kind":"lesson","title":"نظف البيانات أولًا","text":"خطأ واحد في إدخال العمر أو الضغط قد يغير النتيجة."},{"kind":"lesson","title":"اعرف نوع المتغير","text":"رقمي أم فئوي؟ مستمر أم رتبي؟ هذا يحدد الوصف والتحليل."},{"kind":"lesson","title":"لا تثق بالمتوسط وحده","text":"انظر إلى التوزيع والتشتت والقيم المتطرفة."},{"kind":"lesson","title":"ارسم البيانات","text":"الجدول والرسم قد يكشفان نمطًا لا يظهر في رقم واحد."},{"kind":"lesson","title":"افصل الوصف عن الاستنتاج","text":"Descriptive statistics تصف العينة؛ inferential statistics تحاول الاستدلال."},{"kind":"lesson","title":"اربط الرقم بالسؤال","text":"كل اختبار أو مقياس يجب أن يجيب عن سؤال واضح."},{"kind":"scenario","title":"متوسط ضغط مجموعتين مختلف","text":"تسأل عن حجم المجموعات والتشتت وطريقة الاختيار قبل استنتاج أن الفرق مهم."},{"kind":"scenario","title":"نتيجة استبيان 80% راضون","text":"تسأل: 80% من كم؟ ومن هم؟ وكيف اختيروا؟"},{"kind":"scenario","title":"قيمة متطرفة","text":"لا تحذفها تلقائيًا؛ تحقق هل هي خطأ أم قيمة حقيقية مهمة."}],"chunksEn":[{"kind":"overview","title":"Biostatistics","text":"Biostatistics turns health data into interpretable information. Start with the question and data type before choosing a calculation."},{"kind":"concept","title":"Variable","text":"A characteristic or measurement that can take different values."},{"kind":"concept","title":"Frequency","text":"How often a value/category occurs."},{"kind":"concept","title":"Mean/Median/Mode","text":"Different descriptions of centre."},{"kind":"concept","title":"Variability","text":"Shows how spread out observations are."},{"kind":"concept","title":"Percentages & rates","text":"Support comparison across groups."},{"kind":"concept","title":"Hypothesis testing","text":"A structured way to evaluate observed differences under stated assumptions."},{"kind":"lesson","title":"Clean data first","text":"Entry errors can distort results."},{"kind":"lesson","title":"Know the variable type","text":"Numeric, categorical and ordinal data are handled differently."},{"kind":"lesson","title":"Do not trust the mean alone","text":"Consider spread and outliers."},{"kind":"lesson","title":"Visualise data","text":"Tables and charts may reveal patterns."},{"kind":"lesson","title":"Describe before infer","text":"Separate sample description from population inference."},{"kind":"lesson","title":"Connect number to question","text":"Every statistic should answer a clear question."},{"kind":"scenario","title":"Two groups have different mean blood pressures","text":"Ask about sample size, variability and sampling before concluding importance."},{"kind":"scenario","title":"A survey says 80% are satisfied","text":"Ask 80% of how many, and who was sampled."},{"kind":"scenario","title":"One value is extreme","text":"Check whether it is an error or a real important observation before removing it."}],"sources":[]},{"id":"epi","year":3,"sem":2,"code":"MED 301ly","nAr":"علم الوبائيات","nEn":"Epidemiology","typeAr":"عام بحسب توصيف المقرر","typeEn":"General (course description)","bigAr":"الوبائيات تسأل: من يصاب؟ أين؟ متى؟ ولماذا؟ بدل التركيز على مريض واحد، تدرس نمط المرض في مجموعة لتفهم العوامل المرتبطة به وتخطط للوقاية والسيطرة.","bigEn":"Epidemiology asks who is affected, where, when and why. It studies patterns of health and disease in populations to support prevention and control.","chunksAr":[{"kind":"overview","title":"علم الوبائيات","text":"الوبائيات تسأل: من يصاب؟ أين؟ متى؟ ولماذا؟ بدل التركيز على مريض واحد، تدرس نمط المرض في مجموعة لتفهم العوامل المرتبطة به وتخطط للوقاية والسيطرة."},{"kind":"concept","title":"Incidence","text":"حالات جديدة تظهر خلال فترة معينة."},{"kind":"concept","title":"Prevalence","text":"كل الحالات الموجودة في نقطة أو فترة."},{"kind":"concept","title":"Risk factors","text":"عوامل ترتبط بزيادة احتمال حدوث المشكلة."},{"kind":"concept","title":"Surveillance","text":"جمع وتحليل ومتابعة البيانات للكشف عن الأنماط."},{"kind":"concept","title":"Transmission","text":"فهم طريق الانتقال يساعد على قطع السلسلة."},{"kind":"concept","title":"Population","text":"المقام الصحيح مهم؛ العدد وحده لا يكفي للمقارنة."},{"kind":"lesson","title":"اسأل عن المقام","text":"10 حالات في 100 شخص ليست مثل 10 في 10000."},{"kind":"lesson","title":"الزمن مهم","text":"الزيادة السريعة تختلف عن معدل مستقر على سنوات."},{"kind":"lesson","title":"مصدر البيانات","text":"جودة القرار تعتمد على جودة التسجيل والتعريفات."},{"kind":"lesson","title":"العدوى","text":"الوكيل والمضيف والبيئة وطريق الانتقال تساعد على فهم التفشي."},{"kind":"lesson","title":"العدوى بالمستشفى","text":"التسجيل والمراقبة ومكافحة العدوى تتكامل."},{"kind":"lesson","title":"الأمراض غير المعدية","text":"الوبائيات لا تخص العدوى فقط؛ السرطان وأمراض القلب لها أنماط وعوامل خطر أيضًا."},{"kind":"scenario","title":"زادت حالات التهاب معين في جناح","text":"تسأل هل هناك نمط في الوقت أو المكان أو الإجراء قبل القفز إلى تفسير واحد."},{"kind":"scenario","title":"مقارنة منطقتين","text":"تستخدم معدلًا مناسبًا لا العدد الخام فقط."},{"kind":"scenario","title":"حملة تطعيم","text":"تفهم أن الهدف ليس الفرد فقط بل خفض خطر المرض في المجتمع."}],"chunksEn":[{"kind":"overview","title":"Epidemiology","text":"Epidemiology asks who is affected, where, when and why. It studies patterns of health and disease in populations to support prevention and control."},{"kind":"concept","title":"Incidence","text":"New cases occurring over a defined period."},{"kind":"concept","title":"Prevalence","text":"Existing cases in a population at a point/period."},{"kind":"concept","title":"Risk factors","text":"Characteristics associated with higher probability of an outcome."},{"kind":"concept","title":"Surveillance","text":"Ongoing collection and interpretation of health data."},{"kind":"concept","title":"Transmission","text":"Understanding routes helps break chains of infection."},{"kind":"concept","title":"Population denominator","text":"Raw counts are often misleading without the population size."},{"kind":"lesson","title":"Always ask the denominator","text":"Ten cases in 100 people differs from ten in 10,000."},{"kind":"lesson","title":"Time matters","text":"A sudden cluster differs from a stable long-term pattern."},{"kind":"lesson","title":"Data source matters","text":"Good epidemiology depends on definitions and accurate reporting."},{"kind":"lesson","title":"Infectious disease","text":"Think agent, host, environment and transmission."},{"kind":"lesson","title":"Healthcare-associated infection","text":"Surveillance and infection prevention work together."},{"kind":"lesson","title":"Non-communicable disease","text":"Cancer and cardiovascular disease also have population patterns and risk factors."},{"kind":"scenario","title":"Cases increase on one ward","text":"Look for a pattern in time, place and procedures before assuming a cause."},{"kind":"scenario","title":"Comparing two regions","text":"Use rates rather than raw counts alone."},{"kind":"scenario","title":"Vaccination programme","text":"Understand population prevention, not only individual protection."}],"sources":[]},{"id":"mental","year":3,"sem":2,"code":"NURS 305ly","nAr":"تمريض الصحة النفسية والعقلية","nEn":"Mental Health and Psychiatric Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"جوهر هذا المقرر ليس حفظ أسماء الاضطرابات؛ بل بناء علاقة علاجية، ملاحظة السلوك والتفكير والمزاج، تقييم السلامة، التواصل دون حكم، وفهم أن الشخص أكبر من التشخيص.","bigEn":"The core of mental health nursing is not simply naming disorders. It is therapeutic relationship, observation of behaviour/thought/mood, safety assessment, non-judgmental communication and seeing the person beyond the diagnosis.","chunksAr":[{"kind":"overview","title":"تمريض الصحة النفسية والعقلية","text":"جوهر هذا المقرر ليس حفظ أسماء الاضطرابات؛ بل بناء علاقة علاجية، ملاحظة السلوك والتفكير والمزاج، تقييم السلامة، التواصل دون حكم، وفهم أن الشخص أكبر من التشخيص."},{"kind":"concept","title":"Therapeutic relationship","text":"علاقة مهنية لها هدف وحدود، وليست صداقة شخصية."},{"kind":"concept","title":"Use of self","text":"طريقة حضور الممرض وكلامه وصمته قد تكون جزءًا من الرعاية."},{"kind":"concept","title":"Anxiety","text":"القلق له درجات وقد يؤثر في قدرة الشخص على التفكير والتعلم والتواصل."},{"kind":"concept","title":"Crisis","text":"الأزمة قد تتجاوز أساليب التكيف المعتادة وتحتاج تقييمًا ودعمًا سريعًا."},{"kind":"concept","title":"Mood & thought","text":"المزاج والتفكير والإدراك والسلوك كلها مجالات للملاحظة المنظمة."},{"kind":"concept","title":"Safety","text":"تقييم الخطر على النفس أو الآخرين أولوية عند وجود إشارات مقلقة."},{"kind":"lesson","title":"التواصل العلاجي","text":"الأسئلة المفتوحة، الانعكاس، التوضيح والصمت قد تكون أكثر فائدة من النصيحة السريعة."},{"kind":"lesson","title":"الحدود","text":"حافظ على دور مهني واضح ولا تجعل احتياجاتك الشخصية محور العلاقة."},{"kind":"lesson","title":"القلق والأزمة","text":"هدئ البيئة وتواصل ببساطة وقيّم ما يحتاج تدخلًا عاجلًا."},{"kind":"lesson","title":"الذهان","text":"لا تدخل في جدال مباشر مع تجربة الشخص؛ ركز على الأمان والواقع والتواصل الهادئ."},{"kind":"lesson","title":"اضطرابات المزاج","text":"راقب التغير في النوم والطاقة والسلوك والوظيفة مع تقييم السلامة."},{"kind":"lesson","title":"العلاج","text":"العلاج قد يشمل دواءً وتدخلات نفسية واجتماعية وبيئية؛ الممرض يراقب ويعلّم ويدعم."},{"kind":"scenario","title":"مريض يقول شيئًا غير واقعي بالنسبة لك","text":"لا تسخر ولا تؤكد الفكرة؛ استمع وركز على مشاعره وسلامته والواقع الملموس."},{"kind":"scenario","title":"شخص شديد القلق لا يستطيع متابعة شرح طويل","text":"تقلل المعلومات وتستخدم جملًا قصيرة وبيئة أهدأ."},{"kind":"scenario","title":"مريض منعزل وتغير سلوكه","text":"تعرف أن التغير نفسه معلومة تستحق الملاحظة والتواصل مع الفريق."},{"kind":"scenario","title":"حديث يوحي بإيذاء النفس","text":"لا تتجاهله أو تعد بالسرية المطلقة؛ السلامة والتقييم والإبلاغ حسب الإجراء أولوية."}],"chunksEn":[{"kind":"overview","title":"Mental Health and Psychiatric Nursing","text":"The core of mental health nursing is not simply naming disorders. It is therapeutic relationship, observation of behaviour/thought/mood, safety assessment, non-judgmental communication and seeing the person beyond the diagnosis."},{"kind":"concept","title":"Therapeutic relationship","text":"A purposeful professional relationship with boundaries."},{"kind":"concept","title":"Use of self","text":"Presence, words and silence can support care."},{"kind":"concept","title":"Anxiety","text":"Different levels affect thinking, learning and communication."},{"kind":"concept","title":"Crisis","text":"A person's usual coping may be overwhelmed."},{"kind":"concept","title":"Mood & thought","text":"Observe mood, thinking, perception and behaviour systematically."},{"kind":"concept","title":"Safety","text":"Risk to self or others becomes a priority when warning signs appear."},{"kind":"lesson","title":"Therapeutic communication","text":"Open questions, reflection, clarification and silence can be more useful than quick advice."},{"kind":"lesson","title":"Boundaries","text":"Keep a professional role and avoid making your own needs central."},{"kind":"lesson","title":"Anxiety/crisis","text":"Reduce stimulation, communicate simply and assess urgency."},{"kind":"lesson","title":"Psychosis","text":"Do not ridicule or reinforce unusual beliefs; focus on safety and present reality."},{"kind":"lesson","title":"Mood disorders","text":"Observe sleep, energy, function and safety."},{"kind":"lesson","title":"Treatment","text":"Medicines, psychological/social interventions and therapeutic environment may all be involved."},{"kind":"scenario","title":"A patient describes an experience you do not share","text":"Listen without ridicule, focus on feelings, safety and concrete reality."},{"kind":"scenario","title":"A very anxious person cannot follow long explanations","text":"Use short simple communication and a calmer environment."},{"kind":"scenario","title":"A previously social patient becomes withdrawn","text":"A change in behaviour is useful clinical information."},{"kind":"scenario","title":"A patient hints at self-harm","text":"Do not dismiss it or promise absolute secrecy; safety assessment and escalation matter."}],"sources":["openstax-psych","openrn-mental"]},{"id":"adult2","year":3,"sem":2,"code":"NURS 306ly","nAr":"تمريض البالغين 2","nEn":"Adult Nursing 2","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"يكمل Adult Nursing 2 الصورة بالتركيز على الجهاز الهضمي والاستقلاب والغدد الصماء. المفتاح هو رؤية العلاقة بين الهرمون أو العضو والتغير الذي يظهر على السكر والطاقة والسوائل والهضم وبقية الجسم.","bigEn":"Adult Nursing 2 focuses on gastrointestinal, metabolic and endocrine problems. The key is connecting organs and hormones with glucose, energy, fluids, digestion and whole-body effects.","chunksAr":[{"kind":"overview","title":"تمريض البالغين 2","text":"يكمل Adult Nursing 2 الصورة بالتركيز على الجهاز الهضمي والاستقلاب والغدد الصماء. المفتاح هو رؤية العلاقة بين الهرمون أو العضو والتغير الذي يظهر على السكر والطاقة والسوائل والهضم وبقية الجسم."},{"kind":"concept","title":"GI function","text":"الهضم والامتصاص والحركة والكبد والبنكرياس وظائف مترابطة."},{"kind":"concept","title":"Metabolism","text":"الجسم يبني ويهدم ويخزن الوقود باستمرار."},{"kind":"concept","title":"Endocrine feedback","text":"الهرمونات تعمل في حلقات تنظيم؛ خلل صغير قد يؤثر في أكثر من جهاز."},{"kind":"concept","title":"Glucose control","text":"الإنسولين والهرمونات والكبد والأنسجة تنظم الجلوكوز."},{"kind":"concept","title":"Assessment","text":"الوزن والشهية والبطن والبراز والسكر والسوائل كلها أجزاء من التقييم."},{"kind":"concept","title":"Patient education","text":"كثير من الحالات المزمنة تحتاج إدارة يومية من المريض نفسه."},{"kind":"lesson","title":"الجهاز الهضمي","text":"ابدأ بالوظيفة الطبيعية ثم اربط الألم والنزف والقيء والإسهال واليرقان بالموقع والوظيفة."},{"kind":"lesson","title":"الكبد","text":"تذكر دوره في الاستقلاب والتخزين والتخثر وإزالة السموم."},{"kind":"lesson","title":"السكري","text":"اربط الجلوكوز والإنسولين بالغذاء والأدوية والمرض والنشاط."},{"kind":"lesson","title":"الغدة الدرقية","text":"الزيادة والنقص تغيران الاستقلاب وأجهزة متعددة."},{"kind":"lesson","title":"الكظر","text":"الكورتيزول والألدوستيرون وغيرها تؤثر في الضغط والسوائل والاستجابة للإجهاد."},{"kind":"lesson","title":"التثقيف الذاتي","text":"المراقبة المنزلية والغذاء والأدوية ومعرفة علامات الخطر أساسية في الأمراض المزمنة."},{"kind":"scenario","title":"مريض سكري مريض ولا يأكل جيدًا","text":"تعرف أن المرض والغذاء والدواء والجلوكوز يتفاعلون، فلا تطبق روتينًا آليًا دون تقييم."},{"kind":"scenario","title":"يرقان جديد","text":"تربط لون الجلد والعين بوظائف الكبد ومسار البيليروبين وتحتاج تقييمًا."},{"kind":"scenario","title":"خفقان وفقد وزن وعدم تحمل الحرارة","text":"تفكر في نمط هرموني محتمل دون تشخيص مستقل، وتجمع ملاحظات منظمة."},{"kind":"scenario","title":"قيء مستمر","text":"لا تنس السوائل والشوارد والحمض/القاعدة مع المشكلة الهضمية."}],"chunksEn":[{"kind":"overview","title":"Adult Nursing 2","text":"Adult Nursing 2 focuses on gastrointestinal, metabolic and endocrine problems. The key is connecting organs and hormones with glucose, energy, fluids, digestion and whole-body effects."},{"kind":"concept","title":"GI function","text":"Digestion, absorption, motility, liver and pancreas work together."},{"kind":"concept","title":"Metabolism","text":"The body builds, breaks down and stores fuel continuously."},{"kind":"concept","title":"Endocrine feedback","text":"Hormonal feedback loops regulate multiple systems."},{"kind":"concept","title":"Glucose control","text":"Insulin, hormones, liver and tissues regulate blood glucose."},{"kind":"concept","title":"Assessment","text":"Weight, appetite, abdomen, stool, glucose and fluids all contribute."},{"kind":"concept","title":"Self-management","text":"Many chronic conditions require daily patient decisions and monitoring."},{"kind":"lesson","title":"GI disorders","text":"Connect pain, bleeding, vomiting, diarrhoea and jaundice with structure/function."},{"kind":"lesson","title":"Liver","text":"Remember roles in metabolism, storage, clotting and detoxification."},{"kind":"lesson","title":"Diabetes","text":"Connect glucose, insulin, food, activity and medicine."},{"kind":"lesson","title":"Thyroid","text":"Excess or deficiency changes metabolism throughout the body."},{"kind":"lesson","title":"Adrenal function","text":"Cortisol/aldosterone affect stress, pressure and fluids."},{"kind":"lesson","title":"Patient education","text":"Home monitoring, medicines, diet and warning signs matter."},{"kind":"scenario","title":"A person with diabetes is ill and eating poorly","text":"Illness, food, medicines and glucose interact; do not apply routines blindly."},{"kind":"scenario","title":"New jaundice","text":"Connect colour change with liver/bilirubin pathways and assessment."},{"kind":"scenario","title":"Palpitations, weight loss and heat intolerance","text":"Recognise a pattern that warrants endocrine assessment."},{"kind":"scenario","title":"Persistent vomiting","text":"Remember fluids, electrolytes and acid-base consequences."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"prac2","year":3,"sem":2,"code":"NURS 307ly","nAr":"التدريب التمريضي المكثف 2","nEn":"Intensive Nursing Practicum 2","typeAr":"سريري تمريضي","typeEn":"Clinical nursing","bigAr":"Practicum 2 يربط رعاية الجهاز الهضمي والاستقلاب والغدد مع الصحة النفسية. المطلوب هو أن ترى المريض ككل: جسد، تغذية، إخراج، نفسية، تواصل، سلامة وتوثيق.","bigEn":"Practicum 2 connects GI/metabolic/endocrine care with mental health. The patient remains a whole person: body, nutrition, elimination, emotions, communication, safety and documentation.","chunksAr":[{"kind":"overview","title":"التدريب التمريضي المكثف 2","text":"Practicum 2 يربط رعاية الجهاز الهضمي والاستقلاب والغدد مع الصحة النفسية. المطلوب هو أن ترى المريض ككل: جسد، تغذية، إخراج، نفسية، تواصل، سلامة وتوثيق."},{"kind":"concept","title":"History & assessment","text":"التاريخ والفحص المنظم يوجهان ما تفعله بعد ذلك."},{"kind":"concept","title":"NGT","text":"إدخال الأنبوب أو إزالته ليس حركة فقط؛ يجب فهم الهدف والتحقق والمراقبة."},{"kind":"concept","title":"Gastric lavage","text":"إجراء له مؤشرات ومخاطر ويُنفذ وفق تعليمات وإشراف."},{"kind":"concept","title":"TPN","text":"تغذية وريدية عالية التعقيد تتطلب مراقبة الخط والجلوكوز والعدوى والاستقلاب."},{"kind":"concept","title":"Ostomy","text":"العناية تشمل الجلد والمخرج والتغذية وصورة الجسد والتثقيف."},{"kind":"concept","title":"Psychiatric care","text":"التواصل العلاجي والسلامة والحدود المهنية تستمر داخل التدريب السريري."},{"kind":"lesson","title":"NGT insertion/removal","text":"التحضير والوضعية والتأكد من الإجراء والتوثيق ومراقبة المريض."},{"kind":"lesson","title":"Enema","text":"الهدف والوضعية والخصوصية والمراقبة."},{"kind":"lesson","title":"Ostomy care","text":"حماية الجلد وملاحظة stoma وتعليم المريض."},{"kind":"lesson","title":"TPN","text":"المراقبة والعدوى والجلوكوز والوريد المركزي عناصر مهمة."},{"kind":"lesson","title":"Psychiatric rotation","text":"راقب العلاقة والتواصل والسلوك والسلامة، لا الأعراض فقط."},{"kind":"lesson","title":"Case study","text":"اجمع البيانات وحولها إلى تفسير وخطة رعاية لا مجرد نسخ ملف المريض."},{"kind":"scenario","title":"مريض يسحب NGT مرارًا","text":"لا تعيده آليًا فقط؛ قيّم السبب والوعي والانزعاج والخطر واطلب الخطة المناسبة."},{"kind":"scenario","title":"احمرار حول stoma","text":"تفحص الجلد والتسريب والملاءمة بدل اعتبار الاحمرار أمرًا طبيعيًا."},{"kind":"scenario","title":"مريض نفسي يرفض الحديث","text":"لا تضغط عليه؛ استعمل حضورًا هادئًا وحدودًا واضحة ووقتًا مناسبًا."},{"kind":"scenario","title":"TPN وخط وريدي مركزي","text":"تعرف أن أي علامة عدوى أو تغير استقلابي تحتاج انتباهًا لأن الطريق عالي الخطورة."}],"chunksEn":[{"kind":"overview","title":"Intensive Nursing Practicum 2","text":"Practicum 2 connects GI/metabolic/endocrine care with mental health. The patient remains a whole person: body, nutrition, elimination, emotions, communication, safety and documentation."},{"kind":"concept","title":"History & assessment","text":"Systematic data collection guides what comes next."},{"kind":"concept","title":"NGT","text":"Insertion/removal requires purpose, verification and observation."},{"kind":"concept","title":"Gastric lavage","text":"A specific procedure with indications and risks."},{"kind":"concept","title":"TPN","text":"High-complexity intravenous nutrition needs infection/metabolic monitoring."},{"kind":"concept","title":"Ostomy","text":"Care includes stoma/skin, nutrition, body image and education."},{"kind":"concept","title":"Psychiatric care","text":"Therapeutic communication, safety and boundaries remain core clinical skills."},{"kind":"lesson","title":"NGT insertion/removal","text":"Preparation, positioning, verification, monitoring and documentation."},{"kind":"lesson","title":"Enema","text":"Purpose, privacy, positioning and response."},{"kind":"lesson","title":"Ostomy care","text":"Observe stoma and protect peristomal skin."},{"kind":"lesson","title":"TPN","text":"Monitor line, glucose, infection and metabolic response."},{"kind":"lesson","title":"Psychiatric rotation","text":"Observe relationship, communication, behaviour and safety."},{"kind":"lesson","title":"Case study","text":"Turn collected data into interpretation and a nursing plan."},{"kind":"scenario","title":"A patient repeatedly removes an NGT","text":"Assess discomfort, cognition and risk rather than simply replacing it automatically."},{"kind":"scenario","title":"Redness around a stoma","text":"Assess leakage, skin condition and appliance fit."},{"kind":"scenario","title":"A psychiatric patient refuses conversation","text":"Use calm presence and clear boundaries rather than pressuring."},{"kind":"scenario","title":"TPN through a central line","text":"Recognise the importance of infection and metabolic monitoring."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"medterm2","year":4,"sem":1,"code":"LANG 401ly","nAr":"المصطلحات الطبية 2","nEn":"Medical Terminology 2","typeAr":"عام","typeEn":"General","bigAr":"Medical Terminology 2 ينقل المصطلح من قائمة كلمات إلى لغة تستخدمها في أقسام المستشفى. الهدف أن تفهم معنى المصطلح، تنطقه وتكتبه بصورة صحيحة، وتربطه بالمكان والإجراء والتخصص الذي يستخدمه.","bigEn":"Medical Terminology 2 moves terminology into hospital departments. Students learn to understand, pronounce and use terms in emergency, cardiology, ICU, neurology, oncology, obstetrics, pediatrics, radiology, laboratory and administration.","chunksAr":[{"kind":"overview","title":"المصطلحات الطبية 2","text":"Medical Terminology 2 ينقل المصطلح من قائمة كلمات إلى لغة تستخدمها في أقسام المستشفى. الهدف أن تفهم معنى المصطلح، تنطقه وتكتبه بصورة صحيحة، وتربطه بالمكان والإجراء والتخصص الذي يستخدمه."},{"kind":"concept","title":"Department language","text":"لكل قسم مجموعة متكررة من الكلمات والإجراءات."},{"kind":"concept","title":"Procedure terms","text":"اسم الإجراء غالبًا يكشف العضو أو الطريقة أو الهدف."},{"kind":"concept","title":"Diagnostic language","text":"المختبر والأشعة يستخدمان مفردات تختلف عن لغة الأعراض."},{"kind":"concept","title":"Clinical abbreviations","text":"استخدم الاختصارات المعتمدة فقط وتجنب الغامض."},{"kind":"concept","title":"Context","text":"معنى الكلمة يصبح أوضح عندما تراها داخل تقرير أو طلب أو تسليم."},{"kind":"concept","title":"Pronunciation","text":"وضوح النطق مهم في أسماء الأدوية والإجراءات والتخصصات."},{"kind":"lesson","title":"Emergency & ICU","text":"تعلم مفردات الاستقرار، المراقبة، مجرى الهواء، الإنعاش والمعدات الشائعة."},{"kind":"lesson","title":"Cardiology & Neurology","text":"اربط المصطلح بالعضو والفحص والمشكلة الوظيفية."},{"kind":"lesson","title":"Oncology","text":"تعلم كلمات tumor, metastasis, biopsy, chemotherapy, radiotherapy, remission وغيرها في سياقها."},{"kind":"lesson","title":"OB/Peds/Neonatal","text":"تتغير المفردات عندما يكون السياق حملًا أو ولادة أو طفلًا أو وليدًا."},{"kind":"lesson","title":"Radiology/Pathology/Lab","text":"تعرف الفرق بين specimen، imaging، culture، biopsy، report وغيرها."},{"kind":"lesson","title":"Medical records & administration","text":"اللغة الدقيقة مهمة في الطلبات والتوثيق والتسليم."},{"kind":"scenario","title":"تسمع اختصارًا غير مألوف في ICU","text":"لا تخمنه؛ تحقق من القائمة المعتمدة أو اسأل بوضوح."},{"kind":"scenario","title":"تقرأ تقرير أشعة ثم تقرير مختبر","text":"تتعلم أن الكلمات تصف أنواعًا مختلفة من الأدلة ولا تُفسر بالطريقة نفسها."},{"kind":"scenario","title":"تسلم مريضًا لقسم آخر","text":"استخدام المصطلحات المشتركة بدقة يقلل سوء الفهم بين الأقسام."}],"chunksEn":[{"kind":"overview","title":"Medical Terminology 2","text":"Medical Terminology 2 moves terminology into hospital departments. Students learn to understand, pronounce and use terms in emergency, cardiology, ICU, neurology, oncology, obstetrics, pediatrics, radiology, laboratory and administration."},{"kind":"concept","title":"Department vocabulary","text":"Each clinical area has recurring procedures and terms."},{"kind":"concept","title":"Procedure terms","text":"Word structure often indicates body site or procedure."},{"kind":"concept","title":"Diagnostic language","text":"Laboratory and imaging reports use different forms of evidence."},{"kind":"concept","title":"Abbreviations","text":"Use approved abbreviations and clarify ambiguous ones."},{"kind":"concept","title":"Context","text":"Meaning becomes easier inside reports and handovers."},{"kind":"concept","title":"Pronunciation","text":"Clear speech matters for medicines, procedures and specialist terms."},{"kind":"lesson","title":"Emergency & ICU","text":"Stabilisation, airway, resuscitation and monitoring vocabulary."},{"kind":"lesson","title":"Cardiology & neurology","text":"Connect terminology to anatomy and assessment."},{"kind":"lesson","title":"Oncology","text":"tumor, metastasis, biopsy, chemotherapy, radiotherapy, remission."},{"kind":"lesson","title":"OB/Peds/Neonatal","text":"Use age- and maternity-specific vocabulary."},{"kind":"lesson","title":"Radiology/Pathology/Lab","text":"Distinguish specimen, culture, biopsy, imaging and report language."},{"kind":"lesson","title":"Medical records","text":"Precision supports documentation and interdepartmental communication."},{"kind":"scenario","title":"An unfamiliar ICU abbreviation appears","text":"Clarify rather than guessing."},{"kind":"scenario","title":"Reading imaging and laboratory reports","text":"Recognise that different reports represent different types of clinical evidence."},{"kind":"scenario","title":"Transferring a patient between departments","text":"Shared accurate terminology reduces misunderstanding."}],"sources":["openrn-medterm"]},{"id":"onco","year":4,"sem":1,"code":"NURS 401ly","nAr":"تمريض الأورام والطوارئ والكوارث","nEn":"Oncology and Emergency with Disaster Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"يجمع المقرر بين محورين يحتاجان تفكيرًا مختلفًا لكنهما يشتركان في الأولويات: رعاية مريض الأورام عبر رحلة طويلة ومعقدة، والاستجابة السريعة في الطوارئ والكوارث عندما يجب تحديد الأخطر أولًا واتخاذ قرارات منظمة تحت ضغط.","bigEn":"This course combines long-term complex oncology care with rapid emergency/disaster decision-making. Both require prioritisation, safety, communication and disciplined nursing judgement.","chunksAr":[{"kind":"overview","title":"تمريض الأورام والطوارئ والكوارث","text":"يجمع المقرر بين محورين يحتاجان تفكيرًا مختلفًا لكنهما يشتركان في الأولويات: رعاية مريض الأورام عبر رحلة طويلة ومعقدة، والاستجابة السريعة في الطوارئ والكوارث عندما يجب تحديد الأخطر أولًا واتخاذ قرارات منظمة تحت ضغط."},{"kind":"concept","title":"Cancer biology","text":"السرطان يبدأ عندما تفقد بعض الخلايا تنظيم النمو والانقسام وتكتسب قدرة على الغزو أو الانتشار."},{"kind":"concept","title":"Benign vs malignant","text":"الفرق لا يعتمد على الحجم فقط؛ الغزو والانتشار والخصائص الخلوية مهمة."},{"kind":"concept","title":"Staging & grading","text":"التدريج والمرحلة يساعدان على وصف مدى المرض وخصائصه، وليس مجرد تسمية الورم."},{"kind":"concept","title":"Treatment burden","text":"الجراحة والإشعاع والعلاج الدوائي قد تعالج المرض لكنها قد تسبب آثارًا تحتاج رعاية دقيقة."},{"kind":"concept","title":"Triage","text":"في الطوارئ لا يُرتب الناس حسب وقت الوصول فقط؛ الأولوية ترتبط بخطر تدهور الحياة أو الوظيفة."},{"kind":"concept","title":"Disaster thinking","text":"في الكوارث تصبح الموارد محدودة، فيحتاج الفريق إلى تنظيم الأدوار والسلامة والاتصال والفرز."},{"kind":"lesson","title":"Carcinogenesis","text":"افهم أن السرطان عملية متعددة المراحل تتأثر بعوامل جينية وبيئية وسلوكية."},{"kind":"lesson","title":"Metastasis","text":"انتشار الخلايا إلى أعضاء أخرى يغير صورة المرض وخطة الرعاية."},{"kind":"lesson","title":"Oncology treatment","text":"اربط العلاج بالهدف: cure أو control أو palliation، ثم اسأل ما الاحتياجات التمريضية المصاحبة."},{"kind":"lesson","title":"Cancer prevention","text":"الوقاية والكشف المبكر قد يقللان العبء قبل الوصول إلى العلاج المعقد."},{"kind":"lesson","title":"Emergency priorities","text":"ابدأ بالسلامة وABCDE والتقييم السريع ثم أعد التقييم بعد كل تدخل."},{"kind":"lesson","title":"Disaster response","text":"تعرف دورك، خط الاتصال، منطقة العمل، معدات الحماية، والفرز دون العمل خارج صلاحياتك."},{"kind":"scenario","title":"مريض علاج كيميائي وحرارته مرتفعة","text":"تفهم أن العدوى قد تكون أكثر خطورة مع تثبيط المناعة، لذلك لا تتعامل مع الحمى كعرض بسيط."},{"kind":"scenario","title":"عدة مصابين يصلون معًا","text":"تستخدم مبادئ الفرز والأولوية بدل البدء بأكثر شخص يصرخ أو يطلب المساعدة."},{"kind":"scenario","title":"مريض أورام يسأل عن هدف علاجه","text":"تميّز بين العلاج بقصد الشفاء أو السيطرة أو التلطيف وتعرف أهمية التواصل الصريح ضمن دور الفريق."},{"kind":"scenario","title":"مريض طوارئ يتدهور بسرعة","text":"تتعلم أن إعادة التقييم المستمر أهم من افتراض أن الحالة بقيت كما كانت عند الوصول."}],"chunksEn":[{"kind":"overview","title":"Oncology and Emergency with Disaster Nursing","text":"This course combines long-term complex oncology care with rapid emergency/disaster decision-making. Both require prioritisation, safety, communication and disciplined nursing judgement."},{"kind":"concept","title":"Cancer biology","text":"Cancer involves loss of normal growth control with potential invasion and spread."},{"kind":"concept","title":"Benign vs malignant","text":"Invasion, spread and cellular characteristics matter—not size alone."},{"kind":"concept","title":"Staging & grading","text":"Describe extent and characteristics of disease."},{"kind":"concept","title":"Treatment burden","text":"Surgery, radiotherapy and systemic therapy can create important nursing needs."},{"kind":"concept","title":"Triage","text":"Priority is based on risk and urgency, not simply arrival order."},{"kind":"concept","title":"Disaster response","text":"Limited resources require clear roles, communication and organised triage."},{"kind":"lesson","title":"Carcinogenesis","text":"Think of cancer as a multistep process influenced by genetic, environmental and behavioural factors."},{"kind":"lesson","title":"Metastasis","text":"Spread to other sites changes disease burden and care needs."},{"kind":"lesson","title":"Treatment intent","text":"Differentiate cure, control and palliation."},{"kind":"lesson","title":"Cancer prevention","text":"Primary prevention and early detection can reduce burden."},{"kind":"lesson","title":"Emergency priorities","text":"Use safety and ABCDE thinking with repeated reassessment."},{"kind":"lesson","title":"Disaster organisation","text":"Know role, communication pathway, PPE and scope of practice."},{"kind":"scenario","title":"Fever during chemotherapy","text":"Recognise that infection risk may be higher and fever needs prompt assessment."},{"kind":"scenario","title":"Several injured people arrive together","text":"Use triage and urgency rather than choosing the loudest patient."},{"kind":"scenario","title":"A patient asks the goal of cancer treatment","text":"Recognise different treatment intents and communicate within the team's plan."},{"kind":"scenario","title":"An emergency patient deteriorates","text":"Reassess rather than assuming the initial status remains unchanged."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"adult3","year":4,"sem":1,"code":"NURS 402ly","nAr":"تمريض البالغين 3","nEn":"Adult Nursing 3","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"يكمل هذا المقرر رعاية البالغين عبر المناعة والجهاز العصبي والعضلي الهيكلي والحواس الخاصة. هنا يصبح السؤال الأساسي: كيف يؤثر الخلل في الحركة أو الإحساس أو التنسيق أو المناعة على استقلال المريض وسلامته وحياته اليومية؟","bigEn":"Adult Nursing 3 focuses on immune, neurologic, musculoskeletal and special-sense problems, with strong attention to function, coordination, mobility, independence and safety.","chunksAr":[{"kind":"overview","title":"تمريض البالغين 3","text":"يكمل هذا المقرر رعاية البالغين عبر المناعة والجهاز العصبي والعضلي الهيكلي والحواس الخاصة. هنا يصبح السؤال الأساسي: كيف يؤثر الخلل في الحركة أو الإحساس أو التنسيق أو المناعة على استقلال المريض وسلامته وحياته اليومية؟"},{"kind":"concept","title":"Inflammation & immunity","text":"المناعة تحمي الجسم، لكن فرط الاستجابة أو ضعفها قد يسبب مرضًا أو يزيد العدوى."},{"kind":"concept","title":"Neuro assessment","text":"الوعي، الحدقات، القوة، الإحساس والكلام علامات قد تتغير سريعًا."},{"kind":"concept","title":"Mobility","text":"العظام والمفاصل والعضلات والأعصاب تعمل كوحدة للحركة والاستقلال."},{"kind":"concept","title":"Pain & function","text":"شدة الألم مهمة، لكن تأثيره في الحركة والنوم والتنفس والوظيفة مهم أيضًا."},{"kind":"concept","title":"Special senses","text":"فقد السمع أو البصر يغير التواصل والسلامة والاستقلال."},{"kind":"concept","title":"Rehabilitation","text":"الهدف ليس علاج المرض فقط؛ أحيانًا هو استعادة الوظيفة أو التكيف مع فقدها."},{"kind":"lesson","title":"المناعة","text":"اربط الحساسية والالتهاب واضطرابات المناعة بآليات الدفاع ومخاطر العدوى."},{"kind":"lesson","title":"الجهاز العصبي","text":"راقب التغير لا الرقم فقط؛ تغير مستوى الوعي أو القوة قد يكون أهم من قراءة واحدة."},{"kind":"lesson","title":"Musculoskeletal care","text":"التثبيت والحركة والوقاية من المضاعفات والحفاظ على الجلد والدورة جزء من الرعاية."},{"kind":"lesson","title":"Orthopedic devices","text":"الأجهزة الداعمة تحتاج مراقبة الجلد والدورة والألم والمحاذاة."},{"kind":"lesson","title":"Vision & hearing","text":"عدّل طريقة التواصل والبيئة بما يناسب القدرة الحسية للمريض."},{"kind":"lesson","title":"التأهيل","text":"ضع أهدافًا واقعية مع المريض والفريق لتعزيز الاستقلال والأمان."},{"kind":"scenario","title":"مريض أصبح كلامه غير واضح فجأة","text":"تتعامل مع التغير العصبي الجديد كعلامة مهمة تحتاج تقييمًا وتصعيدًا سريعًا."},{"kind":"scenario","title":"طرف في جبيرة أصبح شديد الألم وباردًا","text":"تعرف أن الألم والدورة والإحساس والحركة مؤشرات تحتاج تقييمًا عاجلًا."},{"kind":"scenario","title":"مريض ضعيف السمع يهز رأسه بالموافقة","text":"لا تفترض أنه فهم؛ واجهه بصريًا وتكلم بوضوح وتأكد من الفهم."},{"kind":"scenario","title":"مريض بعد إصابة يخشى الحركة","text":"تفهم أن الخوف والألم والوظيفة كلها تؤثر في التعافي والتأهيل."}],"chunksEn":[{"kind":"overview","title":"Adult Nursing 3","text":"Adult Nursing 3 focuses on immune, neurologic, musculoskeletal and special-sense problems, with strong attention to function, coordination, mobility, independence and safety."},{"kind":"concept","title":"Inflammation & immunity","text":"Defence mechanisms can protect but may also cause disease when excessive or impaired."},{"kind":"concept","title":"Neurologic assessment","text":"Consciousness, pupils, strength, sensation and speech can change rapidly."},{"kind":"concept","title":"Mobility","text":"Bones, joints, muscles and nerves work as a functional unit."},{"kind":"concept","title":"Pain & function","text":"Pain matters partly because of its effect on mobility, sleep and daily activity."},{"kind":"concept","title":"Special senses","text":"Vision/hearing loss changes communication and safety."},{"kind":"concept","title":"Rehabilitation","text":"Care often aims at restoring or adapting function, not only treating disease."},{"kind":"lesson","title":"Immune disorders","text":"Connect inflammation, hypersensitivity and infection risk."},{"kind":"lesson","title":"Neurologic care","text":"Observe change from baseline."},{"kind":"lesson","title":"Musculoskeletal care","text":"Protect alignment, skin, circulation and mobility."},{"kind":"lesson","title":"Orthopedic devices","text":"Monitor pressure, circulation, pain and positioning."},{"kind":"lesson","title":"Vision/hearing","text":"Adapt the environment and communication."},{"kind":"lesson","title":"Rehabilitation","text":"Set realistic function-centred goals with the patient and team."},{"kind":"scenario","title":"Sudden slurred speech","text":"Treat new neurologic change as an urgent assessment finding."},{"kind":"scenario","title":"A casted limb becomes very painful and cool","text":"Assess circulation, sensation and movement promptly."},{"kind":"scenario","title":"A hearing-impaired patient nods to everything","text":"Do not assume understanding; face the patient and confirm meaning."},{"kind":"scenario","title":"A patient is afraid to move after injury","text":"Pain, fear and function all affect rehabilitation."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"prac3","year":4,"sem":1,"code":"NURS 403ly","nAr":"التدريب التمريضي المكثف 3","nEn":"Intensive Nursing Practicum 3","typeAr":"سريري تمريضي","typeEn":"Clinical nursing","bigAr":"في Practicum 3 يجب أن يظهر تطورك من تنفيذ المهارة إلى إدارة موقف سريري: تقييم سريع، تحديد الأولويات، ربط الأمراض بالأدوية والمختبر، التواصل مع الفريق، والاستجابة للحالات الطارئة مع استمرار التوثيق والسلامة.","bigEn":"Practicum 3 is about managing a clinical situation, not simply performing a skill: rapid assessment, prioritisation, safe interventions, team communication, documentation and escalation.","chunksAr":[{"kind":"overview","title":"التدريب التمريضي المكثف 3","text":"في Practicum 3 يجب أن يظهر تطورك من تنفيذ المهارة إلى إدارة موقف سريري: تقييم سريع، تحديد الأولويات، ربط الأمراض بالأدوية والمختبر، التواصل مع الفريق، والاستجابة للحالات الطارئة مع استمرار التوثيق والسلامة."},{"kind":"concept","title":"Priority & escalation","text":"اعرف متى يكفي الاستمرار بالمراقبة ومتى يحتاج المريض تصعيدًا فوريًا."},{"kind":"concept","title":"Emergency readiness","text":"التحضير قبل وصول الحالة يقلل الفوضى عند بدء الرعاية."},{"kind":"concept","title":"Oncology safety","text":"بعض علاجات الأورام تتطلب احتياطات دقيقة ومراقبة آثار جانبية."},{"kind":"concept","title":"Neuro monitoring","text":"التغيرات العصبية تحتاج مقارنة متكررة بخط أساس."},{"kind":"concept","title":"Blood & fluid therapy","text":"النقل والتعويض يتطلبان تحققًا ومراقبة للاستجابة."},{"kind":"concept","title":"Professional handover","text":"الرعاية المستمرة تحتاج تسليمًا مركزًا وواضحًا، لا سردًا طويلًا للملف."},{"kind":"lesson","title":"Emergency preparation","text":"المعدات والأدوار والاتصال يجب أن تكون واضحة قبل الحاجة إليها."},{"kind":"lesson","title":"Suction & chest physiotherapy","text":"اربط المهارة بحاجة المريض التنفسية وراقب تحمله."},{"kind":"lesson","title":"Blood glucose monitoring","text":"الرقم يحتاج سياقًا: أعراض، غذاء، دواء، توقيت."},{"kind":"lesson","title":"Medication safety","text":"التأكد من الدواء والجرعة والطريق والمريض يظل مهمًا حتى مع الخبرة."},{"kind":"lesson","title":"Intake/output","text":"السوائل ليست أرقامًا منفصلة؛ اربطها بالكلى والدورة والوذمة والمختبر."},{"kind":"lesson","title":"Colostomy care","text":"العناية بالجلد والمخرج والتثقيف وصورة الجسد كلها جزء من الرعاية."},{"kind":"scenario","title":"مريض يصبح أقل استجابة أثناء المناوبة","text":"تقارن بخط الأساس وتفعل الأولويات والتصعيد بدل الانتظار حتى الجولة التالية."},{"kind":"scenario","title":"مريض أورام يعاني تعبًا شديدًا بعد العلاج","text":"تقيّم الحرارة والنزف والترطيب والأعراض المصاحبة بدل اعتبار التعب طبيعيًا تلقائيًا."},{"kind":"scenario","title":"سائل وريدي يتحرك أسرع من المطلوب","text":"تتعامل مع معدل التسريب كجزء من سلامة العلاج لا كتفصيل تقني."},{"kind":"scenario","title":"تسليم مريض مع مشكلات متعددة","text":"ترتب التسليم حسب الحالة الحالية والمخاطر وما يجب متابعته في الساعات القادمة."}],"chunksEn":[{"kind":"overview","title":"Intensive Nursing Practicum 3","text":"Practicum 3 is about managing a clinical situation, not simply performing a skill: rapid assessment, prioritisation, safe interventions, team communication, documentation and escalation."},{"kind":"concept","title":"Priority & escalation","text":"Know when monitoring is enough and when immediate escalation is needed."},{"kind":"concept","title":"Emergency readiness","text":"Preparation reduces delay and confusion."},{"kind":"concept","title":"Oncology safety","text":"Therapies may require specific precautions and adverse-effect monitoring."},{"kind":"concept","title":"Neuro monitoring","text":"Compare repeated findings with baseline."},{"kind":"concept","title":"Blood & fluid therapy","text":"Verification and response monitoring remain essential."},{"kind":"concept","title":"Professional handover","text":"Focus on current status, risk and next actions."},{"kind":"lesson","title":"Emergency preparation","text":"Clarify equipment, roles and communication before the emergency."},{"kind":"lesson","title":"Suction/chest physiotherapy","text":"Link intervention to respiratory assessment."},{"kind":"lesson","title":"Blood glucose","text":"Interpret the number in context of symptoms, food and medicines."},{"kind":"lesson","title":"Medication safety","text":"Experience does not replace verification."},{"kind":"lesson","title":"Intake/output","text":"Connect fluid numbers with circulation, kidneys and edema."},{"kind":"lesson","title":"Colostomy care","text":"Include skin, stoma, education and body-image concerns."},{"kind":"scenario","title":"A patient becomes less responsive","text":"Compare with baseline and escalate rather than waiting."},{"kind":"scenario","title":"Severe fatigue after cancer treatment","text":"Assess associated signs rather than automatically labelling it expected."},{"kind":"scenario","title":"An IV infusion is running too fast","text":"Treat rate as part of medication/fluid safety."},{"kind":"scenario","title":"Handover of a complex patient","text":"Prioritise current condition, risks and what must be followed next."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"research1","year":4,"sem":1,"code":"NURS 404ly","nAr":"البحث العلمي في التمريض 1","nEn":"Nursing Research 1","typeAr":"عام وفق المادة (6) · توصيفه تخصصي","typeEn":"General under Article 6 · course description labels Specialty","bigAr":"Research 1 هو مرحلة بناء البحث قبل جمع البيانات. تبدأ من مشكلة حقيقية قابلة للدراسة، ثم تحولها إلى سؤال وأهداف، تبحث عما نعرفه بالفعل، تختار تصميمًا وعينة وأداة، وتضع خطة أخلاقية ومنهجية يمكن تنفيذها.","bigEn":"Research 1 is the planning phase: define a feasible problem, turn it into questions and objectives, review existing evidence, choose a design/sample/tool and prepare an ethical, workable proposal.","chunksAr":[{"kind":"overview","title":"البحث العلمي في التمريض 1","text":"Research 1 هو مرحلة بناء البحث قبل جمع البيانات. تبدأ من مشكلة حقيقية قابلة للدراسة، ثم تحولها إلى سؤال وأهداف، تبحث عما نعرفه بالفعل، تختار تصميمًا وعينة وأداة، وتضع خطة أخلاقية ومنهجية يمكن تنفيذها."},{"kind":"concept","title":"Research problem","text":"الموضوع واسع، أما المشكلة البحثية فتحدد ما الذي لا نفهمه أو نحتاج قياسه."},{"kind":"concept","title":"Question & objectives","text":"السؤال يحدد ما تبحث عنه، والأهداف تحول السؤال إلى خطوات قابلة للتنفيذ."},{"kind":"concept","title":"Variables","text":"تحديد ما ستقيسه وكيف ستقيسه يمنع الغموض لاحقًا."},{"kind":"concept","title":"Literature review","text":"ليست قائمة ملخصات؛ تجمع الأدلة حول أفكار ومحاور وتبين ما نعرفه وما ينقص."},{"kind":"concept","title":"Design","text":"التصميم يتبع السؤال: وصفي، ارتباطي، تجريبي، نوعي وغيرها."},{"kind":"concept","title":"Ethics","text":"الموافقة والخصوصية وتقليل الضرر والعدالة ليست ملاحق؛ هي جزء من تصميم البحث."},{"kind":"lesson","title":"اختر مشكلة قابلة للدراسة","text":"لا تبدأ بعنوان ضخم؛ حدد مجتمعًا ومتغيرات وسياقًا يمكن الوصول إليه."},{"kind":"lesson","title":"ابنِ سؤالًا جيدًا","text":"السؤال الواضح يمنعك من جمع بيانات لا تحتاجها."},{"kind":"lesson","title":"ابحث بطريقة منظمة","text":"استخدم كلمات مفتاحية ومحاور ودوّن المصدر والنتيجة منذ البداية."},{"kind":"lesson","title":"اختر عينة مناسبة","text":"من تريد أن يمثلهم بحثك؟ ومن يستطيع الدخول فعليًا في الدراسة؟"},{"kind":"lesson","title":"صمم أداة تخدم السؤال","text":"كل سؤال في الاستبيان يجب أن يكون له سبب مرتبط بأهداف الدراسة."},{"kind":"lesson","title":"اكتب المقترح كخطة عمل","text":"المقدمة والمنهج ليسا كتابة للتقييم فقط؛ هما خريطة لما ستفعله في الفصل التالي."},{"kind":"scenario","title":"عنوان بحث جميل لكن لا يمكن قياسه","text":"تتعلم تعديل العنوان والسؤال حتى يصبح المتغير والمجتمع واضحين."},{"kind":"scenario","title":"وجدت 20 مقالة","text":"لا تسردها واحدة واحدة؛ تجمعها حسب موضوعات واتفاقات واختلافات وفجوات."},{"kind":"scenario","title":"استبيان طويل جدًا","text":"تراجع كل بند: هل يجيب عن هدف؟ هل يفهمه المشارك؟ هل نحتاجه فعلًا؟"},{"kind":"scenario","title":"فكرة بحث حساسة","text":"تسأل من البداية عن الخصوصية والموافقة واحتمال الضرر قبل جمع أي بيانات."}],"chunksEn":[{"kind":"overview","title":"Nursing Research 1","text":"Research 1 is the planning phase: define a feasible problem, turn it into questions and objectives, review existing evidence, choose a design/sample/tool and prepare an ethical, workable proposal."},{"kind":"concept","title":"Research problem","text":"A broad topic becomes researchable when the gap and context are specific."},{"kind":"concept","title":"Questions & objectives","text":"They determine what information you actually need."},{"kind":"concept","title":"Variables","text":"Define what will be measured and how."},{"kind":"concept","title":"Literature review","text":"Synthesise themes and evidence rather than listing articles."},{"kind":"concept","title":"Design","text":"Design should follow the question."},{"kind":"concept","title":"Ethics","text":"Consent, privacy, minimising harm and fairness are part of design."},{"kind":"lesson","title":"Choose a feasible problem","text":"Define population, variables and accessible setting."},{"kind":"lesson","title":"Write a focused question","text":"A clear question prevents unnecessary data collection."},{"kind":"lesson","title":"Search systematically","text":"Use keywords/themes and track sources."},{"kind":"lesson","title":"Choose a sample","text":"Consider who you want to represent and who you can actually recruit."},{"kind":"lesson","title":"Build a purposeful instrument","text":"Every item should link to an objective."},{"kind":"lesson","title":"Write the proposal as a plan","text":"The methods section is a map for next semester."},{"kind":"scenario","title":"An impressive title cannot be measured","text":"Refine the variables and population until the question is researchable."},{"kind":"scenario","title":"You found 20 papers","text":"Synthesize by themes, agreements, differences and gaps."},{"kind":"scenario","title":"A questionnaire is too long","text":"Ask whether each item serves an objective."},{"kind":"scenario","title":"The topic is sensitive","text":"Plan consent, privacy and risk minimisation before collecting data."}],"sources":[]},{"id":"comm4","year":4,"sem":2,"code":"LANG 402ly","nAr":"مهارات التواصل 4","nEn":"Communication Skills 4","typeAr":"عام","typeEn":"General","bigAr":"في Communication Skills 4 يصبح الطالب قادرًا على تحويل البيانات المرئية إلى رسالة مفهومة: يقرأ جدولًا أو رسمًا، يختار ما هو مهم، ويعرض النتيجة شفهيًا أو كتابيًا بطريقة دقيقة ومنظمة.","bigEn":"Communication Skills 4 focuses on visual communication and presentation: interpreting tables/figures, turning them into accurate spoken or written messages, and presenting research or professional material clearly.","chunksAr":[{"kind":"overview","title":"مهارات التواصل 4","text":"في Communication Skills 4 يصبح الطالب قادرًا على تحويل البيانات المرئية إلى رسالة مفهومة: يقرأ جدولًا أو رسمًا، يختار ما هو مهم، ويعرض النتيجة شفهيًا أو كتابيًا بطريقة دقيقة ومنظمة."},{"kind":"concept","title":"Visual literacy","text":"افهم ما يقيسه الشكل قبل تفسير الاتجاه."},{"kind":"concept","title":"Table vs figure","text":"الجدول يعطي تفاصيل دقيقة؛ الرسم يساعد على رؤية النمط."},{"kind":"concept","title":"Data story","text":"العرض الجيد يجيب: ما السؤال؟ ماذا نرى؟ لماذا يهم؟"},{"kind":"concept","title":"Slide design","text":"الشريحة تدعم المتحدث ولا تنافسه."},{"kind":"concept","title":"Questions","text":"السؤال بعد العرض فرصة لإيضاح الفكرة لا اختبار شخصي للمتحدث."},{"kind":"concept","title":"Team presentation","text":"العرض الجماعي يحتاج اتساقًا في الرسالة والأدوار والزمن."},{"kind":"lesson","title":"اقرأ العنوان والمحاور","text":"قبل تفسير أي رسم، اعرف المتغير والوحدة والزمن والمجموعة."},{"kind":"lesson","title":"لا تبالغ","text":"ارتفاع بسيط في الرسم قد يبدو ضخمًا حسب المقياس؛ اقرأ الأرقام."},{"kind":"lesson","title":"حول الجدول إلى جملة","text":"استخرج أهم نتيجتين بدل قراءة كل خلية."},{"kind":"lesson","title":"نظم العرض","text":"مقدمة → سؤال → طريقة/مصدر → أهم النتائج → معنى → خاتمة."},{"kind":"lesson","title":"أدر الأسئلة","text":"استمع، أعد الصياغة إذا لزم، أجب باختصار، واعترف بما يحتاج تحققًا."},{"kind":"lesson","title":"تدرب على الزمن","text":"العرض الجيد ينتهي في الوقت دون قفز مذعور على آخر الشرائح."},{"kind":"scenario","title":"عرض نتائج بحث التخرج","text":"تختار أهم النتائج التي تجيب عن السؤال، لا كل جدول أنتجته."},{"kind":"scenario","title":"رسم يوحي بفارق كبير","text":"تتحقق من المحور والقيم قبل وصف الفرق بأنه «كبير»."},{"kind":"scenario","title":"سؤال من اللجنة خارج نطاق الدراسة","text":"توضح حدود الدراسة بدل اختراع استنتاج غير مدعوم."}],"chunksEn":[{"kind":"overview","title":"Communication Skills 4","text":"Communication Skills 4 focuses on visual communication and presentation: interpreting tables/figures, turning them into accurate spoken or written messages, and presenting research or professional material clearly."},{"kind":"concept","title":"Visual literacy","text":"Understand what a visual measures before interpreting it."},{"kind":"concept","title":"Table vs figure","text":"Tables give detail; figures reveal patterns."},{"kind":"concept","title":"Data story","text":"A presentation should answer: what is the question, what do we see, why does it matter?"},{"kind":"concept","title":"Slide design","text":"Slides support the speaker rather than becoming a script."},{"kind":"concept","title":"Questions","text":"Questions are opportunities to clarify."},{"kind":"concept","title":"Team presentation","text":"Shared presentations need consistent roles, timing and message."},{"kind":"lesson","title":"Read title and axes","text":"Identify variables, units, time and groups."},{"kind":"lesson","title":"Do not exaggerate","text":"Check scale and actual values before describing a difference."},{"kind":"lesson","title":"Turn a table into sentences","text":"Select the most important findings."},{"kind":"lesson","title":"Organise presentation","text":"Question → method/source → results → meaning → conclusion."},{"kind":"lesson","title":"Handle questions","text":"Listen, clarify if needed and answer within evidence."},{"kind":"lesson","title":"Practise timing","text":"Finish within time without rushing the final slides."},{"kind":"scenario","title":"Presenting graduation research","text":"Choose findings that answer the research question rather than every table."},{"kind":"scenario","title":"A graph looks dramatic","text":"Check axes and values before calling the difference large."},{"kind":"scenario","title":"A panel asks outside study scope","text":"State the study limit instead of inventing an unsupported conclusion."}],"sources":["who-safety"]},{"id":"leadership","year":4,"sem":2,"code":"NURS 405ly","nAr":"القيادة والإدارة في التمريض","nEn":"Nursing Leadership and Management","typeAr":"تمريضي تخصصي","typeEn":"Nursing specialty","bigAr":"القيادة ليست منصبًا فقط، والإدارة ليست أوراقًا فقط. في التمريض تحتاج أن تنظم العمل والناس والوقت والموارد، تتخذ قرارات، تتواصل، تفوض بأمان، وتتابع الجودة مع بقاء المسؤولية عن المريض في المركز.","bigEn":"Leadership is not only a position, and management is not only paperwork. Nurses organise people, time and resources, make decisions, delegate safely, communicate and monitor quality while keeping patient care central.","chunksAr":[{"kind":"overview","title":"القيادة والإدارة في التمريض","text":"القيادة ليست منصبًا فقط، والإدارة ليست أوراقًا فقط. في التمريض تحتاج أن تنظم العمل والناس والوقت والموارد، تتخذ قرارات، تتواصل، تفوض بأمان، وتتابع الجودة مع بقاء المسؤولية عن المريض في المركز."},{"kind":"concept","title":"Leadership vs management","text":"القيادة تؤثر وتوجه، والإدارة تنظم وتخطط وتراقب؛ وغالبًا يحتاج الممرض إلى الاثنين."},{"kind":"concept","title":"Authority & accountability","text":"يمكن تفويض مهمة، لكن المسؤوليات والحدود يجب أن تبقى واضحة."},{"kind":"concept","title":"Planning","text":"تحديد الهدف والموارد والزمن والمخاطر يسبق التنفيذ الجيد."},{"kind":"concept","title":"Delegation","text":"اختر الشخص المناسب للمهمة المناسبة مع التعليم والمتابعة."},{"kind":"concept","title":"Communication","text":"سوء التواصل قد يحول مشكلة صغيرة إلى خطأ كبير."},{"kind":"concept","title":"Quality & control","text":"المتابعة ليست للوم؛ هي للتأكد من أن العمل يحقق المعيار والهدف."},{"kind":"lesson","title":"أنماط القيادة","text":"الأسلوب قد يتغير حسب الموقف والفريق والوقت والمخاطر."},{"kind":"lesson","title":"إدارة المناوبة","text":"رتب المرضى والمهام والأولويات والمهارات المتاحة قبل توزيع العمل."},{"kind":"lesson","title":"التفويض","text":"لا تفوض تقييمًا أو قرارًا يحتاج مستوى لا يملكه الشخص المكلّف."},{"kind":"lesson","title":"حل المشكلات","text":"عرّف المشكلة أولًا قبل القفز إلى حل."},{"kind":"lesson","title":"إدارة الوقت","text":"الأولوية ليست دائمًا أقرب مهمة زمنيًا؛ قد تكون الحالة الأكثر خطورة."},{"kind":"lesson","title":"اتخاذ القرار","text":"اجمع المعلومة وحدد البدائل والمخاطر ثم قرر وتابع أثر القرار."},{"kind":"scenario","title":"ممرض جديد مثقل بعدة مهام","text":"لا تكتفِ بالقول «نظم وقتك»؛ راجع توزيع العمل والأولوية والدعم المطلوب."},{"kind":"scenario","title":"مهمتان عاجلتان في الوقت نفسه","text":"تحدد الخطر، الموارد، من يمكنه المساعدة وما يحتاج إشرافك المباشر."},{"kind":"scenario","title":"خطأ يتكرر في القسم","text":"تفكر في النظام والتدريب والإجراء والبيئة بدل البحث عن شخص واحد للومه."}],"chunksEn":[{"kind":"overview","title":"Nursing Leadership and Management","text":"Leadership is not only a position, and management is not only paperwork. Nurses organise people, time and resources, make decisions, delegate safely, communicate and monitor quality while keeping patient care central."},{"kind":"concept","title":"Leadership vs management","text":"Leadership influences direction; management plans and organises."},{"kind":"concept","title":"Authority & accountability","text":"Delegation does not erase responsibility or scope."},{"kind":"concept","title":"Planning","text":"Goals, resources, time and risk should be considered before action."},{"kind":"concept","title":"Delegation","text":"Match the task, patient and staff member, then supervise appropriately."},{"kind":"concept","title":"Communication","text":"Poor communication can turn small problems into safety events."},{"kind":"concept","title":"Quality/control","text":"Monitoring helps ensure standards and goals are met."},{"kind":"lesson","title":"Leadership styles","text":"Style may need to change with context and team needs."},{"kind":"lesson","title":"Shift organisation","text":"Review patients, priorities and available skills before assigning work."},{"kind":"lesson","title":"Delegation","text":"Do not delegate assessment/judgement beyond the delegatee's scope."},{"kind":"lesson","title":"Problem solving","text":"Define the problem before choosing a solution."},{"kind":"lesson","title":"Time management","text":"Priority is not always the task that is due first."},{"kind":"lesson","title":"Decision making","text":"Gather information, compare options/risks, act and evaluate."},{"kind":"scenario","title":"A new nurse is overloaded","text":"Review workload distribution and support rather than simply saying 'manage your time'."},{"kind":"scenario","title":"Two urgent needs occur together","text":"Compare risk, resources and what requires your direct attention."},{"kind":"scenario","title":"The same error keeps recurring","text":"Look at system, workflow, training and policy—not only individual blame."}],"sources":["openrn-management","who-safety"]},{"id":"prac4","year":4,"sem":2,"code":"NURS 406ly","nAr":"التدريب التمريضي المكثف 4","nEn":"Intensive Nursing Practicum 4","typeAr":"سريري تمريضي","typeEn":"Clinical nursing","bigAr":"هذا التدريب هو جسر بين «طالب ينفذ مهارة» و«خريج يشارك في إدارة رعاية مجموعة من المرضى». التركيز على التفكير السريري، ترتيب العمل، القيادة تحت الإشراف، رعاية المسنين والحالات الحادة والحرجة، والتواصل مع الفريق.","bigEn":"Practicum 4 bridges student performance and professional nursing responsibility. It emphasises clinical prioritisation, supervision, leadership, elderly/critical care and coordination of care for groups of patients.","chunksAr":[{"kind":"overview","title":"التدريب التمريضي المكثف 4","text":"هذا التدريب هو جسر بين «طالب ينفذ مهارة» و«خريج يشارك في إدارة رعاية مجموعة من المرضى». التركيز على التفكير السريري، ترتيب العمل، القيادة تحت الإشراف، رعاية المسنين والحالات الحادة والحرجة، والتواصل مع الفريق."},{"kind":"concept","title":"Assignment","text":"ابدأ بفهم المرضى ومسؤولياتك قبل الدخول في المهام."},{"kind":"concept","title":"Head-nurse thinking","text":"انظر إلى القسم كله: الحالات، الطاقم، الأسرة، المخزون، السلامة والتدفق."},{"kind":"concept","title":"Prioritisation","text":"المريض الأخطر قد يحتاجك قبل المهمة الأسهل أو الأسرع."},{"kind":"concept","title":"Delegation & supervision","text":"التفويض يحتاج وضوحًا وتحققًا ومتابعة."},{"kind":"concept","title":"Chronic & elderly care","text":"الهدف قد يكون الحفاظ على الوظيفة والاستقلال ومنع المضاعفات."},{"kind":"concept","title":"Critical skills","text":"الشفط والعلاج التنفسي والسوائل والدم والجلوكوز تحتاج فهمًا ومراقبة لا مجرد تنفيذ."},{"kind":"lesson","title":"ابدأ المناوبة بخطة","text":"راجع المرضى والأوامر والمخاطر والأولويات."},{"kind":"lesson","title":"وزع العمل بوعي","text":"راعي مهارة كل فرد وحالة المريض."},{"kind":"lesson","title":"راقب التقدم","text":"لا تنتظر نهاية المناوبة لتكتشف أن مهمة حرجة لم تُنجز."},{"kind":"lesson","title":"Communicate changes","text":"أي تغير مهم يجب أن يصل للشخص المناسب في الوقت المناسب."},{"kind":"lesson","title":"Document","text":"التوثيق جزء من الرعاية والتنسيق والمساءلة."},{"kind":"lesson","title":"Reflect","text":"بعد الموقف، اسأل ما الذي نجح وما الذي يجب تحسينه في المرة القادمة."},{"kind":"scenario","title":"أنت مسؤول عن عدة مرضى","text":"تضع قائمة أولوية مرنة وتتوقع أنها ستتغير عندما تتغير الحالات."},{"kind":"scenario","title":"تم تفويض مهمة ولم تُنفذ","text":"لا تفترض أنها تمت؛ المتابعة جزء من التفويض."},{"kind":"scenario","title":"مريض مسن يبدأ ارتباكًا جديدًا","text":"لا تنسبه للعمر تلقائيًا؛ التغير الحاد يحتاج تقييمًا."},{"kind":"scenario","title":"مريض COPD يحتاج شفطًا أو علاجًا تنفسيًا","text":"تربط الإجراء بالتقييم قبل وبعد وتراقب التحمل."}],"chunksEn":[{"kind":"overview","title":"Intensive Nursing Practicum 4","text":"Practicum 4 bridges student performance and professional nursing responsibility. It emphasises clinical prioritisation, supervision, leadership, elderly/critical care and coordination of care for groups of patients."},{"kind":"concept","title":"Assignment","text":"Understand patients and responsibilities before starting tasks."},{"kind":"concept","title":"Head-nurse thinking","text":"See the whole unit: patients, staff, beds, resources and safety."},{"kind":"concept","title":"Prioritisation","text":"The highest-risk patient may need attention before the easiest task."},{"kind":"concept","title":"Delegation","text":"Give clear instructions and follow up."},{"kind":"concept","title":"Elderly/chronic care","text":"Protect function, independence and complication prevention."},{"kind":"concept","title":"Critical skills","text":"Respiratory care, feeding, blood glucose, IV therapy and transfusion require monitoring."},{"kind":"lesson","title":"Start with a plan","text":"Review patients, orders, risks and priorities."},{"kind":"lesson","title":"Allocate safely","text":"Match staff competence to patient needs."},{"kind":"lesson","title":"Follow progress","text":"Do not wait until shift end to discover a critical task was missed."},{"kind":"lesson","title":"Communicate changes","text":"Important changes must reach the right person promptly."},{"kind":"lesson","title":"Document","text":"Documentation supports continuity and accountability."},{"kind":"lesson","title":"Reflect","text":"Identify what worked and what should change next time."},{"kind":"scenario","title":"You are responsible for several patients","text":"Build a flexible priority list and update it as conditions change."},{"kind":"scenario","title":"A delegated task was not completed","text":"Follow-up is part of delegation."},{"kind":"scenario","title":"An older patient becomes newly confused","text":"Do not assume it is simply age-related."},{"kind":"scenario","title":"A COPD patient needs respiratory care","text":"Link the intervention to pre/post assessment and tolerance."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"elderly","year":4,"sem":2,"code":"NURS 407ly","nAr":"رعاية المسنين","nEn":"Care of the Elderly","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"الشيخوخة ليست مرضًا. الهدف أن تميز بين التغير الطبيعي المرتبط بالعمر وبين المرض، وأن تحافظ على استقلال الشخص ووظيفته وكرامته قدر الإمكان مع الانتباه لتعدد الأمراض والأدوية والمخاطر.","bigEn":"Ageing is not a disease. Nursing care distinguishes expected age-related change from illness while protecting function, independence, dignity and safety in people who may have multiple conditions and medicines.","chunksAr":[{"kind":"overview","title":"رعاية المسنين","text":"الشيخوخة ليست مرضًا. الهدف أن تميز بين التغير الطبيعي المرتبط بالعمر وبين المرض، وأن تحافظ على استقلال الشخص ووظيفته وكرامته قدر الإمكان مع الانتباه لتعدد الأمراض والأدوية والمخاطر."},{"kind":"concept","title":"Normal aging vs disease","text":"بطء معين قد يكون متوقعًا، لكن التغير المفاجئ أو الشديد ليس «طبيعيًا» لمجرد العمر."},{"kind":"concept","title":"Function","text":"القدرة على الأكل والحركة واللبس والتواصل قد تكون أهم من تشخيص منفرد."},{"kind":"concept","title":"Polypharmacy","text":"كثرة الأدوية ترفع خطر التداخل والآثار الجانبية والارتباك والسقوط."},{"kind":"concept","title":"Falls","text":"السقوط ليس حادثًا بسيطًا؛ له عوامل دوائية وحسية وبيئية وحركية."},{"kind":"concept","title":"Cognition","text":"فرّق بين decline مزمن وdelirium حاد قدر الإمكان، لأن التوقيت والمسار مهمان."},{"kind":"concept","title":"Dignity","text":"المسن بالغ له تفضيلات وحقوق؛ لا تتحدث عنه وكأنه غير موجود."},{"kind":"lesson","title":"التقييم الوظيفي","text":"اسأل ماذا يستطيع أن يفعل وحده وما الذي يحتاج مساعدة فيه."},{"kind":"lesson","title":"التغذية والترطيب","text":"قلة الشهية أو العطش أو صعوبة المضغ قد تؤثر بسرعة في الحالة."},{"kind":"lesson","title":"الجلد والحركة","text":"قلة الحركة تزيد مخاطر الضغط والضعف والجلطات ومشكلات التنفس."},{"kind":"lesson","title":"الأدوية","text":"راجع ما يستخدمه فعليًا، لا ما هو مكتوب فقط."},{"kind":"lesson","title":"التواصل","text":"امنح وقتًا إضافيًا، حسّن السمع والرؤية، وتجنب مخاطبته بطريقة طفولية."},{"kind":"lesson","title":"الأسرة والبيئة","text":"المنزل والدعم ومقدم الرعاية عوامل مهمة في الخروج الآمن."},{"kind":"scenario","title":"مسن أصبح مرتبكًا منذ صباح اليوم","text":"لا تفترض أنه «خرف»؛ الارتباك الحاد قد يرتبط بعدوى أو دواء أو سوائل أو ألم وغيرها."},{"kind":"scenario","title":"مريض يسقط للمرة الثانية","text":"تفحص البيئة والدواء والضغط والحركة والبصر والحاجة للمساعدة."},{"kind":"scenario","title":"المرافق يجيب عن كل الأسئلة","text":"تتوجه للمريض نفسه أولًا ما دام قادرًا على المشاركة."},{"kind":"scenario","title":"مريض يأخذ أدوية من أكثر من طبيب","text":"تدرك أهمية medication reconciliation ومراجعة التكرار والتداخلات."}],"chunksEn":[{"kind":"overview","title":"Care of the Elderly","text":"Ageing is not a disease. Nursing care distinguishes expected age-related change from illness while protecting function, independence, dignity and safety in people who may have multiple conditions and medicines."},{"kind":"concept","title":"Normal ageing vs disease","text":"Sudden or severe change should not be dismissed as 'just age'."},{"kind":"concept","title":"Function","text":"Ability to eat, move, dress and communicate may matter more than one diagnosis."},{"kind":"concept","title":"Polypharmacy","text":"Multiple medicines increase interaction and adverse-effect risk."},{"kind":"concept","title":"Falls","text":"Falls can reflect medicines, vision, blood pressure, mobility and environment."},{"kind":"concept","title":"Cognition","text":"Timing helps distinguish chronic decline from acute delirium."},{"kind":"concept","title":"Dignity","text":"Speak to the older person directly and respect preferences."},{"kind":"lesson","title":"Functional assessment","text":"Identify what the person can do independently."},{"kind":"lesson","title":"Nutrition/hydration","text":"Appetite, thirst, dentition and swallowing affect health."},{"kind":"lesson","title":"Skin/mobility","text":"Immobility raises risk of pressure injury and deconditioning."},{"kind":"lesson","title":"Medicines","text":"Reconcile what the person actually takes."},{"kind":"lesson","title":"Communication","text":"Allow time and optimise hearing/vision without infantilising."},{"kind":"lesson","title":"Home/family","text":"Support and environment influence safe discharge."},{"kind":"scenario","title":"New confusion since this morning","text":"Think acute delirium and possible causes rather than automatically dementia."},{"kind":"scenario","title":"Repeated falls","text":"Assess environment, medicines, blood pressure, vision and mobility."},{"kind":"scenario","title":"A relative answers every question","text":"Address the patient first when they can participate."},{"kind":"scenario","title":"Medicines from several prescribers","text":"Medication reconciliation becomes important."}],"sources":["openrn-fund","openrn-skills"]},{"id":"critical","year":4,"sem":2,"code":"NURS 408ly","nAr":"تمريض العناية الحرجة","nEn":"Critical Care Nursing","typeAr":"تمريضي","typeEn":"Nursing","bigAr":"العناية الحرجة هي فن اكتشاف التغير قبل أن يصبح انهيارًا. المريض الحرج قد تتغير حالته خلال دقائق، لذلك تحتاج إلى فهم الوظائف الحيوية، ترتيب الأولويات، قراءة الاتجاهات، استخدام الأجهزة كأدوات للمراقبة وليس بديلًا عن تقييم المريض.","bigEn":"Critical care is the discipline of detecting deterioration before collapse. Critically ill patients can change quickly, so nursing relies on physiology, priorities, trends, repeated assessment and safe use of monitoring/support technology.","chunksAr":[{"kind":"overview","title":"تمريض العناية الحرجة","text":"العناية الحرجة هي فن اكتشاف التغير قبل أن يصبح انهيارًا. المريض الحرج قد تتغير حالته خلال دقائق، لذلك تحتاج إلى فهم الوظائف الحيوية، ترتيب الأولويات، قراءة الاتجاهات، استخدام الأجهزة كأدوات للمراقبة وليس بديلًا عن تقييم المريض."},{"kind":"concept","title":"ABCDE","text":"إطار سريع لترتيب ما يهدد الحياة: airway, breathing, circulation, disability, exposure."},{"kind":"concept","title":"Trend not single number","text":"اتجاه الضغط والنبض والبول والوعي أهم أحيانًا من قراءة واحدة."},{"kind":"concept","title":"Shock & perfusion","text":"المشكلة ليست الضغط فقط؛ السؤال هل الأنسجة تحصل على دم وأكسجين كافيين؟"},{"kind":"concept","title":"Respiratory failure","text":"الأكسجة والتهوية مختلفتان وقد تحتاجان مراقبة وتدخلات مختلفة."},{"kind":"concept","title":"Neurologic deterioration","text":"الوعي والحدقات والقوة والضغط داخل الجمجمة قد تتغير بسرعة."},{"kind":"concept","title":"Multisystem care","text":"فشل عضو واحد قد يؤثر في الكلى والرئتين والقلب والدماغ والاستقلاب."},{"kind":"lesson","title":"Cardiac failure/MI","text":"اربط التروية والأكسجين والضغط والاحتقان والاستجابة للعلاج."},{"kind":"lesson","title":"Respiratory failure","text":"راقب العمل التنفسي والغازات والأكسجة والاستجابة للأكسجين أو الدعم."},{"kind":"lesson","title":"Renal failure","text":"السوائل والبوتاسيوم والحموضة والبول تصبح قضايا حرجة."},{"kind":"lesson","title":"Raised ICP & stroke","text":"التغير العصبي الجديد يحتاج سرعة ودقة في التقييم."},{"kind":"lesson","title":"DKA/HHS","text":"الجلوكوز العالي يرتبط بالسوائل والشوارد والحموضة والوعي."},{"kind":"lesson","title":"Machines","text":"المونيتور والventilator والمضخات تعطي بيانات وتنفذ دعمًا؛ الممرض يظل مسؤولًا عن تقييم الإنسان."},{"kind":"scenario","title":"الضغط يبدو مقبولًا لكن البول ينخفض والوعي يتغير","text":"تتعلم ألا تطمئن لرقم واحد إذا كانت بقية مؤشرات التروية تتدهور."},{"kind":"scenario","title":"Alarm من monitor","text":"تنظر إلى المريض أولًا ثم تتحقق من الجهاز والإشارة، لا تسكت الإنذار تلقائيًا."},{"kind":"scenario","title":"مريض على أكسجين يزداد تعبًا","text":"تقيم العمل التنفسي والوعي والأكسجة وتستعد للتصعيد بدل زيادة الأكسجين عشوائيًا."},{"kind":"scenario","title":"مريض سكري شديد الجفاف والتنفس غير طبيعي","text":"تربط الاستقلاب والسوائل والشوارد والحمض/القاعدة كصورة واحدة."}],"chunksEn":[{"kind":"overview","title":"Critical Care Nursing","text":"Critical care is the discipline of detecting deterioration before collapse. Critically ill patients can change quickly, so nursing relies on physiology, priorities, trends, repeated assessment and safe use of monitoring/support technology."},{"kind":"concept","title":"ABCDE","text":"A structured approach to immediate threats."},{"kind":"concept","title":"Trend vs one number","text":"Patterns in BP, urine, consciousness and vital signs matter."},{"kind":"concept","title":"Shock & perfusion","text":"The question is whether tissues receive enough blood and oxygen."},{"kind":"concept","title":"Respiratory failure","text":"Oxygenation and ventilation are related but distinct."},{"kind":"concept","title":"Neurologic deterioration","text":"Consciousness, pupils and strength can change rapidly."},{"kind":"concept","title":"Multisystem failure","text":"Dysfunction in one organ can affect multiple systems."},{"kind":"lesson","title":"Cardiac failure/MI","text":"Connect perfusion, oxygen demand and congestion."},{"kind":"lesson","title":"Respiratory failure","text":"Assess work of breathing, gases and response to support."},{"kind":"lesson","title":"Renal failure","text":"Fluid, potassium, acid-base and urine become critical."},{"kind":"lesson","title":"Raised ICP/stroke","text":"New neurologic change requires rapid focused assessment."},{"kind":"lesson","title":"DKA/HHS","text":"Connect glucose with dehydration, electrolytes and consciousness."},{"kind":"lesson","title":"Machines","text":"Monitors and ventilators support care; they do not replace patient assessment."},{"kind":"scenario","title":"BP looks acceptable but urine and consciousness worsen","text":"Do not rely on a single reassuring number."},{"kind":"scenario","title":"A monitor alarm sounds","text":"Look at the patient first, then verify equipment and signal."},{"kind":"scenario","title":"A patient on oxygen becomes more fatigued","text":"Assess work of breathing and consciousness and escalate appropriately."},{"kind":"scenario","title":"Severe hyperglycaemia with dehydration","text":"Think glucose, fluid, electrolytes and acid-base together."}],"sources":["openrn-fund","openrn-skills","openrn-advanced"]},{"id":"research2","year":4,"sem":2,"code":"NURS 409ly","nAr":"البحث العلمي في التمريض 2","nEn":"Nursing Research 2","typeAr":"عام وفق المادة (6) · توصيفه تخصصي","typeEn":"General under Article 6 · course description labels Specialty","bigAr":"Research 2 هو مرحلة التنفيذ: تجمع البيانات بالطريقة التي خططت لها، تنظفها وتحللها، تعرض النتائج دون تحريف، تفسرها في ضوء السؤال والأدلة السابقة، ثم تكتب استنتاجات وتوصيات لا تتجاوز ما تسمح به البيانات.","bigEn":"Research 2 is the execution phase: collect, clean and analyse data, present results honestly, interpret them in relation to the research question and previous evidence, then draw conclusions and recommendations that do not exceed the data.","chunksAr":[{"kind":"overview","title":"البحث العلمي في التمريض 2","text":"Research 2 هو مرحلة التنفيذ: تجمع البيانات بالطريقة التي خططت لها، تنظفها وتحللها، تعرض النتائج دون تحريف، تفسرها في ضوء السؤال والأدلة السابقة، ثم تكتب استنتاجات وتوصيات لا تتجاوز ما تسمح به البيانات."},{"kind":"concept","title":"Data integrity","text":"البيانات يجب أن تبقى كما جُمعت، مع توثيق التنظيف والتعديلات."},{"kind":"concept","title":"Sampling reality","text":"العينة التي شاركت فعليًا قد تختلف عن الخطة، وهذا يؤثر في التفسير."},{"kind":"concept","title":"Analysis","text":"اختر التحليل الذي يناسب السؤال ونوع البيانات بدل البحث عن اختبار يعطي نتيجة مرغوبة."},{"kind":"concept","title":"Results vs discussion","text":"النتائج تقول ماذا وجدت؛ المناقشة تفسر ما قد يعنيه ذلك."},{"kind":"concept","title":"Conclusion","text":"لا تحول الارتباط إلى سبب ولا تعمم أكثر من قدرة التصميم والعينة."},{"kind":"concept","title":"Dissemination","text":"البحث لا ينتهي بالدرجة؛ الهدف إيصال المعرفة بطريقة يفهمها المختصون ويستفيد منها الميدان."},{"kind":"lesson","title":"قبل الجمع","text":"تأكد من الموافقات والأداة وخطة حفظ البيانات وتدريب الفريق."},{"kind":"lesson","title":"أثناء الجمع","text":"استخدم نفس الإجراء مع الجميع قدر الإمكان وسجل المشكلات."},{"kind":"lesson","title":"تنظيف البيانات","text":"ابحث عن القيم الناقصة والتكرار والأخطاء قبل التحليل."},{"kind":"lesson","title":"عرض النتائج","text":"استخدم جدولًا أو شكلًا عندما يساعد القارئ على رؤية النمط، لا لمجرد الزينة."},{"kind":"lesson","title":"المناقشة","text":"قارن بالدراسات السابقة وقدم تفسيرات محتملة وحدودًا واضحة."},{"kind":"lesson","title":"الدفاع","text":"اعرف سؤال بحثك وتصميمك وسبب كل قرار؛ لا تحفظ الشرائح فقط."},{"kind":"scenario","title":"نتيجة لا تدعم توقعك","text":"لا تغير التحليل لإجبارها؛ التقرير الصادق للنتيجة هو البحث الصحيح."},{"kind":"scenario","title":"نسبة استجابة منخفضة","text":"تذكر أثر ذلك في التمثيل والتعميم واذكره ضمن الحدود."},{"kind":"scenario","title":"لجنة تسأل لماذا اخترتم هذا الاختبار","text":"تجيب من نوع البيانات والسؤال، لا لأن البرنامج أعطاه تلقائيًا."},{"kind":"scenario","title":"توصية كبيرة من عينة صغيرة","text":"تتعلم جعل التوصية متناسبة مع قوة الدليل الذي لديك."}],"chunksEn":[{"kind":"overview","title":"Nursing Research 2","text":"Research 2 is the execution phase: collect, clean and analyse data, present results honestly, interpret them in relation to the research question and previous evidence, then draw conclusions and recommendations that do not exceed the data."},{"kind":"concept","title":"Data integrity","text":"Preserve original data and document cleaning decisions."},{"kind":"concept","title":"Sampling reality","text":"The achieved sample affects interpretation."},{"kind":"concept","title":"Analysis","text":"Choose methods that fit the question and data."},{"kind":"concept","title":"Results vs discussion","text":"Results report findings; discussion interprets them."},{"kind":"concept","title":"Conclusion","text":"Do not convert association into causation or overgeneralise."},{"kind":"concept","title":"Dissemination","text":"Research should be communicated clearly to professional audiences."},{"kind":"lesson","title":"Before collection","text":"Confirm approvals, instrument and data-storage plan."},{"kind":"lesson","title":"During collection","text":"Use consistent procedures and record deviations."},{"kind":"lesson","title":"Clean data","text":"Check missing values, duplicates and entry errors."},{"kind":"lesson","title":"Present results","text":"Use tables/figures when they improve understanding."},{"kind":"lesson","title":"Discuss findings","text":"Compare with prior literature and state limitations."},{"kind":"lesson","title":"Defense","text":"Know why you made each methodological decision."},{"kind":"scenario","title":"A result does not support your expectation","text":"Report it honestly rather than forcing the analysis."},{"kind":"scenario","title":"Response rate is low","text":"Discuss its effect on representation/generalisation."},{"kind":"scenario","title":"The panel asks why you chose a test","text":"Answer from data type and research question."},{"kind":"scenario","title":"A strong recommendation is based on a small sample","text":"Scale recommendations to the strength of evidence."}],"sources":[]}];
